window.ANSWER_TERMS = {"alfa-helix":{"match":"alfa-helices|alfa-helixen|alfa-helixes|alfa-helix|alfa helices|alfa helix|alpha-helices|alpha-helixes|alpha-helix|alpha helices|alpha helix|α-helices|α-helix","title":"Alfa-helix","short":"De alfa-helix is een veelvoorkomende secundaire eiwitstructuur: een rechtsdraaiende spiraal die bij elkaar wordt gehouden door waterstofbruggen in de ruggengraat van het eiwit.","definition":"<p>De <strong>alfa-helix</strong> is een element van de <em>secundaire</em> eiwitstructuur: een rechtsdraaiende spiraal met ongeveer 3,6 aminozuren per winding. Hij wordt gestabiliseerd door waterstofbruggen tussen de C=O van aminozuur <em>n</em> en de N–H van aminozuur <em>n+4</em> — dus tussen de <em>ruggengraat</em>-atomen, niet tussen de zijketens.</p><p>De zijketens steken naar buiten: hydrofiel richting het water, hydrofoob naar de kern van het eiwit. <em>Proline</em> mist de N–H en knikt de keten — de klassieke “helix-breaker”; ook glycine destabiliseert. Voorbeelden: keratine, collageen (drie helices ineengedraaid) en de normale vorm van het prioneiwit PrP<sup>C</sup>.</p>","image_url":"","wiki_title":"Alpha helix"},"beta-sheet":{"match":"beta-sheets|bèta-sheets|β-sheets|beta sheets|beta-sheet|bèta-sheet|β-sheet|beta sheet|bètaplaat|beta-plaatstructuur","title":"Beta-sheet","short":"Een beta-sheet is de tweede grote secundaire eiwitstructuur: uitgestrekte ketens die naast elkaar liggen als een geplooid vel, verbonden door waterstofbruggen.","definition":"<p>De <strong>beta-sheet</strong> (bèta-plaatstructuur) bestaat uit uitgestrekte polypeptideketens (β-strengen) die náást elkaar liggen en met waterstofbruggen aan elkaar vastzitten — parallel of antiparallel. Het geheel is licht geplooid, als een harmonicavel.</p><p>De zijketens wijzen afwisselend boven en onder het vlak. Liggen daar vooral <em>hydrofobe</em> zijketens, dan plakken beta-sheets van verschillende eiwitmoleculen aan elkaar: dat is precies wat er misgaat bij <em>amyloïdvorming</em> — bij prionziekten (PrP<sup>Sc</sup>), de ziekte van Alzheimer en systemische amyloïdose. Het neerslag is dan onoplosbaar en vrijwel niet meer af te breken.</p>","image_url":"","wiki_title":"Beta sheet"},"ATP":{"match":"adenosinetrifosfaat|adenosine trifosfaat|adenosine-trifosfaat|ATP","title":"ATP (adenosinetrifosfaat)","short":"ATP is de energiemunt van de cel: bij afsplitsing van de derde fosfaatgroep komt energie vrij die transport, contractie en biosynthese aandrijft.","definition":"<p><strong>ATP</strong> (adenosinetrifosfaat) bestaat uit adenine, ribose en drie fosfaatgroepen. Hydrolyse van de eindstandige fosfaatbinding (ATP → ADP + P<sub>i</sub>) levert ongeveer 30 kJ/mol — genoeg om ongunstige reacties te koppelen aan een gunstige: spiercontractie, de Na⁺/K⁺-ATPase, en de opbouw van eiwitten, vetten en DNA.</p><p>Het meeste ATP komt uit de <em>oxidatieve fosforylering</em> in het mitochondrion: de elektronentransportketen pompt protonen naar de intermembraanruimte, en ATP-synthase laat die protonengradiënt terugstromen en maakt daarmee ATP (chemiosmose). Glycolyse en de citroenzuurcyclus leveren daarnaast rechtstreeks een kleine hoeveelheid.</p><p>De cel slaat ATP nauwelijks op — de voorraad gaat in seconden — dus productie en verbruik zijn strak gekoppeld: veel ADP versnelt de verbranding, overmaat ATP remt die af.</p>","image_url":"","wiki_titles":["Adenosine triphosphate","ATP synthase"]},"lysosoom":{"title":"Lysosoom","short":"Membraanblaasje vol verterende enzymen dat afvalstoffen en opgenomen materiaal afbreekt.","definition":"<p>Het <b>lysosoom</b> is een blaasje omgeven door één membraan, gevuld met hydrolytische enzymen die bij een lage pH (~4,5) macromoleculen afbreken. Het is de 'maag' van de cel.</p><p>Het verteert materiaal dat via endocytose of fagocytose is opgenomen en ruimt via autofagie versleten celonderdelen op.</p>","image_url":"","wiki_title":"Lysosome","match":"lysosoom|lysosomen"},"mitochondrion":{"title":"Mitochondrion","short":"De 'energiecentrale' van de cel; produceert ATP via de citroenzuurcyclus en oxidatieve fosforylering.","definition":"<p>Het <b>mitochondrion</b> heeft een dubbele membraan; de binnenste is sterk geplooid (cristae). Hier vinden de citroenzuurcyclus en de elektronentransportketen plaats.</p><p>Zo levert het mitochondrion het grootste deel van de ATP van de cel. Het bevat eigen DNA en kan zich delen.</p>","image_url":"","wiki_title":"Mitochondrion","match":"mitochondrion|mitochondriën|mitochondrien|mitochondria|mitochondrium"},"keratine":{"title":"Keratine","short":"Vezelig structuureiwit (intermediair filament) dat opperhuid, haren en nagels stevigheid en waterbestendigheid geeft.","definition":"<p><b>Keratine</b> is een taai, onoplosbaar structuureiwit uit de groep intermediaire filamenten. Keratinocyten maken het aan terwijl ze naar de oppervlakte schuiven.</p><p>In het stratum corneum vormen dode, met keratine gevulde cellen een waterafstotende barrière. Keratine is ook het hoofdbestanddeel van haar en nagels.</p>","image_url":"","wiki_title":"Keratin","match":"keratine"},"desmosoom":{"title":"Desmosoom","short":"Sterke celverbinding (macula adherens) die naburige keratinocyten aan elkaar koppelt voor mechanische stevigheid.","definition":"<p>Een <b>desmosoom</b> is een knoopvormige adhesieverbinding die twee cellen stevig verbindt via cadherines (desmogleïne en desmocolline), verankerd aan het keratine-cytoskelet (tonofilamenten).</p><p>Desmosomen geven weefsel dat aan trekkracht blootstaat, zoals huid, zijn stevigheid. Bij pemphigus vulgaris worden ze door auto-antistoffen aangevallen.</p>","image_url":"","wiki_title":"Desmosome","match":"desmosoom|desmosomen"},"autocriene signalering":{"title":"Autocriene signalering","short":"De cel scheidt een signaalstof af waarop hij zélf reageert.","definition":"<p>Bij <b>autocriene signalering</b> geeft een cel een signaalmolecuul af dat bindt aan receptoren op diezelfde cel.</p><p>De cel stuurt dus zichzelf. Dit komt onder meer voor bij groeiregulatie en bij tumorcellen die hun eigen groei aanjagen.</p>","image_url":"","wiki_title":"Autocrine signaling","match":"autocriene signalering|autocrien|autocriene secretie|autocriene celsignalering"},"paracriene signalering":{"title":"Paracriene signalering","short":"Een cel scheidt een signaalstof af die alleen op nabijgelegen cellen inwerkt.","definition":"<p>Bij <b>paracriene signalering</b> werkt het afgegeven signaalmolecuul lokaal in op cellen in de directe omgeving.</p><p>De stof wordt snel afgebroken of opgenomen, zodat het effect beperkt blijft tot de buurt. Voorbeeld: histamine bij ontsteking.</p>","image_url":"","wiki_title":"Paracrine signaling","match":"paracriene signalering|paracrien|paracriene secretie|paracriene celsignalering"},"endocriene signalering":{"title":"Endocriene signalering","short":"Klieren geven hormonen af aan het bloed, dat ze naar verre doelorganen vervoert.","definition":"<p>Bij <b>endocriene signalering</b> scheiden endocriene klieren hormonen rechtstreeks in de bloedbaan uit.</p><p>Via het bloed bereiken de hormonen doelcellen elders in het lichaam die de bijbehorende receptor dragen. Het effect is trager maar wijdverbreid.</p>","image_url":"","wiki_title":"Endocrine system","match":"endocriene signalering|endocrien|endocriene secretie|endocriene celsignalering"},"glycoproteine":{"title":"Glycoproteïne","short":"Eiwit met aangehechte suikerketens; veel membraan- en secretie-eiwitten zijn geglycosyleerd.","definition":"<p>Een <b>glycoproteïne</b> is een eiwit waaraan tijdens de rijping in ER en Golgi suikerketens zijn gekoppeld (glycosylering).</p><p>Ze zitten veel in de celmembraan en in secreten en spelen een rol bij herkenning, adhesie en bescherming.</p>","image_url":"","wiki_title":"Glycoprotein","match":"glycoproteïne|glycoproteine|glycoproteïnen|glycoproteinen|glycoproteinen"},"proteoglycaan":{"title":"Proteoglycaan","short":"Eiwit met lange glycosaminoglycaan-ketens; waterbindend hoofdbestanddeel van de extracellulaire matrix.","definition":"<p>Een <b>proteoglycaan</b> bestaat uit een kerneiwit met glycosaminoglycaan-ketens (zoals chondroïtinesulfaat). Door hun negatieve lading trekken ze veel water aan.</p><p>Ze vormen een gel-achtige grondsubstantie in bindweefsel en kraakbeen die druk opvangt en waarin vezels zijn ingebed.</p>","image_url":"","wiki_title":"Proteoglycan","match":"proteoglycaan|proteoglycanen"},"fagocytose":{"title":"Fagocytose","short":"Het 'opeten' van grote deeltjes of hele cellen (zoals bacteriën) door een cel via insluiting in een fagosoom.","definition":"<p><b>Fagocytose</b> is een vorm van endocytose waarbij een cel grote deeltjes omsluit, zoals bacteriën, celresten of stofdeeltjes.</p><p>Het gevormde fagosoom versmelt met een lysosoom, waarna de inhoud wordt verteerd. Neutrofielen en macrofagen zijn de belangrijkste fagocyten.</p>","image_url":"","wiki_title":"Phagocytosis","match":"fagocytose"},"apoptose":{"title":"Apoptose","short":"Geprogrammeerde celdood: een geordend 'zelfmoordprogramma' dat de cel netjes opruimt zonder ontsteking.","definition":"<p><b>Apoptose</b> is gecontroleerde celdood. De cel krimpt, het DNA wordt in stukken geknipt en de cel valt uiteen in nette blaasjes (apoptotic bodies).</p><p>Macrofagen ruimen die op zonder ontstekingsreactie. Het is essentieel voor ontwikkeling en het verwijderen van beschadigde cellen.</p>","image_url":"","wiki_title":"Apoptosis","match":"apoptose"},"necrose":{"title":"Necrose","short":"Ongecontroleerde celdood door schade, waarbij de cel opzwelt, openbarst en een ontstekingsreactie uitlokt.","definition":"<p><b>Necrose</b> is celdood door acute schade (zuurstoftekort, toxinen, trauma). De cel zwelt op en de membraan scheurt.</p><p>De vrijkomende celinhoud lokt een ontstekingsreactie uit — anders dan bij de 'nette' apoptose.</p>","image_url":"","wiki_title":"Necrosis","match":"necrose"},"nadh":{"title":"NADH","short":"Elektronendrager die de citroenzuurcyclus 'oplaadt' en zijn elektronen aan de elektronentransportketen levert.","definition":"<p><b>NADH</b> is de gereduceerde vorm van NAD⁺. Het ontstaat als tijdens glycolyse en citroenzuurcyclus elektronen worden opgenomen.</p><p>In het mitochondrion staat NADH die elektronen weer af aan de elektronentransportketen, wat ATP oplevert.</p>","image_url":"","wiki_title":"Nicotinamide adenine dinucleotide","match":"nadh"},"fosforylering":{"title":"Fosforylering","short":"Toevoeging van een fosfaatgroep aan een eiwit; een veelgebruikte aan/uit-schakelaar van eiwitactiviteit.","definition":"<p><b>Fosforylering</b> is het koppelen van een fosfaatgroep aan een eiwit door een kinase. Een fosfatase haalt hem er weer af.</p><p>Zo schakelen cellen eiwitten razendsnel aan of uit — de basis van veel signaaltransductie.</p>","image_url":"","wiki_title":"Phosphorylation","match":"fosforylering|fosforylatie"},"epidermis":{"title":"Epidermis","short":"De opperhuid: het bovenste, uit meerlagig verhoornend plaveiselepitheel opgebouwde deel van de huid.","definition":"<p>De <b>epidermis</b> (opperhuid) is de buitenste huidlaag, opgebouwd uit meerlagig verhoornend plaveiselepitheel zonder bloedvaten.</p><p>Ze bestaat vooral uit keratinocyten in opeenvolgende lagen (basale → hoornlaag) en levert de beschermende barrière.</p>","image_url":"","wiki_title":"Epidermis","match":"epidermis|de epidermis"},"dermis":{"title":"Dermis","short":"De lederhuid onder de epidermis: bindweefsel met collageen, bloedvaten, zenuwen, klieren en haarfollikels.","definition":"<p>De <b>dermis</b> (lederhuid) ligt onder de epidermis en bestaat uit bindweefsel met collageen en elastine.</p><p>Ze bevat bloedvaten, zenuwuiteinden, zweet- en talgklieren en haarfollikels en geeft de huid stevigheid en elasticiteit. Men onderscheidt een papillaire en een reticulaire dermis.</p>","image_url":"","wiki_title":"Dermis","match":"dermis|de dermis|papillaire dermis|reticulaire dermis"},"keratinocyt":{"title":"Keratinocyt","short":"De hoofdcel van de epidermis; produceert keratine en bouwt al opschuivend de huidbarrière op.","definition":"<p>De <b>keratinocyt</b> maakt ongeveer 90% van de epidermiscellen uit. Vanuit het stratum basale schuift hij omhoog terwijl hij steeds meer keratine vormt.</p><p>Bovenaan aangekomen is hij een dode, verhoornde cel die de barrière vormt en uiteindelijk afschilfert.</p>","image_url":"","wiki_title":"Keratinocyte","match":"keratinocyt|keratinocyten"},"fibroblast":{"title":"Fibroblast","short":"De belangrijkste bindweefselcel; produceert collageen, elastine en de overige extracellulaire matrix.","definition":"<p>De <b>fibroblast</b> is de meest voorkomende cel in bindweefsel en de dermis. Hij maakt de vezels (collageen, elastine) en de grondsubstantie aan.</p><p>Bij wondgenezing migreren fibroblasten naar de wond, vormen nieuw matrixmateriaal en kunnen als myofibroblast de wond samentrekken.</p>","image_url":"","wiki_title":"Fibroblast","match":"fibroblast|fibroblasten"},"mestcel":{"title":"Mestcel","short":"Weefselcel vol histaminekorrels die bij allergie en ontsteking degranuleert.","definition":"<p>De <b>mestcel</b> (mastcel) zit in de dermis en andere weefsels en is volgepakt met korrels vol histamine en andere ontstekingsmediatoren.</p><p>Bij binding van allergenen aan IgE op zijn oppervlak stort hij zijn korrels uit (degranulatie), wat jeuk, roodheid en zwelling geeft.</p>","image_url":"","wiki_title":"Mast cell","match":"mestcel|mestcellen|mastcel"},"neutrofiele granulocyt":{"title":"Neutrofiele granulocyt","short":"Meest voorkomende witte bloedcel en eerste verdedigingslinie tegen bacteriën via fagocytose.","definition":"<p>De <b>neutrofiele granulocyt</b> is de talrijkste leukocyt, met een gelobde kern, en als eerste ter plaatse bij een bacteriële infectie.</p><p>Hij ruimt bacteriën op door fagocytose en enzymen; dode neutrofielen vormen samen met bacterieresten de pus.</p>","image_url":"","wiki_title":"Neutrophil","match":"neutrofiele granulocyt|neutrofiele granulocyten"},"eosinofiele granulocyt":{"title":"Eosinofiele granulocyt","short":"Witte bloedcel met rood-kleurende korrels, actief bij afweer tegen parasieten en bij allergie.","definition":"<p>De <b>eosinofiele granulocyt</b> heeft korrels die met eosine roodroze aankleuren en meestal een tweelobbige kern.</p><p>Hij is betrokken bij de afweer tegen wormparasieten en bij allergische processen zoals astma en eczeem; het aantal is dan vaak verhoogd.</p>","image_url":"","wiki_title":"Eosinophil","match":"eosinofiele granulocyt|eosinofiele granulocyten"},"basofiele granulocyt":{"title":"Basofiele granulocyt","short":"Zeldzaamste witte bloedcel; komt met histamine-korrels op voor allergie en ontsteking, verwant aan de mestcel.","definition":"<p>De <b>basofiele granulocyt</b> is de zeldzaamste leukocyt. Zijn korrels kleuren met basische kleurstoffen donker aan en bevatten histamine en heparine.</p><p>Net als de mestcel speelt hij een rol bij allergische reacties en ontsteking.</p>","image_url":"","wiki_title":"Basophil","match":"basofiele granulocyt|basofiele granulocyten"},"monocyt":{"title":"Monocyt","short":"Grootste witte bloedcel; verlaat het bloed en rijpt in de weefsels uit tot macrofaag of dendritische cel.","definition":"<p>De <b>monocyt</b> is de grootste circulerende leukocyt, met een niervormige kern. Hij circuleert enkele dagen en migreert dan de weefsels in.</p><p>Daar differentieert hij tot macrofaag of dendritische cel, die pathogenen fagocyteren en antigenen presenteren.</p>","image_url":"","wiki_title":"Monocyte","match":"monocyt|monocyten"},"macrofaag":{"title":"Macrofaag","short":"Grote fagocyt in de weefsels die pathogenen en celresten opruimt en antigenen presenteert.","definition":"<p>De <b>macrofaag</b> ontstaat uit een monocyt die het weefsel is binnengegaan. Hij fagocyteert bacteriën, dode cellen en afval.</p><p>Als antigeenpresenterende cel activeert hij ook T-cellen en scheidt hij ontstekingsmediatoren uit. In de huid heten verwante cellen histiocyten.</p>","image_url":"","wiki_title":"Macrophage","match":"macrofaag|macrofagen"},"lymfocyt":{"title":"Lymfocyt","short":"Witte bloedcel van de specifieke afweer; omvat de B-cellen (antistoffen) en T-cellen.","definition":"<p>De <b>lymfocyt</b> is de sleutelcel van het adaptieve (specifieke) immuunsysteem. B-lymfocyten maken antistoffen; T-lymfocyten doden geïnfecteerde cellen of sturen de afweer aan.</p><p>Lymfocyten circuleren tussen bloed, lymfe en lymfoïde organen.</p>","image_url":"","wiki_title":"Lymphocyte","match":"lymfocyt|lymfocyten"},"plasmacel":{"title":"Plasmacel","short":"Uit een B-cel gerijpte cel die grote hoeveelheden antistoffen (antilichamen) produceert.","definition":"<p>De <b>plasmacel</b> is een geactiveerde, uitgerijpte B-lymfocyt. Zijn sterk ontwikkelde ruw endoplasmatisch reticulum maakt hem tot een antistoffabriek.</p><p>Hij scheidt grote hoeveelheden specifieke antilichamen af tegen één antigeen.</p>","image_url":"","wiki_title":"Plasma cell","match":"plasmacel|plasmacellen"},"thymus":{"title":"Thymus","short":"Lymfoïd orgaan achter het borstbeen waar T-lymfocyten uitrijpen en geselecteerd worden.","definition":"<p>De <b>thymus</b> (zwezerik) ligt achter het borstbeen. Hier rijpen T-lymfocyten uit en worden ze getest op nut en veiligheid (positieve en negatieve selectie).</p><p>De thymus is het actiefst in de jeugd en neemt daarna geleidelijk af.</p>","image_url":"","wiki_title":"Thymus","match":"thymus"},"milt":{"title":"Milt","short":"Lymfoïd orgaan dat oude bloedcellen afbreekt en bloedgedragen ziekteverwekkers filtert.","definition":"<p>De <b>milt</b> filtert het bloed: de rode pulpa ruimt versleten erytrocyten op, de witte pulpa herbergt lymfocyten voor de afweer tegen bloedgedragen pathogenen.</p><p>Ook dient de milt als bloedreservoir.</p>","image_url":"","wiki_title":"Spleen","match":"milt"},"beenmerg":{"title":"Beenmerg","short":"Weefsel in de holten van botten waar alle bloedcellen worden gevormd (hematopoëse).","definition":"<p>Het <b>beenmerg</b> vult de holten van botten. In het rode beenmerg vindt de hematopoëse plaats: de vorming van rode en witte bloedcellen en bloedplaatjes uit stamcellen.</p><p>Het is tevens de plaats waar B-lymfocyten uitrijpen.</p>","image_url":"","wiki_title":"Bone marrow","match":"beenmerg|het beenmerg"},"lymfeklier":{"title":"Lymfeklier","short":"Filterstation in de lymfebaan waar antigenen worden gepresenteerd en de afweerreactie op gang komt.","definition":"<p>De <b>lymfeklier</b> filtert de lymfe en is een ontmoetingsplaats voor antigeenpresenterende cellen en lymfocyten.</p><p>Hier worden T- en B-cellen geactiveerd; bij infectie zwellen lymfeklieren op doordat de lymfocyten zich vermenigvuldigen.</p>","image_url":"","wiki_title":"Lymph node","match":"lymfeklier|lymfeklieren|lymfklier|lymfklieren"},"collageen":{"title":"Collageen","short":"Sterkste structuureiwit van het lichaam; hoofdbestanddeel van bindweefsel, dermis, pezen en bot.","definition":"<p><b>Collageen</b> is het meest voorkomende eiwit in het lichaam en vormt sterke, drievoudig gewonden vezels.</p><p>In de dermis geeft het de huid trekvastheid; fibroblasten maken het aan. Voor de aanmaak is vitamine C nodig (hydroxylering van proline).</p>","image_url":"","wiki_title":"Collagen","match":"collageen"},"elastine":{"title":"Elastine","short":"Rekbaar bindweefseleiwit dat huid, longen en bloedvaten na uitrekking hun vorm laat hervinden.","definition":"<p><b>Elastine</b> vormt elastische vezels die kunnen uitrekken en daarna weer terugveren.</p><p>Het geeft de huid, longen en slagaderwanden hun elasticiteit. Afname van elastine draagt bij aan huidveroudering en rimpels.</p>","image_url":"","wiki_title":"Elastin","match":"elastine"},"papula":{"title":"Papula","short":"Klein, vast, verheven en voelbaar huidknobbeltje (< ~1 cm).","definition":"<p>Een <b>papula</b> (papel) is een klein, stevig, verheven bultje kleiner dan ongeveer 1 cm dat je kunt voelen.</p><p>Voorbeelden zijn een insectenbeet-reactie of de bultjes bij acne. Meerdere versmolten papels vormen een plaque.</p>","image_url":"","wiki_title":"Papule","match":"papula|papel|papels|papula's|papula’s|papels"},"nodulus":{"title":"Nodulus","short":"Vaste, verheven en voelbare knobbel die dieper in de huid reikt dan een papel (> ~1 cm).","definition":"<p>Een <b>nodulus</b> (nodus, knobbel) is een stevige, verheven laesie die groter is dan een papel en dieper in de dermis of subcutis reikt.</p><p>Voorbeelden zijn een dermatofibroom of sommige huidtumoren.</p>","image_url":"","wiki_title":"Nodule (medicine)","match":"nodulus|nodus|noduli|nodi"},"vesikel":{"title":"Vesikel","short":"Klein, met helder vocht gevuld blaasje in de huid (< ~1 cm).","definition":"<p>Een <b>vesikel</b> (vesicula) is een klein blaasje gevuld met helder vocht, kleiner dan ongeveer 1 cm.</p><p>Vesikels komen voor bij o.a. herpes, waterpokken en acuut eczeem. Een groter blaasje heet een bulla.</p>","image_url":"","wiki_title":"Blister","match":"vesikel|vesikels|vesicula|vesiculae"},"urtica":{"title":"Urtica","short":"Vluchtige, jeukende, verheven zwelling van de huid — een 'galbult' of kwaddel.","definition":"<p>Een <b>urtica</b> (kwaddel, galbult) is een verheven, bleekroze zwelling door vochtophoping in de dermis, meestal sterk jeukend.</p><p>Ze ontstaat door histamine-afgifte (netelroos/urticaria) en verdwijnt doorgaans binnen 24 uur weer.</p>","image_url":"","wiki_title":"Hives","match":"urtica|urticae"},"squama":{"title":"Squama","short":"Zichtbare hoornschilfer door versnelde of gestoorde verhoorning van de opperhuid.","definition":"<p>Een <b>squama</b> (schilfer) is een loskomend plaatje hoorncellen van het stratum corneum.</p><p>Overmatige schilfering is typerend voor psoriasis en ichthyosis.</p>","image_url":"","wiki_title":"Desquamation","match":"squama|squamae|schilfer|schilfering"},"erosie":{"title":"Erosie","short":"Oppervlakkig huiddefect beperkt tot de epidermis, dat zonder litteken geneest.","definition":"<p>Een <b>erosie</b> is een oppervlakkig verlies van epidermis, bijvoorbeeld nadat een blaasje is opengegaan.</p><p>Omdat de dermis intact blijft, geneest een erosie zonder litteken.</p>","image_url":"","wiki_title":"Erosion (dermatology)","match":"erosie|erosies"},"ulcus":{"title":"Ulcus","short":"Diep huiddefect tot in de dermis of dieper, dat met een litteken geneest (een 'zweer').","definition":"<p>Een <b>ulcus</b> (zweer) is een dieper weefselverlies dat tot in de dermis of subcutis reikt.</p><p>Doordat de dermis is aangetast, geneest het met littekenvorming. Een ulcus cruris (open been) is een bekend voorbeeld.</p>","image_url":"","wiki_title":"Ulcer (dermatology)","match":"ulcus|ulcera"},"excoriatie":{"title":"Excoriatie","short":"Oppervlakkig krab- of schaafdefect van de huid, vaak door krabben.","definition":"<p>Een <b>excoriatie</b> is een oppervlakkige beschadiging van de huid door mechanische kracht, meestal krabben.</p><p>Ze reikt tot in de bovenste dermis en gaat vaak gepaard met korstjes; typisch bij jeukende aandoeningen zoals eczeem.</p>","image_url":"","wiki_title":"Excoriation","match":"excoriatie|excoriaties"},"atrofie":{"title":"Atrofie","short":"Verdunning of afname van weefsel; bij de huid een dunnere, kwetsbaardere epidermis en/of dermis.","definition":"<p><b>Atrofie</b> is het slinken van een weefsel of orgaan doordat de cellen krimpen of in aantal afnemen.</p><p>Huidatrofie (bijv. na langdurig sterk corticosteroïdgebruik of door veroudering) geeft een dunne, doorschijnende, kwetsbare huid.</p>","image_url":"","wiki_title":"Atrophy","match":"atrofie"},"melanoom":{"title":"Melanoom","short":"Kwaadaardige tumor van melanocyten; relatief zeldzaam maar het gevaarlijkst door vroege uitzaaiing.","definition":"<p>Het <b>melanoom</b> is een kwaadaardige tumor van de pigmentcellen (melanocyten).</p><p>Het is de dodelijkste huidkanker omdat het vroeg kan uitzaaien. De ABCDE-regel (Asymmetrie, Begrenzing, Kleur, Diameter, Evolutie) helpt bij herkenning; de Breslowdikte bepaalt de prognose.</p>","image_url":"","wiki_title":"Melanoma","match":"melanoom|melanomen"},"constitutioneel eczeem":{"title":"Constitutioneel eczeem","short":"Chronisch, jeukend, atopisch eczeem met een gestoorde huidbarrière; begint meestal op de kinderleeftijd.","definition":"<p><b>Constitutioneel eczeem</b> (atopische dermatitis) is een chronische, jeukende huidontsteking die vaak al bij baby's begint.</p><p>Een gestoorde huidbarrière (o.a. door filaggrine-defect) en atopische aanleg spelen een rol. Bij kinderen zit het typisch in de elleboog- en knieplooien.</p>","image_url":"","wiki_title":"Atopic dermatitis","match":"constitutioneel eczeem|atopisch eczeem|atopische dermatitis"},"allergisch contacteczeem":{"title":"Allergisch contacteczeem","short":"Vertraagde (type IV) allergische huidreactie op een stof waarvoor men gevoelig is geworden, zoals nikkel.","definition":"<p><b>Allergisch contacteczeem</b> is een type IV (vertraagde) allergische reactie: na eerdere sensibilisatie geven T-cellen bij hernieuwd contact een eczeemreactie.</p><p>Bekende allergenen zijn nikkel, parfums en conserveermiddelen. Het eczeem verschijnt 1–3 dagen na contact op de blootgestelde plek.</p>","image_url":"","wiki_title":"Contact dermatitis","match":"allergisch contacteczeem"},"excisie":{"title":"Excisie","short":"Chirurgisch wegsnijden van een huidafwijking, meestal met een marge gezond weefsel.","definition":"<p>Een <b>excisie</b> is het operatief wegsnijden van een laesie, doorgaans met een randje gezonde huid (marge).</p><p>Bij een diagnostische excisie wordt de hele afwijking verwijderd voor onderzoek; bij huidkanker is de marge afhankelijk van het type en de dikte.</p>","image_url":"","wiki_title":"Wide local excision","match":"excisie|diagnostische excisie"},"puntmutatie":{"title":"Puntmutatie","short":"Verandering van één enkele DNA-base.","definition":"<p>Een <b>puntmutatie</b> is de vervanging, invoeging of verwijdering van één enkele base in het DNA.</p><p>Afhankelijk van het effect op het codon spreekt men van een stille, missense of nonsense mutatie.</p>","image_url":"","wiki_title":"Point mutation","match":"puntmutatie"},"pluripotent":{"title":"Pluripotent","short":"Eigenschap van een stamcel die kan uitgroeien tot vrijwel alle celtypen van het lichaam.","definition":"<p>Een <b>pluripotente</b> stamcel kan differentiëren tot cellen van alle drie de kiembladen — dus vrijwel elk celtype — maar niet tot een volledig organisme.</p><p>Embryonale stamcellen zijn pluripotent. Het staat tegenover multipotent (beperkt tot enkele verwante celtypen).</p>","image_url":"","wiki_title":"Cell potency","match":"pluripotent"},"mrna":{"title":"mRNA","short":"Boodschapper-RNA dat de genetische code van het DNA naar de ribosomen brengt voor eiwitsynthese.","definition":"<p><b>mRNA</b> (messenger RNA) is de kopie van een gen die tijdens transcriptie in de kern wordt gemaakt.</p><p>Het reist naar het cytoplasma, waar ribosomen de codons aflezen om er een eiwit van te maken (translatie).</p>","image_url":"","wiki_title":"Messenger RNA","match":"mrna|messenger rna|boodschapper-rna"},"staphylococcus aureus":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"staphylococcus aureus|s. aureus|stafylococcus aureus","option_only":true},"influenzavirus":{"title":"Influenza(virus)","short":"Influenza (griep) wordt veroorzaakt door het influenzavirus, een omhuld RNA-virus met hoge koorts, spierpijn en hoesten; jaarlijks seizoensgebonden.","definition":"<p><strong>Influenza</strong> wordt veroorzaakt door influenzavirussen (type A, B en C), omhulde RNA-virussen met een gesegmenteerd genoom. Op het oppervlak zitten hemagglutinine (H) en neuraminidase (N).</p><p>Kleine mutaties in H en N (<em>antigene drift</em>) veroorzaken de jaarlijkse griepepidemie; uitwisseling van gensegmenten (<em>antigene shift</em>, alleen type A) kan pandemieën geven. Klachten: plotselinge hoge koorts, spierpijn, hoofdpijn, droge hoest. Complicatie is o.a. een secundaire bacteriële pneumonie. Jaarlijks vaccin voor risicogroepen.</p>","image_url":"","wiki_title":"Influenza","match":"influenzavirus|influenza|griep|influenza a|influenzavirussen","option_only":true},"rode hond":{"title":"Rode hond (rubella)","short":"Rode hond is een milde virale ziekte met huiduitslag en zwollen klieren, maar bij infectie in de vroege zwangerschap ontstaat het congenitaal rubellasyndroom.","definition":"<p><strong>Rode hond</strong> (rubella) wordt veroorzaakt door het rubellavirus, een omhuld RNA-virus. Bij kinderen verloopt het mild: lichte koorts, kleinvlekkige huiduitslag en gezwollen lymfeklieren (o.a. achter de oren en in de nek).</p><p>Gevaarlijk is infectie van een zwangere in het eerste trimester: het virus kan de foetus besmetten en het <em>congenitaal rubellasyndroom</em> veroorzaken (doofheid, cataract, hartafwijkingen). Vaccinatie gebeurt met het BMR-vaccin.</p>","image_url":"","wiki_title":"Rubella","match":"rode hond|rubella|rubellavirus","option_only":true},"covid-19":{"title":"COVID-19","short":"COVID-19 is de ziekte veroorzaakt door het coronavirus SARS-CoV-2, met klachten van verkoudheid tot ernstige pneumonie.","definition":"<p><strong>COVID-19</strong> wordt veroorzaakt door <em>SARS-CoV-2</em>, een omhuld RNA-coronavirus dat via het spike-eiwit aan de ACE2-receptor bindt. Overdracht via druppels en aerosolen.</p><p>Het klinisch beeld varieert van geen klachten of verkoudheid tot een virale pneumonie met ARDS. Verlies van reuk en smaak was een opvallend symptoom. Risicofactoren voor een ernstig beloop zijn hoge leeftijd, obesitas en comorbiditeit.</p>","image_url":"","wiki_title":"COVID-19","match":"covid-19|covid|sars-cov-2|corona","option_only":true},"malaria":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"malaria|plasmodium|plasmodium falciparum","option_only":true},"meningitis":{"title":"Meningitis","short":"Meningitis is een ontsteking van de hersenvliezen, met hoofdpijn, koorts, nekstijfheid en verminderd bewustzijn; bacteriële meningitis is een spoedgeval.","definition":"<p><strong>Meningitis</strong> is een ontsteking van de leptomeningen (pia en arachnoidea) en de liquor. Oorzaken zijn bacteriën (bij volwassenen vooral pneumokok en meningokok), virussen (vaak milder) en zelden schimmels.</p><p>Klassieke symptomen: hoofdpijn, koorts, nekstijfheid en een verlaagd bewustzijn; bij meningokokken soms petechiën. Diagnose via lumbaalpunctie (liquoronderzoek). Bacteriële meningitis vereist direct antibiotica en dexamethason.</p>","image_url":"","wiki_title":"Meningitis","match":"meningitis|hersenvliesontsteking|bacteriële meningitis","option_only":true},"tuberculose":{"title":"Tuberculose","short":"Tuberculose is een infectie met Mycobacterium tuberculosis, meestal in de longen, met langdurig hoesten, nachtzweten, gewichtsverlies en granulomen.","definition":"<p><strong>Tuberculose</strong> wordt veroorzaakt door <em>Mycobacterium tuberculosis</em> en verspreidt zich via aerosolen. Na infectie wordt de bacterie meestal ingekapseld in granulomen (latente tbc); bij verminderde afweer kan actieve ziekte ontstaan.</p><p>Longtuberculose geeft langdurig hoesten (soms met bloed), koorts, nachtzweten en gewichtsverlies; typisch zijn holtevorming in de longtoppen en granulomen met centrale <em>verkazing</em>. Behandeling met een combinatie van tuberculostatica gedurende minstens 6 maanden.</p>","image_url":"","wiki_title":"Tuberculosis","match":"tuberculose|tbc|tb","option_only":true},"paracetamol":{"title":"Paracetamol","short":"Paracetamol is een pijnstiller en koortsverlager zonder relevante ontstekingsremmende werking; bij overdosering levertoxisch.","definition":"<p><strong>Paracetamol</strong> werkt pijnstillend en koortsverlagend, vermoedelijk via remming van prostaglandinesynthese in het centrale zenuwstelsel. Perifeer is het nauwelijks ontstekingsremmend en het remt de bloedplaatjes niet.</p><p>Het is bij gewone dosering veilig en daarom eerste stap van de pijnladder. Bij overdosering raakt glutathion in de lever uitgeput en hoopt de toxische metaboliet NAPQI zich op, met levernecrose; het antidotum is acetylcysteïne.</p>","image_url":"","wiki_title":"Paracetamol","match":"paracetamol|acetaminofen","option_only":true},"prednison":{"title":"Prednison / prednisolon","short":"Prednison(olon) is een synthetisch glucocorticoïd met sterke ontstekingsremmende en immunosuppressieve werking.","definition":"<p><strong>Prednison</strong> is een prodrug die in de lever wordt omgezet in het actieve <strong>prednisolon</strong>. Beide zijn synthetische <em>glucocorticoïden</em>: ze binden aan de intracellulaire glucocorticoïdreceptor en veranderen de gentranscriptie.</p><p>Daardoor remmen ze de vorming van allerlei ontstekingsmediatoren en de activatie van ontstekingscellen. Gebruikt bij astma/COPD-exacerbaties, auto-immuunziekten en allergieën. Bijwerkingen bij langdurig gebruik: osteoporose, hyperglykemie, gewichtstoename, huidatrofie, infectierisico en bijnierschorsremming.</p>","image_url":"","wiki_title":"Prednisolone","match":"prednison|prednisolon|prednisone|prednisolone","option_only":true},"serotonine":{"title":"Serotonine","short":"Serotonine (5-HT) is een monoamine uit tryptofaan; neurotransmitter voor stemming, slaap en eetlust en in de darm en bloedplaatjes actief.","definition":"<p><strong>Serotonine</strong> (5-hydroxytryptamine) wordt gemaakt uit het aminozuur <em>tryptofaan</em>. Het meeste zit in enterochromaffiene cellen van de darm en wordt in bloedplaatjes opgeslagen.</p><p>In het brein komen serotonerge neuronen uit de raphekernen van de hersenstam; ze beïnvloeden stemming, angst, slaap, eetlust en pijn. SSRI's remmen de heropname en worden bij depressie en angststoornissen gebruikt. In de darm stimuleert serotonine de motiliteit; perifeer veroorzaakt het vasoconstrictie of -dilatatie afhankelijk van het vaatbed.</p>","image_url":"","wiki_title":"Serotonin","match":"serotonine|5-ht|5-hydroxytryptamine|serotonin","option_only":true},"catalase":{"title":"Catalase","short":"Catalase is een enzym dat waterstofperoxide omzet in water en zuurstof; bacteriën met catalase (zoals stafylokokken) zijn catalasepositief.","definition":"<p><strong>Catalase</strong> breekt <em>waterstofperoxide</em> af: 2 H<sub>2</sub>O<sub>2</sub> → 2 H<sub>2</sub>O + O<sub>2</sub>. In menselijke cellen zit het vooral in de peroxisomen en beschermt het tegen oxidatieve schade.</p><p>In de microbiologie is de catalasetest een snelle manier om grampositieve kokken te onderscheiden: <em>stafylokokken</em> zijn catalasepositief (bruisen met H<sub>2</sub>O<sub>2</sub>), <em>streptokokken</em> catalasenegatief. Catalasepositieve micro-organismen zijn ook beter bestand tegen de oxidatieve burst van fagocyten.</p>","image_url":"","wiki_title":"Catalase","match":"catalase","option_only":true},"il-1 en tnf":{"title":"IL-1 en TNF","short":"IL-1 en TNF-α zijn pro-inflammatoire cytokines van macrofagen die koorts, de acutefase-reactie en endotheelactivatie veroorzaken.","definition":"<p><strong>Interleukine-1</strong> en <strong>tumornecrosefactor-α</strong> zijn de klassieke <em>pro-inflammatoire cytokines</em>, vooral afgegeven door geactiveerde macrofagen.</p><p>Ze activeren het endotheel (adhesiemoleculen, leukocytenrekrutering), veroorzaken koorts via prostaglandine E<sub>2</sub> in de hypothalamus en zetten (samen met IL-6) de lever aan tot productie van acutefase-eiwitten zoals CRP. TNF-remmers worden gebruikt bij reumatoïde artritis en IBD.</p>","image_url":"","wiki_title":"Tumor necrosis factor","match":"il-1 en tnf|il-1|tnf|tnf-alfa|tnf-α|interleukine-1|tumornecrosefactor","option_only":true},"complement factoren":{"title":"Complement","short":"Het complementsysteem is een cascade van plasma-eiwitten die micro-organismen opsoneert, ontsteking aanjaagt en via het membraanaanvalscomplex cellen lyseert.","definition":"<p>Het <strong>complementsysteem</strong> bestaat uit plasma-eiwitten (C1–C9 en regulatoren) die in een cascade worden geactiveerd via de klassieke (antilichamen), de lectine- en de alternatieve route.</p><p>Belangrijke functies: <em>opsonisatie</em> (C3b), aantrekken van ontstekingscellen en mestcelactivatie (anafylatoxinen C3a en C5a) en lysis van micro-organismen door het <em>membraanaanvalscomplex</em> (C5b–C9). Tekort aan late complementfactoren geeft een verhoogd risico op <em>Neisseria</em>-infecties.</p>","image_url":"","wiki_title":"Complement system","match":"complement factoren|complementfactoren|complement|complementsysteem","option_only":true},"antilichamen":{"title":"Antilichamen","short":"Antilichamen (immunoglobulinen) zijn door plasmacellen gemaakte Y-vormige eiwitten die specifiek een antigeen binden.","definition":"<p><strong>Antilichamen</strong> worden gemaakt door <em>plasmacellen</em> (gedifferentieerde B-cellen). Ze bestaan uit twee zware en twee lichte ketens; het Fab-deel bindt het antigeen, het Fc-deel bepaalt de effectorfunctie.</p><p>Ze werken door neutralisatie van toxines en virussen, opsonisatie voor fagocytose en activatie van complement. Er zijn vijf klassen: IgM (eerste respons), IgG (meest in bloed, passeert placenta), IgA (slijmvliezen), IgE (allergie, parasieten) en IgD.</p>","image_url":"","wiki_title":"Antibody","match":"antilichamen|antistoffen|immunoglobulinen|antilichaam","option_only":true},"a. axillaris":{"title":"A. axillaris","short":"De a. axillaris is de voortzetting van de a. subclavia vanaf de buitenrand van de eerste rib tot de onderrand van de m. teres major.","definition":"<p>De <strong>a. axillaris</strong> begint aan de laterale rand van de <em>eerste rib</em> als voortzetting van de a. subclavia en eindigt aan de onderrand van de m. teres major, waarna zij a. brachialis heet.</p><p>De m. pectoralis minor verdeelt haar in drie delen, die samen zes takken afgeven: a. thoracica superior, a. thoracoacromialis, a. thoracica lateralis, a. subscapularis en de aa. circumflexae humeri anterior en posterior. De fasciculi van de plexus brachialis liggen om haar heen.</p>","image_url":"","wiki_title":"Axillary artery","match":"a. axillaris|arteria axillaris","option_only":true},"a. subclavia":{"title":"A. subclavia","short":"De a. subclavia voorziet de arm, een deel van de hals en het brein (via de a. vertebralis) van bloed; rechts uit de truncus brachiocephalicus, links direct uit de aortaboog.","definition":"<p>De <strong>a. subclavia</strong> ontspringt rechts uit de truncus brachiocephalicus en links direct uit de aortaboog. Zij loopt over de eerste rib achter de m. scalenus anterior (scalenusspleet, samen met de plexus brachialis).</p><p>Belangrijke takken: <em>a. vertebralis</em> (naar het brein), a. thoracica interna, truncus thyrocervicalis en truncus costocervicalis. Aan de buitenrand van de eerste rib gaat zij over in de a. axillaris.</p>","image_url":"","wiki_title":"Subclavian artery","match":"a. subclavia|arteria subclavia","option_only":true},"longfibrose":{"title":"Longfibrose","short":"Bij longfibrose wordt het longinterstitium vervangen door bindweefsel; de long wordt stug, met een restrictief beeld en verminderde diffusie.","definition":"<p>Bij <strong>longfibrose</strong> leidt beschadiging en abnormaal herstel van het longinterstitium tot verlittekening. Oorzaken zijn idiopathisch (IPF), stofblootstelling (asbest, silica), auto-immuunziekten, medicatie, bestraling of chronische extrinsieke allergische alveolitis.</p><p>De long wordt stijver (lagere compliantie): een <em>restrictieve</em> longfunctiestoornis (lage TLC en VC, normale of verhoogde FEV1/FVC) met verlaagde diffusiecapaciteit. Klachten: progressieve kortademigheid en droge hoest; bij auscultatie fijne ‘knisper’crepitaties; vaak trommelstokvingers.</p>","image_url":"","wiki_title":"Pulmonary fibrosis","match":"longfibrose|pulmonale fibrose|idiopathische pulmonale fibrose|ipf","option_only":true},"echo abdomen":{"title":"Echo abdomen","short":"Een echo abdomen is een echografisch onderzoek van de buikorganen; zonder straling en goed voor galblaas, galwegen, lever, nieren en vrij vocht.","definition":"<p>Bij een <strong>echo abdomen</strong> wordt met geluidsgolven een beeld gemaakt van de buikorganen. Het onderzoek gebruikt geen ioniserende straling, is goedkoop en direct beschikbaar.</p><p>Het is bijzonder geschikt voor het aantonen van galstenen en cholecystitis, verwijde galwegen, leverafwijkingen, nierstuwing (hydronefrose), een abdominaal aorta-aneurysma en vrij vocht. Darmgas en een dikke buikwand beperken het zicht; de kwaliteit hangt af van de onderzoeker.</p>","image_url":"","wiki_title":"Abdominal ultrasonography","match":"echo abdomen|echografie abdomen|echo van de buik|abdominale echografie|echo-abdomen","option_only":true},"proliferatie":{"title":"Proliferatie","short":"Proliferatie is de toename van het aantal cellen door celdeling.","definition":"<p><strong>Proliferatie</strong> is vermeerdering van cellen door celdeling (mitose). Het is een basisproces bij groei en ontwikkeling, weefselherstel en vernieuwing van bijvoorbeeld huid, darmepitheel en bloedcellen.</p><p>Proliferatie wordt gereguleerd door groeifactoren en de celcyclus-controlepunten. Ongecontroleerde proliferatie is een kenmerk van kanker.</p>","image_url":"","wiki_title":"","match":"proliferatie|celproliferatie","option_only":true},"differentiatie":{"title":"Differentiatie","short":"Differentiatie is het proces waarbij een minder gespecialiseerde cel een gespecialiseerde vorm en functie krijgt.","definition":"<p>Bij <strong>(cel)differentiatie</strong> zet een cel bepaalde genen aan en andere uit, waardoor ze een specifieke structuur en functie krijgt — bijvoorbeeld een stamcel die een neuron, spiercel of rode bloedcel wordt.</p><p>Differentiatie wordt gestuurd door signalen uit de omgeving (groeifactoren, cel-celcontact) en transcriptiefactoren. In tumoren geeft de mate van differentiatie (goed tot slecht gedifferentieerd) informatie over agressiviteit.</p>","image_url":"","wiki_title":"","match":"differentiatie|celdifferentiatie","option_only":true},"endotheelcellen":{"title":"Endotheelcellen","short":"Endotheelcellen bekleden als één dunne laag de binnenkant van alle bloed- en lymfevaten en regelen vaattonus, stolling en doorlaatbaarheid.","definition":"<p><strong>Endotheel</strong> is een enkellaags plaveiselepitheel dat de binnenwand (tunica intima) van bloed- en lymfevaten en het hart bekleedt.</p><p>Endotheelcellen zijn actief: ze maken vaatverwijders (NO, prostacycline) en -vernauwers (endotheline), houden het bloed vloeibaar (antistollingsfactoren) maar kunnen bij beschadiging de stolling activeren (von Willebrandfactor), en laten leukocyten via adhesiemoleculen het weefsel in tijdens ontsteking.</p>","image_url":"","wiki_title":"Endothelium","match":"endotheelcellen|endotheel|endotheelcel","option_only":true},"gladde spiercellen":{"title":"Gladde spiercellen","short":"Gladde spiercellen zijn spoelvormige, onwillekeurig aangestuurde spiercellen zonder dwarsstreping, in de wand van vaten en holle organen.","definition":"<p><strong>Gladde spiercellen</strong> zijn spoelvormige cellen met één centraal gelegen kern. Actine en myosine liggen niet in sarcomeren, daarom ontbreekt de dwarsstreping. Contractie wordt via calcium-calmoduline en myosine-lichteketenkinase gereguleerd.</p><p>Ze komen voor in de wand van bloedvaten, luchtwegen, maag-darmkanaal, blaas en uterus en worden aangestuurd door het autonome zenuwstelsel, hormonen en lokale factoren. Ze kunnen langdurig samentrekken met weinig energieverbruik.</p>","image_url":"","wiki_title":"Smooth muscle","match":"gladde spiercellen|glad spierweefsel|gladde spier|gladde spiercel","option_only":true},"allergie":{"title":"Allergie","short":"Een allergie is een overdreven immuunreactie op een onschuldige stof (allergeen), klassiek IgE-gemedieerd: een type I-overgevoeligheidsreactie.","definition":"<p>Bij een <strong>allergie</strong> reageert het immuunsysteem op een onschadelijk antigeen, zoals pollen, huisstofmijt of voedsel. Bij de eerste blootstelling ontstaat <em>sensibilisatie</em>: B-cellen maken onder invloed van Th2-cellen IgE, dat zich aan mestcellen bindt.</p><p>Bij herblootstelling binden allergenen dat IgE, waardoor mestcellen histamine, leukotriënen en prostaglandinen afgeven (type I-reactie): niezen, jeuk, urticaria, astma of anafylaxie. Een late fase met eosinofielen kan volgen.</p>","image_url":"","wiki_title":"Allergy","match":"allergie|allergische reactie|type i-overgevoeligheid","option_only":true},"systemische lupus erythematosus":{"title":"Systemische lupus erythematosus (SLE)","short":"SLE is een systemische auto-immuunziekte met antinucleaire antistoffen en immuuncomplexen; gewrichten, huid, nieren en bloed kunnen aangedaan zijn.","definition":"<p><strong>Systemische lupus erythematosus</strong> is een chronische auto-immuunziekte die vooral jonge vrouwen treft. Er worden antistoffen gevormd tegen kerncomponenten (ANA, anti-dsDNA, anti-Sm), die met antigenen <em>immuuncomplexen</em> vormen die neerslaan in weefsels (type III-reactie) en complement verbruiken.</p><p>Kenmerken: artralgie/artritis, vlindervormig erytheem in het gezicht, fotosensitiviteit, serositis, nefritis, cytopenieën en neurologische verschijnselen. Behandeling met o.a. hydroxychloroquine, corticosteroïden en immunosuppressiva.</p>","image_url":"","wiki_title":"Systemic lupus erythematosus","match":"systemische lupus erythematosus|sle|lupus|systemic lupus erythematosus","option_only":true},"sclerodermie (systemic sclerosis)":{"title":"Systemische sclerose (sclerodermie)","short":"Systemische sclerose is een auto-immuunziekte met fibrose van huid en organen en vaatafwijkingen; typisch zijn Raynaud, strakke huid en anti-Scl-70/anticentromeer.","definition":"<p>Bij <strong>systemische sclerose</strong> (sclerodermie) leiden auto-immuniteit en schade aan kleine bloedvaten tot overmatige collageenvorming en <em>fibrose</em> van huid en inwendige organen.</p><p>Bijna alle patiënten hebben het fenomeen van Raynaud. De huid wordt strak en verdikt (sclerodactylie), en er kunnen slikklachten (oesofagus), longfibrose, pulmonale hypertensie en een renale crisis ontstaan. Bij de beperkte vorm (CREST) zijn vaak anticentromeer-antistoffen aanwezig, bij de diffuse vorm anti-Scl-70 (topo-isomerase I).</p>","image_url":"","wiki_title":"Systemic scleroderma","match":"sclerodermie (systemic sclerosis)|sclerodermie|systemische sclerose|systemic sclerosis","option_only":true},"artrose (osteoarthritis)":{"title":"Artrose","short":"Artrose is degeneratie van gewrichtskraakbeen met botreactie; het geeft startpijn en pijn bij belasting, vooral in knieën, heupen en handen bij ouderen.","definition":"<p>Bij <strong>artrose</strong> slijt en verdwijnt het gewrichtskraakbeen, met reactieve veranderingen van het bot: <em>osteofyten</em>, subchondrale sclerose en cysten, en versmalling van de gewrichtsspleet op de röntgenfoto.</p><p>Risicofactoren: leeftijd, overgewicht, eerder letsel en aanleg. Klachten: pijn bij belasting, startpijn en korte ochtendstijfheid (&lt;30 minuten), soms crepitaties en verminderde beweeglijkheid. Typische plaatsen: knie, heup, DIP- en PIP-gewrichten (Heberden- en Bouchardknobbels) en het CMC-1-gewricht.</p>","image_url":"","wiki_title":"Osteoarthritis","match":"artrose (osteoarthritis)|artrose|osteoarthritis|osteoartrose","option_only":true},"septische artritis":{"title":"Septische artritis","short":"Septische artritis is een bacteriële infectie van een gewricht (vaak S. aureus): acuut, pijnlijk, gezwollen, warm gewricht met koorts; een spoedgeval.","definition":"<p>Bij <strong>septische artritis</strong> raakt een gewricht geïnfecteerd, meestal via de bloedbaan, soms na een punctie of operatie. De meest voorkomende verwekker is <em>Staphylococcus aureus</em>; bij seksueel actieve jongvolwassenen ook <em>Neisseria gonorrhoeae</em>.</p><p>Het geeft een acuut rood, warm, gezwollen en zeer pijnlijk gewricht (vaak de knie) met bewegingsbeperking en meestal koorts. Diagnose door punctie (troebel synoviaal vocht met veel leukocyten, kweek). Snel draineren en antibiotica zijn nodig om kraakbeenvernietiging te voorkomen.</p>","image_url":"","wiki_title":"Septic arthritis","match":"septische artritis|bacteriële artritis|septische arthritis","option_only":true},"reactieve artritis":{"title":"Reactieve artritis","short":"Reactieve artritis is een steriele gewrichtsontsteking enkele weken na een darm- of urogenitale infectie, vaak bij HLA-B27-dragers.","definition":"<p><strong>Reactieve artritis</strong> ontstaat 1–4 weken na een infectie van de darm (<em>Salmonella</em>, <em>Shigella</em>, <em>Campylobacter</em>, <em>Yersinia</em>) of de urogenitale tractus (<em>Chlamydia trachomatis</em>). Het gewricht zelf is niet geïnfecteerd.</p><p>Typisch is een asymmetrische oligoartritis van vooral de benen, eventueel met enthesitis, dactylitis, urethritis en conjunctivitis/uveïtis. Het behoort tot de spondyloartritiden en is geassocieerd met HLA-B27.</p>","image_url":"","wiki_title":"Reactive arthritis","match":"reactieve artritis|reactieve arthritis|ziekte van reiter","option_only":true},"maligniteit":{"title":"Maligniteit","short":"Een maligniteit is een kwaadaardige tumor: ongecontroleerd groeiende cellen die omliggend weefsel binnendringen en kunnen uitzaaien.","definition":"<p>Een <strong>maligniteit</strong> (kanker) is een tumor waarvan de cellen ongeremd delen, het omliggende weefsel <em>infiltreren</em> en via bloed- of lymfevaten kunnen <em>metastaseren</em>. Dat onderscheidt ze van goedaardige (benigne) tumoren, die expansief groeien zonder invasie.</p><p>Maligniteiten ontstaan door een opeenstapeling van genetische veranderingen (activatie van oncogenen, uitschakeling van tumorsuppressorgenen). Systemische verschijnselen kunnen zijn: gewichtsverlies, moeheid, nachtzweten, anemie, trombose en paraneoplastische syndromen.</p>","image_url":"","wiki_title":"","match":"maligniteit|maligne tumor|kanker|kwaadaardige tumor","option_only":true},"tumor":{"title":"Tumor","short":"Een tumor (neoplasma) is een gezwel door autonome, overmatige celgroei; die kan goedaardig (benigne) of kwaadaardig (maligne) zijn.","definition":"<p>In de pathologie betekent <strong>tumor</strong> letterlijk zwelling, maar meestal bedoelt men een <em>neoplasma</em>: weefsel dat ontstaat door celgroei die niet meer gereguleerd wordt en doorgaat zonder de oorspronkelijke prikkel.</p><p>Benigne tumoren groeien meestal langzaam en expansief, zijn goed begrensd en zaaien niet uit. Maligne tumoren groeien invasief en kunnen metastaseren. ‘Tumor’ is ook een van de klassieke ontstekingsverschijnselen (zwelling).</p>","image_url":"","wiki_title":"","match":"tumor|gezwel|neoplasma","option_only":true},"maagcarcinoom":{"title":"Maagcarcinoom","short":"Een maagcarcinoom is een kwaadaardige tumor (meestal adenocarcinoom) van de maag; risicofactoren zijn o.a. H. pylori, roken en zoutrijke voeding.","definition":"<p>Het <strong>maagcarcinoom</strong> is meestal een adenocarcinoom, uitgaand van het klierepitheel. Het intestinale type ontstaat via een reeks van chronische (H. pylori-)gastritis, atrofie, intestinale metaplasie en dysplasie; het diffuse type (zegelringcellen) infiltreert de wand zonder duidelijke massa (linitis plastica).</p><p>Klachten komen vaak laat: verminderde eetlust, vroege verzadiging, gewichtsverlies, epigastrische pijn, anemie of slikklachten. Metastasen kunnen zich manifesteren als een klier van Virchow (links supraclaviculair) of ovariummetastasen (Krukenberg).</p>","image_url":"","wiki_title":"Stomach cancer","match":"maagcarcinoom|maagkanker|adenocarcinoom van de maag","option_only":true},"koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"koorts|febris|pyrexie|hoge koorts","option_only":true},"hepatocyten":{"title":"Hepatocyten","short":"Hepatocyten zijn de levercellen die vrijwel alle metabole, synthetiserende en ontgiftende functies van de lever uitvoeren.","definition":"<p><strong>Hepatocyten</strong> vormen ±80% van het levervolume. Ze liggen in balkjes langs de sinusoïden en hebben veel mitochondriën, glad en ruw ER en Golgi.</p><p>Ze maken plasma-eiwitten (albumine, stollingsfactoren), gal, glucose (gluconeogenese) en ureum, slaan glycogeen, vet en vitamines op en ontgiften stoffen via het cytochroom P450-systeem. Tussen naburige hepatocyten liggen de galcanaliculi.</p>","image_url":"","wiki_title":"Hepatocyte","match":"hepatocyten|levercellen|hepatocyt","option_only":true},"pancreas":{"title":"Pancreas","short":"De pancreas is zowel een exocriene klier (verteringsenzymen en bicarbonaat naar het duodenum) als een endocriene klier (insuline en glucagon uit de eilandjes van Langerhans).","definition":"<p>De <strong>pancreas</strong> ligt retroperitoneaal achter de maag, met de kop in de bocht van het duodenum.</p><p>Het <em>exocriene</em> deel (±98%) maakt verteringsenzymen (trypsine(ogeen), lipase, amylase) en bicarbonaatrijk sap, dat via de ductus pancreaticus samen met de galweg in het duodenum uitmondt. Het <em>endocriene</em> deel bestaat uit de eilandjes van Langerhans met bètacellen (insuline), alfacellen (glucagon) en deltacellen (somatostatine).</p>","image_url":"","wiki_title":"Pancreas","match":"pancreas|alvleesklier","option_only":true},"de milt":{"title":"Milt","short":"De milt filtert het bloed: hij ruimt oude en beschadigde rode bloedcellen op en vormt een afweerorgaan tegen bacteriën in het bloed.","definition":"<p>De <strong>milt</strong> ligt linksboven in de buik onder het diafragma. Ze bestaat uit <em>rode pulpa</em> (sinusoïden waar verouderde of afwijkende erytrocyten worden afgebroken) en <em>witte pulpa</em> (lymfatisch weefsel met B- en T-cellen rond arteriolen).</p><p>De milt is belangrijk voor de afweer tegen <em>gekapselde bacteriën</em> (pneumokok, meningokok, H. influenzae). Na splenectomie is het risico op een ernstige sepsis daardoor verhoogd; deze patiënten worden gevaccineerd.</p>","image_url":"","wiki_title":"Spleen","match":"de milt|milt|lien|splenomegalie","option_only":true},"angiogenese":{"title":"Angiogenese","short":"Angiogenese is de vorming van nieuwe bloedvaten uit bestaande vaten, gestimuleerd door o.a. VEGF; belangrijk bij wondgenezing en tumorgroei.","definition":"<p>Bij <strong>angiogenese</strong> spruiten nieuwe capillairen uit bestaande vaten. Endotheelcellen breken de basaalmembraan af, migreren, prolifereren en vormen nieuwe buisjes, gevolgd door rekrutering van pericyten.</p><p>Het belangrijkste stimulerende signaal is <em>VEGF</em>, dat o.a. bij hypoxie wordt gemaakt. Angiogenese is essentieel bij embryonale ontwikkeling, wondgenezing (granulatieweefsel) en de menstruele cyclus, maar ook bij tumorgroei en diabetische retinopathie; VEGF-remmers worden daarom bij kanker en maculadegeneratie gebruikt.</p>","image_url":"","wiki_title":"Angiogenesis","match":"angiogenese|neovascularisatie|angiogenesis","option_only":true},"fibrineuze ontsteking":{"title":"Fibrineuze ontsteking","short":"Bij een fibrineuze ontsteking lekt door sterke vaatbeschadiging fibrinogeen uit de vaten, dat als fibrine neerslaat, vaak op sereuze vliezen (bijv. pericarditis).","definition":"<p>Bij een <strong>fibrineuze ontsteking</strong> is de vaatwand zo doorlaatbaar dat ook grote eiwitten zoals fibrinogeen het weefsel in lekken. Daar wordt het omgezet in <em>fibrine</em>, dat als een eosinofiel, draderig netwerk neerslaat.</p><p>Het komt typisch voor op sereuze vliezen (pericard, pleura, peritoneum): bij een fibrineuze pericarditis ontstaat een ‘broodboter’-aspect en een pericardwrijven. Als de fibrine niet wordt opgeruimd, kan het ingroeien tot littekenweefsel (verklevingen).</p>","image_url":"","wiki_title":"","match":"fibrineuze ontsteking|fibrineus exsudaat","option_only":true},"sereuze ontsteking":{"title":"Sereuze ontsteking","short":"Bij een sereuze ontsteking lekt een dun, eiwitarm, celarm vocht uit, zoals in een brandblaar of bij een pleura-effusie.","definition":"<p>Bij een <strong>sereuze ontsteking</strong> bestaat het exsudaat uit dun, helder vocht met relatief weinig eiwit en cellen, afkomstig uit het plasma of uit mesotheelcellen.</p><p>Voorbeelden zijn de vochtblaar bij een brandwond of virale huidinfectie en vochtophoping in lichaamsholten (sereuze effusie, bijv. pleuravocht bij een milde ontsteking). Het is de mildste vorm van exsudatieve ontsteking.</p>","image_url":"","wiki_title":"","match":"sereuze ontsteking|sereus exsudaat","option_only":true},"ulcererende ontsteking":{"title":"Ulcererende ontsteking","short":"Bij een ulcererende ontsteking gaat het oppervlakte-epitheel lokaal verloren, met een defect (ulcus) waarvan de bodem ontstoken is.","definition":"<p>Een <strong>ulcus</strong> is een lokaal defect van het epitheel en (een deel van) het onderliggende weefsel, ontstaan door necrose en afstoting van ontstoken weefsel.</p><p>Het komt vooral voor op slijmvliezen (maag, duodenum, darm) en de huid (bijv. ulcus cruris). De bodem van het ulcus bevat necrotisch materiaal en fibrine met daaronder een ontstekingsinfiltraat; in het chronische stadium ontstaat granulatieweefsel en fibrose.</p>","image_url":"","wiki_title":"","match":"ulcererende ontsteking|ulceratie|ulcus","option_only":true},"b-cellen":{"title":"B-cellen","short":"B-cellen zijn lymfocyten die na activatie uitrijpen tot plasmacellen die antilichamen maken; ze rijpen in het beenmerg.","definition":"<p><strong>B-cellen</strong> ontstaan en rijpen in het beenmerg. Elke B-cel draagt een unieke B-celreceptor (membraangebonden antilichaam).</p><p>Na binding van een antigeen en meestal hulp van een T-helpercel (in de kiemcentra van lymfeklieren) prolifereren ze en differentiëren ze tot <em>plasmacellen</em> (antilichaamproductie) en geheugen-B-cellen. Daarbij vinden klasseswitch en affiniteitsrijping plaats. B-cellen kunnen ook antigeen presenteren.</p>","image_url":"","wiki_title":"B cell","match":"b-cellen|b cellen|b-lymfocyten|b-cel|b-lymfocyt|b cel","option_only":true},"t-cellen":{"title":"T-cellen","short":"T-cellen zijn lymfocyten die in de thymus rijpen en antigeen herkennen dat via MHC wordt gepresenteerd; CD4-cellen helpen, CD8-cellen doden geïnfecteerde cellen.","definition":"<p><strong>T-cellen</strong> ontstaan in het beenmerg en rijpen in de <em>thymus</em>, waar positieve en negatieve selectie plaatsvindt. Hun T-celreceptor herkent alleen peptiden die door MHC-moleculen worden gepresenteerd.</p><p><em>CD4⁺ T-helpercellen</em> herkennen MHC-II en sturen de afweer met cytokines (Th1, Th2, Th17, Tfh); <em>CD8⁺ cytotoxische T-cellen</em> herkennen MHC-I en doden geïnfecteerde of tumorcellen; regulatoire T-cellen remmen de afweer. Ze vormen de cellulaire adaptieve immuniteit.</p>","image_url":"","wiki_title":"T cell","match":"t-cellen|t cellen|t-lymfocyten|t-cel|t-lymfocyt|t cel","option_only":true},"neutrofielen":{"title":"Neutrofiele granulocyten","short":"Neutrofielen zijn de meest voorkomende witte bloedcellen; ze zijn als eerste ter plekke bij een acute bacteriële ontsteking en fagocyteren bacteriën.","definition":"<p><strong>Neutrofiele granulocyten</strong> hebben een gesegmenteerde kern en korrels met afbrekende enzymen. Ze leven maar kort (uren tot dagen) en worden in grote aantallen in het beenmerg gemaakt.</p><p>Bij een acute ontsteking verlaten ze als eerste de bloedbaan (marginatie, rollen, adhesie, diapedese) en volgen ze chemotactische signalen (o.a. IL-8, C5a). Ze fagocyteren en doden bacteriën met een oxidatieve burst en enzymen en kunnen ‘NETs’ uitwerpen. Pus bestaat grotendeels uit dode neutrofielen.</p>","image_url":"","wiki_title":"Neutrophil","match":"neutrofielen|neutrofiele granulocyten|neutrofiel|neutrofiele granulocyt","option_only":true},"dendritische cellen":{"title":"Dendritische cellen","short":"Dendritische cellen zijn de belangrijkste antigeenpresenterende cellen: ze nemen antigeen op in weefsels en activeren naïeve T-cellen in de lymfeklier.","definition":"<p><strong>Dendritische cellen</strong> zitten in weefsels die in contact staan met de buitenwereld, zoals huid (Langerhanscellen) en slijmvliezen. Met hun uitlopers nemen ze antigenen op.</p><p>Na activatie (bijv. via Toll-like receptoren) migreren ze naar de lymfeklier, waar ze antigeenfragmenten op MHC-I en MHC-II presenteren, met costimulerende moleculen. Ze zijn de enige cellen die effectief <em>naïeve T-cellen</em> activeren en vormen zo de brug tussen aangeboren en verworven afweer.</p>","image_url":"","wiki_title":"Dendritic cell","match":"dendritische cellen|dendritische cel|langerhanscellen","option_only":true},"astma":{"title":"Astma","short":"Astma is een chronische ontsteking van de luchtwegen met wisselende, reversibele luchtwegobstructie en hyperreactiviteit; klachten zijn piepen, benauwdheid en hoesten.","definition":"<p>Bij <strong>astma</strong> zijn de luchtwegen chronisch ontstoken (vaak eosinofiel/Th2-gemedieerd) en <em>hyperreactief</em>: op prikkels zoals allergenen, inspanning, koude lucht of rook ontstaan bronchoconstrictie, slijmvliesoedeem en slijmproductie.</p><p>De obstructie is variabel en grotendeels <em>reversibel</em> (verbetering van de FEV1 na een luchtwegverwijder). Klachten: aanvallen van piepen, kortademigheid, een beklemd gevoel op de borst en hoesten, vaak ’s nachts. Behandeling met inhalatiecorticosteroïden en luchtwegverwijders.</p>","image_url":"","wiki_title":"Asthma","match":"astma|asthma|astma bronchiale","option_only":true},"nier":{"title":"Nier","short":"De nieren filteren het bloed en regelen water-, zout- en zuur-base-evenwicht en bloeddruk; ook maken ze hormonen (renine, EPO, actief vitamine D).","definition":"<p>De <strong>nieren</strong> liggen retroperitoneaal aan weerszijden van de wervelkolom. De functionele eenheid is het <em>nefron</em>: glomerulus, proximale tubulus, lis van Henle, distale tubulus en verzamelbuis. Samen filteren de nieren ongeveer 180 liter per dag, waarvan meer dan 99% wordt teruggeresorbeerd.</p><p>Ze scheiden afvalstoffen (ureum, creatinine) en geneesmiddelen uit, regelen het volume en de samenstelling van de lichaamsvloeistoffen en de pH, en maken <em>renine</em> (bloeddruk), <em>erytropoëtine</em> (aanmaak van rode bloedcellen) en <em>calcitriol</em> (actief vitamine D).</p>","image_url":"","wiki_title":"Kidney","match":"nier|nieren|ren","option_only":true},"cortisol":{"title":"Cortisol","short":"Cortisol is het belangrijkste glucocorticoïd uit de bijnierschors; het is een stresshormoon met effecten op stofwisseling en afweer.","definition":"<p><strong>Cortisol</strong> wordt gemaakt in de zona fasciculata onder invloed van ACTH, met een dagritme (hoog in de ochtend). Het verhoogt de bloedglucose (gluconeogenese), breekt eiwitten af, remt ontsteking en afweer en ondersteunt de bloeddruk. Overmaat geeft het syndroom van Cushing, tekort bijnierinsufficiëntie (ziekte van Addison).</p>","image_url":"","wiki_title":"Cortisol","match":"cortisol|hydrocortison","option_only":true},"adrenaline":{"title":"Adrenaline (epinefrine)","short":"Adrenaline is een catecholamine uit het bijniermerg dat de ‘fight-or-flight’-reactie aanstuurt via alfa- en bèta-receptoren.","definition":"<p><strong>Adrenaline</strong> wordt door chromaffiene cellen van het bijniermerg afgegeven bij stress. Het verhoogt hartfrequentie en contractiekracht (β1), verwijdt de bronchi (β2), vernauwt vaten in huid en darm (α1) en verhoogt de bloedglucose. Als geneesmiddel is het het middel bij anafylaxie (intramusculair) en wordt het gebruikt bij reanimatie.</p>","image_url":"","wiki_title":"Adrenaline","match":"adrenaline|epinefrine|epinephrine","option_only":true},"histamine":{"title":"Histamine","short":"Histamine is een mediator uit mestcellen en basofielen die vaatverwijding, lekkage, jeuk en bronchoconstrictie veroorzaakt.","definition":"<p><strong>Histamine</strong> ontstaat uit histidine en ligt opgeslagen in de granula van mestcellen en basofielen. Via H1-receptoren veroorzaakt het vaatverwijding, verhoogde vaatpermeabiliteit, jeuk en bronchoconstrictie; via H2-receptoren stimuleert het de maagzuursecretie. In het brein werkt het als neurotransmitter voor waakzaamheid.</p>","image_url":"","wiki_title":"Histamine","match":"histamine","option_only":true},"stikstofoxide":{"title":"Stikstofoxide (NO)","short":"Stikstofoxide (NO) is een gasvormige signaalstof uit het endotheel die gladde spier ontspant en zo vaten verwijdt.","definition":"<p><strong>NO</strong> wordt gemaakt uit arginine door NO-synthase. In het endotheel ontstaat het o.a. door schuifspanning en acetylcholine; het diffundeert naar de gladde spiercel, activeert guanylaatcyclase en verhoogt cGMP, wat relaxatie geeft. NO remt ook de plaatjesaggregatie. Nitraten en PDE5-remmers versterken deze route.</p>","image_url":"","wiki_title":"Nitric oxide","match":"stikstofoxide|stikstofmonoxide|no|nitric oxide","option_only":true},"lysozym":{"title":"Lysozym","short":"Lysozym is een antibacterieel enzym in traanvocht, speeksel en slijm dat de peptidoglycaanwand van bacteriën afbreekt.","definition":"<p><strong>Lysozym</strong> splitst de bindingen tussen N-acetylmuraminezuur en N-acetylglucosamine in peptidoglycaan. Het werkt vooral tegen grampositieve bacteriën, die een dikke, onbeschermde peptidoglycaanlaag hebben. Het is onderdeel van de aangeboren afweer en komt voor in tranen, speeksel, moedermelk en de granula van neutrofielen.</p>","image_url":"","wiki_title":"Lysozyme","match":"lysozym|lysozyme","option_only":true},"a. thyroidea inferior":{"title":"A. thyroidea inferior","short":"De a. thyroidea inferior is een tak van de truncus thyrocervicalis die de onderpool van de schildklier en de bijschildklieren voorziet.","definition":"<p>De <strong>a. thyroidea inferior</strong> komt uit de truncus thyrocervicalis (tak van de a. subclavia) en loopt achter de a. carotis naar de schildklier. Ze voorziet ook de bijschildklieren. Vlak bij de schildklier kruist ze de n. laryngeus recurrens, waar de chirurg bij een thyreoïdectomie extra op moet letten.</p>","image_url":"","wiki_title":"Inferior thyroid artery","match":"a. thyroidea inferior|arteria thyroidea inferior","option_only":true},"hiv":{"title":"Hiv (humaan immunodeficiëntievirus)","short":"Hiv is een retrovirus dat CD4-T-helpercellen infecteert; zonder behandeling ontstaat aids.","definition":"<p><strong>Hiv</strong> bindt met gp120 aan CD4 en een co-receptor (CCR5 of CXCR4), schrijft zijn RNA via reverse transcriptase om naar DNA en bouwt dat in het genoom in. Het aantal CD4-cellen daalt geleidelijk; onder ±200/µl ontstaan opportunistische infecties en tumoren (aids). Overdracht via seks, bloed en van moeder op kind. Combinatietherapie (cART) onderdrukt het virus volledig.</p>","image_url":"","wiki_title":"HIV","match":"hiv|humaan immunodeficiëntievirus|aids","option_only":true},"toxoplasmose":{"title":"Toxoplasmose","short":"Toxoplasmose is een infectie met de parasiet Toxoplasma gondii, opgelopen via kattenpoep of onvoldoende verhit vlees.","definition":"<p><strong><em>Toxoplasma gondii</em></strong> heeft de kat als eindgastheer. Bij gezonde mensen verloopt infectie meestal ongemerkt of als een mononucleose-achtig beeld. Bij een eerste infectie in de zwangerschap kan de parasiet de foetus infecteren (chorioretinitis, hydrocephalus, intracraniële verkalkingen). Bij afweergestoorden kan reactivatie toxoplasma-encefalitis geven.</p>","image_url":"","wiki_title":"Toxoplasmosis","match":"toxoplasmose|toxoplasma gondii|toxoplasma","option_only":true},"giardiasis":{"title":"Giardiasis","short":"Giardiasis is een darminfectie met de protozo Giardia lamblia, met langdurige diarree, opgeblazen gevoel en vetrijke ontlasting.","definition":"<p><strong><em>Giardia lamblia</em></strong> wordt via cysten in besmet water of voedsel opgelopen. De trofozoïeten hechten aan het dunnedarmepitheel zonder het te binnendringen. Klachten: waterige, vettige, stinkende ontlasting, buikkrampen, winderigheid en gewichtsverlies, soms wekenlang. Diagnose met PCR of microscopie van ontlasting; behandeling met metronidazol of tinidazol.</p>","image_url":"","wiki_title":"Giardiasis","match":"giardiasis|giardia lamblia|giardia","option_only":true},"sepsis":{"title":"Sepsis","short":"Sepsis is een levensbedreigende orgaandisfunctie door een ontregelde afweerreactie op een infectie.","definition":"<p>Bij <strong>sepsis</strong> leidt de reactie van het lichaam op een infectie tot schade aan de eigen organen: hypotensie, verwardheid, snelle ademhaling, nierfalen, stollingsstoornissen en een verhoogd lactaat. Septische shock is sepsis met hypotensie die vasopressoren vereist. Snelle herkenning (bijv. qSOFA), bloedkweken, antibiotica binnen een uur en vochtresuscitatie zijn essentieel.</p>","image_url":"","wiki_title":"Sepsis","match":"sepsis|bloedvergiftiging","option_only":true},"myxoedeem":{"title":"Myxoedeem","short":"Myxoedeem is deegachtige zwelling van de huid door stapeling van glycosaminoglycanen; het begrip wordt ook gebruikt voor ernstige hypothyreoïdie.","definition":"<p>Bij ernstige <strong>hypothyreoïdie</strong> stapelen glycosaminoglycanen zich op in de huid, waardoor een niet-putjesvormend, deegachtig oedeem ontstaat, vooral rond de ogen en aan handen en voeten. Een myxoedeemcoma is een levensbedreigende ontsporing met hypothermie en verlaagd bewustzijn. Pretibiaal myxoedeem is daarentegen een specifiek kenmerk van de ziekte van Graves.</p>","image_url":"","wiki_title":"Myxedema","match":"myxoedeem|myxoedema","option_only":true},"schildklier":{"title":"Schildklier (glandula thyroidea)","short":"De schildklier is een vlindervormige klier in de hals die de schildklierhormonen T4 en T3 en calcitonine maakt.","definition":"<p>De <strong>schildklier</strong> ligt vóór de trachea, onder het strottenhoofd. Folliculaire cellen nemen jodium op en maken thyroglobuline, waarmee T4 en T3 worden gevormd; deze regelen het basaal metabolisme. De afgifte wordt gestuurd door TSH uit de hypofyse. Parafolliculaire C-cellen maken calcitonine. Embryonaal daalt de schildklier af vanaf de tongbasis (ductus thyroglossus).</p>","image_url":"","wiki_title":"Thyroid","match":"schildklier|glandula thyroidea|thyroid","option_only":true},"leukocytose":{"title":"Leukocytose","short":"Leukocytose is een verhoogd aantal witte bloedcellen, meestal door infectie of ontsteking.","definition":"<p>Bij <strong>leukocytose</strong> is het aantal leukocyten boven ongeveer 10 × 10⁹/L. Een neutrofiele leukocytose met linksverschuiving past bij bacteriële infectie; ook stress, corticosteroïden, roken, trauma en necrose kunnen het verhogen. Sterk verhoogde waarden met onrijpe cellen in het bloed wijzen op leukemie of een leukemoïde reactie.</p>","image_url":"","wiki_title":"Leukocytosis","match":"leukocytose","option_only":true},"granulocyten":{"title":"Granulocyten","short":"Granulocyten zijn witte bloedcellen met korrels in het cytoplasma: neutrofielen, eosinofielen en basofielen.","definition":"<p><strong>Granulocyten</strong> ontstaan uit de myeloïde lijn via myeloblast, promyelocyt, myelocyt, metamyelocyt en staafkernige vorm. <em>Neutrofielen</em> fagocyteren bacteriën, <em>eosinofielen</em> spelen een rol bij parasitaire infecties en allergie, <em>basofielen</em> geven histamine af. Ze maken deel uit van de aangeboren afweer.</p>","image_url":"","wiki_title":"Granulocyte","match":"granulocyten|granulocyt","option_only":true},"hodgkin lymfoom":{"title":"Hodgkinlymfoom","short":"Het Hodgkinlymfoom is een kwaadaardige ziekte van het lymfeweefsel, gekenmerkt door Reed-Sternbergcellen.","definition":"<p>Het <strong>Hodgkinlymfoom</strong> komt vooral voor bij jongvolwassenen en ouderen. Het begint vaak met een pijnloze lymfeklierzwelling in de hals of het mediastinum en verspreidt zich via aangrenzende kliergroepen. B-symptomen (koorts, nachtzweten, gewichtsverlies) en jeuk komen voor. In het weefsel zijn grote Reed-Sternbergcellen (CD15+, CD30+) in een ontstekingsachtergrond te zien. De prognose is meestal goed.</p>","image_url":"","wiki_title":"Hodgkin lymphoma","match":"hodgkin lymfoom|hodgkinlymfoom|ziekte van hodgkin","option_only":true},"igg":{"title":"IgG","short":"IgG is de meest voorkomende antistofklasse in het bloed; het is belangrijk bij de secundaire immuunrespons en passeert de placenta.","definition":"<p><strong>IgG</strong> is een monomeer en heeft vier subklassen. Het werkt via neutralisatie, opsonisatie (via Fcγ-receptoren op fagocyten) en complementactivatie. Het is de belangrijkste antistof bij een herhaalde blootstelling en de enige klasse die actief via de placenta naar de foetus gaat, wat pasgeborenen maandenlang beschermt.</p>","image_url":"","wiki_title":"Immunoglobulin G","match":"igg|immunoglobuline g","option_only":true},"th1 cellen":{"title":"Th1-cellen","short":"Th1-cellen zijn CD4-T-helpercellen die via IFN-γ macrofagen activeren en zo intracellulaire ziekteverwekkers bestrijden.","definition":"<p><strong>Th1-cellen</strong> ontstaan onder invloed van IL-12 en maken vooral IFN-γ. Daardoor worden macrofagen beter in het doden van opgenomen micro-organismen zoals mycobacteriën. Th1-reacties liggen ten grondslag aan type IV-overgevoeligheid en granuloomvorming. Tegenover hen staan o.a. Th2-cellen (IL-4, IL-5, IL-13; allergie en parasieten) en Th17-cellen.</p>","image_url":"","wiki_title":"T helper cell","match":"th1 cellen|th1-cellen|th1","option_only":true},"ifn-α":{"title":"Interferon-alfa","short":"Interferon-alfa is een type I-interferon dat door geïnfecteerde cellen wordt gemaakt en naburige cellen in een antivirale toestand brengt.","definition":"<p><strong>Type I-interferonen</strong> (IFN-α en IFN-β) worden vooral door plasmacytoïde dendritische cellen en geïnfecteerde cellen afgegeven. Ze remmen virale replicatie in omliggende cellen, verhogen de MHC-I-expressie en activeren NK-cellen. Als geneesmiddel werd interferon-alfa gebruikt bij chronische hepatitis B en C en sommige maligniteiten; bijwerkingen zijn griepachtige klachten en depressie.</p>","image_url":"","wiki_title":"Interferon type I","match":"ifn-α|ifn-alfa|interferon-alfa|interferon alfa|type i interferon","option_only":true},"icam-1":{"title":"ICAM-1","short":"ICAM-1 is een adhesiemolecuul op geactiveerd endotheel dat via integrines (LFA-1) leukocyten stevig laat binden.","definition":"<p><strong>ICAM-1</strong> behoort tot de immunoglobuline-superfamilie en wordt door IL-1 en TNF op endotheel tot expressie gebracht. Het bindt aan integrines zoals LFA-1 en Mac-1 op leukocyten, wat vaste adhesie en transmigratie mogelijk maakt. ICAM-1 is ook de receptor voor de meeste rhinovirussen.</p>","image_url":"","wiki_title":"ICAM-1","match":"icam-1|intercellular adhesion molecule-1","option_only":true},"cd31 (pecam-1)":{"title":"PECAM-1 (CD31)","short":"PECAM-1 (CD31) is een adhesiemolecuul op de verbindingen tussen endotheelcellen dat de doorgang (diapedese) van leukocyten bevordert.","definition":"<p><strong>PECAM-1</strong> komt voor op endotheelcellen (vooral op de celgrenzen), bloedplaatjes en leukocyten. Door homofiele binding helpt het leukocyten tussen endotheelcellen door het weefsel in te gaan. In de pathologie is CD31 een marker om endotheel en vaattumoren aan te tonen.</p>","image_url":"","wiki_title":"PECAM-1","match":"cd31 (pecam-1)|cd31|pecam-1","option_only":true},"sialyl-lewis-x gemodificeerde glycoproteïnen":{"title":"Sialyl-Lewis X","short":"Sialyl-Lewis X is een suikerstructuur op leukocyten die bindt aan selectines op het endotheel en zo het ‘rollen’ mogelijk maakt.","definition":"<p><strong>Sialyl-Lewis X</strong> is een tetrasacharide op glycoproteïnen (zoals PSGL-1) van leukocyten. Het is het ligand voor E- en P-selectine op geactiveerd endotheel. Een erfelijk defect in de vorming ervan (leukocyte adhesion deficiency type II) geeft recidiverende infecties door verstoorde leukocytenrekrutering.</p>","image_url":"","wiki_title":"Sialyl-Lewis X","match":"sialyl-lewis-x gemodificeerde glycoproteïnen|sialyl-lewis-x|sialyl lewis x","option_only":true},"fcε-receptoren":{"title":"Fcε-receptoren","short":"Fcε-receptoren binden het Fc-deel van IgE; op mestcellen en basofielen zorgen ze voor de allergische reactie.","definition":"<p>De hoog-affiene <strong>FcεRI</strong> zit op mestcellen en basofielen en houdt IgE ook zonder antigeen vast. Als een allergeen twee gebonden IgE-moleculen verbindt, degranuleert de cel en komen histamine, leukotriënen en cytokines vrij (type I-reactie). Omalizumab (anti-IgE) voorkomt de binding van IgE aan deze receptor.</p>","image_url":"","wiki_title":"Fc receptor","match":"fcε-receptoren|fcε-receptor|fc-epsilon-receptor|fcεri","option_only":true},"fcγ-receptoren":{"title":"Fcγ-receptoren","short":"Fcγ-receptoren binden het Fc-deel van IgG; ze laten fagocyten en NK-cellen met antistoffen beladen doelwitten herkennen.","definition":"<p><strong>Fcγ-receptoren</strong> komen voor op macrofagen, neutrofielen, NK-cellen en B-cellen. Ze bemiddelen opsonisatie en fagocytose van IgG-gecoate deeltjes en antilichaam-afhankelijke cellulaire cytotoxiciteit (ADCC). De neonatale Fc-receptor (FcRn) zorgt voor transport van IgG over de placenta en voor de lange halfwaardetijd van IgG.</p>","image_url":"","wiki_title":"Fc receptor","match":"fcγ-receptoren|fcγ-receptor|fc-gamma-receptor","option_only":true},"rubor":{"title":"Rubor (roodheid)","short":"Rubor (roodheid) is een van de klassieke ontstekingsverschijnselen, door verwijding van de bloedvaten.","definition":"<p>De klassieke tekenen van ontsteking zijn <strong>rubor</strong> (roodheid), calor (warmte), tumor (zwelling), dolor (pijn) en functio laesa (functieverlies). Roodheid en warmte ontstaan door arterioladilatatie onder invloed van mediatoren als histamine, prostaglandinen en NO, waardoor meer bloed door het ontstoken gebied stroomt.</p>","image_url":"","wiki_title":"Inflammation","match":"rubor|roodheid","option_only":true},"reumatoïde artritis":{"title":"Reumatoïde artritis","short":"Reumatoïde artritis is een chronische auto-immuunziekte met symmetrische ontsteking van vooral de kleine gewrichten van handen en voeten.","definition":"<p>Bij <strong>reumatoïde artritis</strong> leidt synovitis tot pannusvorming en erosie van kraakbeen en bot. Kenmerken: symmetrische polyartritis van MCP-, PIP- en MTP-gewrichten, ochtendstijfheid langer dan een uur, reumafactor en anti-CCP-antistoffen. Extra-articulair: reumanoduli, longaandoeningen, vasculitis. Vroege behandeling met DMARD's (zoals methotrexaat) voorkomt gewrichtsschade.</p>","image_url":"","wiki_title":"Rheumatoid arthritis","match":"reumatoïde artritis|reumatoide artritis|reumatoïde arthritis","option_only":true},"jicht":{"title":"Jicht","short":"Jicht is een gewrichtsontsteking door neerslag van uraatkristallen bij een verhoogd urinezuur.","definition":"<p>Bij <strong>jicht</strong> slaan mononatriumuraatkristallen neer in en rond gewrichten. Een aanval begint plotseling, vaak ’s nachts, met een rood, gezwollen, zeer pijnlijk gewricht. Uitlokkers zijn alcohol, purinerijk voedsel, diuretica en uitdroging. In het gewrichtsvocht zijn naaldvormige, negatief dubbelbrekende kristallen te zien. Behandeling van een aanval met NSAID's, colchicine of corticosteroïden; preventie met allopurinol.</p>","image_url":"","wiki_title":"Gout","match":"jicht|arthritis urica|podagra","option_only":true},"lupus erythematosus":{"title":"Lupus erythematosus","short":"Lupus erythematosus is een auto-immuunziekte die beperkt kan blijven tot de huid of als systemische ziekte (SLE) meerdere organen treft.","definition":"<p>Bij <strong>cutane lupus</strong> zijn er huidafwijkingen zoals discoïde plaques met littekens of een fotosensitieve uitslag. Bij <strong>systemische lupus erythematosus</strong> zijn er daarnaast antinucleaire antistoffen en ontsteking van o.a. gewrichten, nieren, serosa, bloed en zenuwstelsel. Geneesmiddelen (bijv. hydralazine, procaïnamide) kunnen een lupusachtig beeld geven met anti-histonantistoffen.</p>","image_url":"","wiki_title":"Lupus erythematosus","match":"lupus erythematosus|lupus","option_only":true},"conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies, met een rood oog, tranen of afscheiding en een branderig gevoel, zonder visusdaling.","definition":"<p><strong>Conjunctivitis</strong> kan viraal (vaak adenovirus, waterige afscheiding), bacterieel (purulente afscheiding) of allergisch (jeuk, beide ogen, seizoensgebonden) zijn. Het zicht is normaal en er is meestal geen echte pijn of lichtschuwheid; die passen eerder bij keratitis, uveïtis of glaucoom. Bij pasgeborenen moet aan chlamydia of gonokokken worden gedacht.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"conjunctivitis|bindvliesontsteking","option_only":true},"tolerantie":{"title":"Tolerantie","short":"Tolerantie is een afgenomen reactie op een middel bij herhaald gebruik, waardoor een hogere dosis nodig is voor hetzelfde effect.","definition":"<p><strong>Tolerantie</strong> kan farmacokinetisch zijn (snellere afbraak, bijv. enzyminductie) of farmacodynamisch (aanpassing van receptoren, zoals bij opioïden, benzodiazepinen en alcohol). In de immunologie betekent tolerantie het uitblijven van een afweerreactie tegen een antigeen, zoals tegen lichaamseigen weefsel.</p>","image_url":"","wiki_title":"Drug tolerance","match":"tolerantie|gewenning","option_only":true},"aβ-proteïne":{"title":"Amyloïd-β","short":"Amyloïd-β is een eiwitfragment uit APP dat zich bij de ziekte van Alzheimer ophoopt in plaques en in de vaatwand.","definition":"<p><strong>Amyloïd-β</strong> ontstaat door splitsing van het amyloïde-precursoreiwit (APP) door β- en γ-secretase. Vooral de langere vorm (Aβ42) klontert samen tot oligomeren en seniele plaques. Afzetting in de wand van hersenvaten heet cerebrale amyloïdangiopathie en geeft lobaire hersenbloedingen. Bij het syndroom van Down (extra kopie van APP op chromosoom 21) ontstaat Alzheimer op jongere leeftijd.</p>","image_url":"","wiki_title":"Amyloid beta","match":"aβ-proteïne|amyloïd-bèta|amyloid-beta|aβ","option_only":true},"attr-proteïne":{"title":"Transthyretine-amyloïd (ATTR)","short":"ATTR-amyloïdose ontstaat door afzetting van transthyretine, erfelijk (mutant) of op hogere leeftijd (wildtype).","definition":"<p><strong>Transthyretine</strong> is een transporteiwit voor thyroxine en retinol, gemaakt in de lever. Bij <strong>ATTR-amyloïdose</strong> valt het tetrameer uiteen en vormen de monomeren amyloïdfibrillen. De wildtypevorm treft vooral het hart van oudere mannen (cardiomyopathie, carpaletunnelsyndroom); erfelijke vormen geven ook polyneuropathie. Er zijn middelen die het tetrameer stabiliseren.</p>","image_url":"","wiki_title":"Transthyretin amyloidosis","match":"attr-proteïne|attr|transthyretine-amyloïdose","option_only":true},"al-proteïne":{"title":"AL-amyloïd (lichte ketens)","short":"AL-amyloïdose ontstaat door afzetting van vrije lichte ketens van immunoglobulinen, gemaakt door een kloon van plasmacellen.","definition":"<p>Bij <strong>AL-amyloïdose</strong> maakt een (vaak kleine) plasmaceldyscrasie, soms een multipel myeloom, overmatig lichte ketens die neerslaan als amyloïd. Organen die vaak worden aangedaan zijn nier (nefrotisch syndroom), hart (restrictieve cardiomyopathie), zenuwen, lever en tong (macroglossie). Diagnostiek o.a. met vrije lichte ketens in serum en een weefselbiopt met Congoroodkleuring.</p>","image_url":"","wiki_title":"AL amyloidosis","match":"al-proteïne|al-amyloïdose|al-amyloïd","option_only":true},"de ziekte van graves":{"title":"Ziekte van Graves","short":"De ziekte van Graves is een auto-immuunziekte waarbij antistoffen de TSH-receptor stimuleren, met hyperthyreoïdie als gevolg.","definition":"<p>Bij de <strong>ziekte van Graves</strong> maakt het lichaam antistoffen tegen de TSH-receptor (TSI/TRAb). De schildklier wordt diffuus vergroot en overactief, met een verlaagd TSH en verhoogd vrij T4. Specifieke kenmerken zijn Graves-orbitopathie (exoftalmie) en pretibiaal myxoedeem; roken verergert de oogziekte. Behandeling met thyreostatica, radioactief jodium of operatie.</p>","image_url":"","wiki_title":"Graves' disease","match":"de ziekte van graves|ziekte van graves|morbus basedow|graves","option_only":true},"acute myeloïde leukemie":{"title":"Acute myeloïde leukemie (AML)","short":"AML is een agressieve kanker van het beenmerg waarbij onrijpe myeloïde voorlopercellen (blasten) zich ophopen.","definition":"<p>Bij <strong>AML</strong> verdringen myeloblasten (≥20% in het beenmerg) de normale bloedaanmaak, met anemie, trombocytopenie (bloedingen) en neutropenie (infecties). Het komt vooral bij ouderen voor. Blasten kunnen Auerstaafjes bevatten. Bij acute promyelocytenleukemie (t(15;17)) dreigt diffuse intravasale stolling; die vorm reageert goed op all-trans-retinoïnezuur. Behandeling met intensieve chemotherapie, eventueel stamceltransplantatie.</p>","image_url":"","wiki_title":"Acute myeloid leukemia","match":"acute myeloïde leukemie|aml|acute myeloide leukemie","option_only":true},"beenmergonderzoek":{"title":"Beenmergonderzoek","short":"Bij beenmergonderzoek wordt beenmerg uit de bekkenkam opgezogen en/of een biopt genomen om de bloedaanmaak te beoordelen.","definition":"<p>Een <strong>beenmergaspiraat</strong> geeft informatie over de celsoorten (cytologie, flowcytometrie, cytogenetica); een <strong>biopt</strong> over de cellulariteit en architectuur (bijv. fibrose, infiltratie). Het wordt gedaan bij onverklaarde cytopenieën, verdenking op leukemie, myeloom of lymfoom en voor stadiëring.</p>","image_url":"","wiki_title":"Bone marrow examination","match":"beenmergonderzoek|beenmergpunctie|beenmergbiopt","option_only":true},"dexamethason":{"title":"Dexamethason","short":"Dexamethason is een sterk en langwerkend glucocorticoïd zonder mineralocorticoïde werking.","definition":"<p><strong>Dexamethason</strong> is ongeveer 25–30 keer zo krachtig als cortisol. Het wordt gebruikt bij hersenoedeem rond tumoren, bacteriële meningitis (vóór of met antibiotica), misselijkheid door chemotherapie, ernstige COVID-19, en ter longrijping bij dreigende vroeggeboorte. Ook gebruikt bij de dexamethasonsuppressietest voor het syndroom van Cushing.</p>","image_url":"","wiki_title":"Dexamethasone","match":"dexamethason|dexamethasone","option_only":true},"corticosteroïden":{"title":"Corticosteroïden","short":"Corticosteroïden zijn van cortisol afgeleide middelen met sterke ontstekingsremmende en immunosuppressieve werking.","definition":"<p>Glucocorticoïden binden aan een intracellulaire receptor en remmen de transcriptie van ontstekingsgenen (cytokines, COX-2) en de vorming van ontstekingsmediatoren. Ze worden lokaal (huid, inhalatie, injectie) en systemisch gebruikt. Bij langdurig systemisch gebruik: osteoporose, hyperglykemie, gewichtstoename, huidatrofie, infecties, spierzwakte, cataract en remming van de eigen bijnier (niet abrupt stoppen).</p>","image_url":"","wiki_title":"Corticosteroid","match":"corticosteroïden|corticosteroiden|glucocorticoïden|corticosteroïd","option_only":true},"vasodilatatie":{"title":"Vasodilatatie","short":"Vasodilatatie is verwijding van bloedvaten door ontspanning van de gladde spier in de vaatwand.","definition":"<p><strong>Vasodilatatie</strong> verlaagt de vaatweerstand en verhoogt de doorbloeding. Mediatoren zijn o.a. NO, prostacycline, histamine, bradykinine, adenosine, CO₂ en melkzuur (lokale autoregulatie). Het speelt een rol bij ontsteking (roodheid en warmte), warmteafgifte en inspanning, en is het werkingsmechanisme van veel antihypertensiva.</p>","image_url":"","wiki_title":"Vasodilation","match":"vasodilatatie|vaatverwijding","option_only":true},"cervixcarcinoom":{"title":"Cervixcarcinoom","short":"Het cervixcarcinoom is kanker van de baarmoederhals, vrijwel altijd veroorzaakt door een persisterende infectie met hoog-risico-HPV.","definition":"<p>Het <strong>cervixcarcinoom</strong> ontstaat via voorstadia (CIN) in de transformatiezone, meestal als plaveiselcelcarcinoom. Klachten: contactbloedingen (na gemeenschap), intermenstrueel bloedverlies en afscheiding. Preventie via HPV-vaccinatie en het bevolkingsonderzoek (hrHPV-test). Behandeling afhankelijk van stadium: operatie of (chemo)radiatie.</p>","image_url":"","wiki_title":"Cervical cancer","match":"cervixcarcinoom|baarmoederhalskanker","option_only":true},"myastheen syndroom":{"title":"Myasthenie (gravis) en myastheen syndroom","short":"Myasthene syndromen zijn stoornissen in de prikkeloverdracht van zenuw naar spier, met zwakte die toeneemt bij inspanning.","definition":"<p>Bij <strong>myasthenia gravis</strong> blokkeren antistoffen de acetylcholinereceptor; er is wisselende, inspanningsafhankelijke zwakte van oogspieren (ptosis, dubbelzien), bulbaire spieren en ledematen. Bij het <strong>Lambert-Eaton myasthene syndroom</strong> zijn antistoffen gericht tegen presynaptische calciumkanalen, vaak bij een kleincellig longcarcinoom; hier verbetert de kracht juist kort bij herhaald aanspannen en zijn de reflexen verlaagd.</p>","image_url":"","wiki_title":"Myasthenia gravis","match":"myastheen syndroom|lambert-eaton|lambert-eaton myastheen syndroom|myasthenia gravis|myasthenie","option_only":true},"th2 cellen":{"title":"Th2-cellen","short":"Th2-cellen zijn CD4-T-helpercellen die via IL-4, IL-5 en IL-13 de afweer tegen parasieten en allergische reacties sturen.","definition":"<p><strong>Th2-cellen</strong> ontstaan onder invloed van IL-4. Ze stimuleren B-cellen tot de productie van IgE (IL-4, IL-13), activeren eosinofielen (IL-5) en bevorderen slijmproductie. Ze spelen een centrale rol bij allergie, allergisch astma en atopisch eczeem; biologicals tegen IL-4/IL-13 en IL-5 remmen deze route.</p>","image_url":"","wiki_title":"T helper cell","match":"th2 cellen|th2-cellen|th2","option_only":true},"th17 cellen":{"title":"Th17-cellen","short":"Th17-cellen zijn CD4-T-helpercellen die via IL-17 neutrofielen aantrekken; belangrijk tegen bacteriën en schimmels en bij auto-immuunziekten.","definition":"<p><strong>Th17-cellen</strong> ontstaan onder invloed van TGF-β en IL-6 en worden in stand gehouden door IL-23. Ze maken IL-17 en IL-22, die epitheel en neutrofielen activeren. Ze beschermen tegen extracellulaire bacteriën en <em>Candida</em>, en spelen een rol bij psoriasis, spondyloartritis en IBD; middelen tegen IL-17 en IL-23 worden bij deze ziekten gebruikt.</p>","image_url":"","wiki_title":"T helper 17 cell","match":"th17 cellen|th17-cellen|th17","option_only":true},"tonsillitis":{"title":"Tonsillitis","short":"Tonsillitis is een ontsteking van de keelamandelen, meestal viraal, soms door groep A-streptokokken.","definition":"<p>Bij <strong>tonsillitis</strong> zijn de amandelen rood en gezwollen, soms met beslag, en zijn er keelpijn, slikklachten en koorts. Meestal gaat het om een virus (ook EBV). Bij een bacteriële oorzaak gaat het vaak om groep A-streptokokken. Complicaties zijn een peritonsillair abces (met trismus en uitpuilen van het gehemelte) en zelden acuut reuma.</p>","image_url":"","wiki_title":"Tonsillitis","match":"tonsillitis|amandelontsteking|angina tonsillaris","option_only":true},"de ziekte van hashimoto":{"title":"Ziekte van Hashimoto","short":"De ziekte van Hashimoto is een auto-immuunontsteking van de schildklier die meestal tot hypothyreoïdie leidt.","definition":"<p>Bij <strong>Hashimoto-thyreoïditis</strong> infiltreren lymfocyten de schildklier, met antistoffen tegen thyreoperoxidase (anti-TPO). De klier kan eerst vergroot zijn en wordt later vaak kleiner, met geleidelijk een trage schildklierwerking. Het komt vaker voor bij vrouwen en samen met andere auto-immuunziekten. Er is een licht verhoogd risico op een schildkliermalt-lymfoom.</p>","image_url":"","wiki_title":"Hashimoto's thyroiditis","match":"de ziekte van hashimoto|ziekte van hashimoto|hashimoto|thyreoïditis van hashimoto","option_only":true},"leucocytose":{"title":"Leukocytose","short":"Leukocytose is een verhoogd aantal witte bloedcellen, meestal door infectie of ontsteking.","definition":"<p>Bij <strong>leukocytose</strong> is het aantal leukocyten boven ongeveer 10 × 10⁹/L. Een neutrofiele leukocytose met linksverschuiving past bij bacteriële infectie; ook stress, corticosteroïden, roken, trauma en necrose kunnen het verhogen. Sterk verhoogde waarden met onrijpe cellen in het bloed wijzen op leukemie of een leukemoïde reactie.</p>","image_url":"","wiki_title":"Leukocytosis","match":"leucocytose","option_only":true},"het beenmerg":{"title":"Beenmerg","short":"Weefsel in de holten van botten waar alle bloedcellen worden gevormd (hematopoëse).","definition":"<p>Het <b>beenmerg</b> vult de holten van botten. In het rode beenmerg vindt de hematopoëse plaats: de vorming van rode en witte bloedcellen en bloedplaatjes uit stamcellen.</p><p>Het is tevens de plaats waar B-lymfocyten uitrijpen.</p>","image_url":"","wiki_title":"Bone marrow","match":"het beenmerg","option_only":true},"t cel":{"title":"T-cellen","short":"T-cellen zijn lymfocyten die in de thymus rijpen en antigeen herkennen dat via MHC wordt gepresenteerd; CD4-cellen helpen, CD8-cellen doden geïnfecteerde cellen.","definition":"<p><strong>T-cellen</strong> ontstaan in het beenmerg en rijpen in de <em>thymus</em>, waar positieve en negatieve selectie plaatsvindt. Hun T-celreceptor herkent alleen peptiden die door MHC-moleculen worden gepresenteerd.</p><p><em>CD4⁺ T-helpercellen</em> herkennen MHC-II en sturen de afweer met cytokines (Th1, Th2, Th17, Tfh); <em>CD8⁺ cytotoxische T-cellen</em> herkennen MHC-I en doden geïnfecteerde of tumorcellen; regulatoire T-cellen remmen de afweer. Ze vormen de cellulaire adaptieve immuniteit.</p>","image_url":"","wiki_title":"T cell","match":"t cel","option_only":true},"b cel":{"title":"B-cellen","short":"B-cellen zijn lymfocyten die na activatie uitrijpen tot plasmacellen die antilichamen maken; ze rijpen in het beenmerg.","definition":"<p><strong>B-cellen</strong> ontstaan en rijpen in het beenmerg. Elke B-cel draagt een unieke B-celreceptor (membraangebonden antilichaam).</p><p>Na binding van een antigeen en meestal hulp van een T-helpercel (in de kiemcentra van lymfeklieren) prolifereren ze en differentiëren ze tot <em>plasmacellen</em> (antilichaamproductie) en geheugen-B-cellen. Daarbij vinden klasseswitch en affiniteitsrijping plaats. B-cellen kunnen ook antigeen presenteren.</p>","image_url":"","wiki_title":"B cell","match":"b cel","option_only":true},"hoge koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"hoge koorts","option_only":true},"cytotoxische t lymfocyten":{"title":"Cytotoxische T-cellen (CD8)","short":"Cytotoxische T-cellen herkennen via MHC klasse I gepresenteerde antigenen en doden geïnfecteerde of kwaadaardige cellen.","definition":"<p><strong>CD8⁺ T-cellen</strong> doden doelcellen via perforine en granzymen of via Fas-ligand, waarna apoptose volgt. Ze zijn essentieel bij de afweer tegen virussen, intracellulaire bacteriën en tumoren, en spelen een rol bij transplantaatafstoting en sommige auto-immuunziekten.</p>","image_url":"","wiki_title":"Cytotoxic T cell","match":"cytotoxische t lymfocyten|cytotoxische t-cellen|cd8+ t-cellen|cd8","option_only":true},"a. thyroidea superior":{"title":"A. thyroidea superior","short":"De a. thyroidea superior is de eerste tak van de a. carotis externa en voorziet de bovenpool van de schildklier.","definition":"<p>De <strong>a. thyroidea superior</strong> loopt met de externe tak van de n. laryngeus superior naar de bovenpool van de schildklier. Bij het afbinden van deze arterie tijdens een thyreoïdectomie kan die zenuw (die de m. cricothyroideus innerveert) beschadigd raken, met een minder krachtige, lagere stem.</p>","image_url":"","wiki_title":"Superior thyroid artery","match":"a. thyroidea superior|arteria thyroidea superior","option_only":true},"cd4+-lymfocyten":{"title":"CD4+ T-helpercellen","short":"CD4+ T-helpercellen sturen de afweer via cytokines; hiv infecteert deze cellen en het CD4-getal is de belangrijkste maat voor de afweer bij hiv.","definition":"<p><strong>T-helpercellen</strong> herkennen antigeen op MHC klasse II en differentiëren tot o.a. Th1, Th2, Th17, Tfh en regulatoire T-cellen. Ze activeren macrofagen, helpen B-cellen bij antistofproductie en ondersteunen cytotoxische T-cellen. Bij een CD4-getal onder ongeveer 200 per µl ontstaan opportunistische infecties zoals <em>Pneumocystis</em>-pneumonie.</p>","image_url":"","wiki_title":"T helper cell","match":"cd4+-lymfocyten|cd4+ t-cellen|t-helpercellen|cd4-cellen","option_only":true},"otitis media acuta":{"title":"Otitis media acuta","short":"Otitis media acuta is een acute middenoorontsteking met oorpijn, koorts en een rood, bomberend trommelvlies.","definition":"<p><strong>Acute otitis media</strong> komt vooral bij jonge kinderen voor, vaak na een verkoudheid; verwekkers zijn virussen en bacteriën (pneumokok, <em>H. influenzae</em>, <em>Moraxella</em>). Een loopoor ontstaat bij perforatie van het trommelvlies. Meestal geneest het spontaan; pijnstilling is de basis, antibiotica alleen bij risicofactoren of ernstig beloop.</p>","image_url":"","wiki_title":"Otitis media","match":"otitis media acuta|acute otitis media|middenoorontsteking","option_only":true},"reumatoide artritis":{"title":"Reumatoïde artritis","short":"Reumatoïde artritis is een chronische auto-immuunziekte met symmetrische ontsteking van vooral de kleine gewrichten van handen en voeten.","definition":"<p>Bij <strong>reumatoïde artritis</strong> leidt synovitis tot pannusvorming en erosie van kraakbeen en bot. Kenmerken: symmetrische polyartritis van MCP-, PIP- en MTP-gewrichten, ochtendstijfheid langer dan een uur, reumafactor en anti-CCP-antistoffen. Extra-articulair: reumanoduli, longaandoeningen, vasculitis. Vroege behandeling met DMARD's (zoals methotrexaat) voorkomt gewrichtsschade.</p>","image_url":"","wiki_title":"Rheumatoid arthritis","match":"reumatoide artritis","option_only":true},"glomerulaire filtratiesnelheid":{"title":"Nier","short":"De nieren filteren het bloed en regelen water-, zout- en zuur-base-evenwicht en bloeddruk; ook maken ze hormonen (renine, EPO, actief vitamine D).","definition":"<p>De <strong>nieren</strong> liggen retroperitoneaal aan weerszijden van de wervelkolom. De functionele eenheid is het <em>nefron</em>: glomerulus, proximale tubulus, lis van Henle, distale tubulus en verzamelbuis. Samen filteren de nieren ongeveer 180 liter per dag, waarvan meer dan 99% wordt teruggeresorbeerd.</p><p>Ze scheiden afvalstoffen (ureum, creatinine) en geneesmiddelen uit, regelen het volume en de samenstelling van de lichaamsvloeistoffen en de pH, en maken <em>renine</em> (bloeddruk), <em>erytropoëtine</em> (aanmaak van rode bloedcellen) en <em>calcitriol</em> (actief vitamine D).</p>","image_url":"","wiki_title":"Kidney","match":"glomerulaire filtratiesnelheid","option_only":true},"ernstige sepsis":{"title":"Sepsis","short":"Sepsis is een levensbedreigende orgaandisfunctie door een ontregelde afweerreactie op een infectie.","definition":"<p>Bij <strong>sepsis</strong> leidt de reactie van het lichaam op een infectie tot schade aan de eigen organen: hypotensie, verwardheid, snelle ademhaling, nierfalen, stollingsstoornissen en een verhoogd lactaat. Septische shock is sepsis met hypotensie die vasopressoren vereist. Snelle herkenning (bijv. qSOFA), bloedkweken, antibiotica binnen een uur en vochtresuscitatie zijn essentieel.</p>","image_url":"","wiki_title":"Sepsis","match":"ernstige sepsis","option_only":true},"longontsteking door sars-cov-2":{"title":"COVID-19","short":"COVID-19 is de ziekte veroorzaakt door het coronavirus SARS-CoV-2, met klachten van verkoudheid tot ernstige pneumonie.","definition":"<p><strong>COVID-19</strong> wordt veroorzaakt door <em>SARS-CoV-2</em>, een omhuld RNA-coronavirus dat via het spike-eiwit aan de ACE2-receptor bindt. Overdracht via druppels en aerosolen.</p><p>Het klinisch beeld varieert van geen klachten of verkoudheid tot een virale pneumonie met ARDS. Verlies van reuk en smaak was een opvallend symptoom. Risicofactoren voor een ernstig beloop zijn hoge leeftijd, obesitas en comorbiditeit.</p>","image_url":"","wiki_title":"COVID-19","match":"longontsteking door sars-cov-2","option_only":true},"diclofenac":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"diclofenac","option_only":true},"granulomateuze ontsteking":{"title":"Granulomateuze ontsteking","short":"Bij een granulomateuze ontsteking vormen macrofagen (epitheloïde cellen en reuscellen) compacte haarden: granulomen.","definition":"<p><strong>Granulomen</strong> ontstaan bij persisterende antigenen die moeilijk op te ruimen zijn, via een Th1/IFN-γ-gedreven reactie. Voorbeelden: tuberculose (met centrale verkazing), sarcoïdose (niet-verkazend), lepra, schimmels, de ziekte van Crohn, granulomatose met polyangiitis en vreemdlichaamreacties.</p>","image_url":"","wiki_title":"Granulomatous inflammation","match":"granulomateuze ontsteking|granuloom|granulomen","option_only":true},"hypertrofie":{"title":"Hypertrofie","short":"Hypertrofie is vergroting van een weefsel of orgaan doordat de afzonderlijke cellen groter worden.","definition":"<p><strong>Hypertrofie</strong> treedt vooral op in weefsels die weinig delen, zoals hart- en skeletspier, als aanpassing aan een verhoogde belasting (bijv. linkerventrikelhypertrofie bij hypertensie of training). Het kan samengaan met hyperplasie.</p>","image_url":"","wiki_title":"Hypertrophy","match":"hypertrofie","option_only":true},"reumafactor":{"title":"Reumafactor","short":"Reumafactor is een auto-antistof (meestal IgM) tegen het Fc-deel van IgG; hij komt voor bij reumatoïde artritis maar ook bij andere ziekten.","definition":"<p><strong>Reumafactor</strong> is positief bij ongeveer 70–80% van de patiënten met reumatoïde artritis, maar ook bij het syndroom van Sjögren, chronische infecties (hepatitis C, endocarditis) en bij gezonde ouderen. Anti-CCP is specifieker voor RA.</p>","image_url":"","wiki_title":"Rheumatoid factor","match":"reumafactor|rf","option_only":true},"fibrinoïde necrose":{"title":"Fibrinoïde necrose","short":"Fibrinoïde necrose is een vorm van necrose in de vaatwand, met neerslag van fibrine en immuuncomplexen, bij vasculitis en maligne hypertensie.","definition":"<p>Bij <strong>fibrinoïde necrose</strong> ziet de vaatwand er onder de microscoop helderroze en amorf uit. Het komt voor bij immuuncomplexvasculitis (bijv. polyarteriitis nodosa) en bij maligne hypertensie.</p>","image_url":"","wiki_title":"Fibrinoid necrosis","match":"fibrinoïde necrose","option_only":true},"necrotiserende vasculitis":{"title":"Necrotiserende vasculitis","short":"Bij een necrotiserende vasculitis gaat de vaatwand door ontsteking te gronde, met bloedingen of afsluiting.","definition":"<p>Voorbeelden zijn polyarteriitis nodosa en de ANCA-geassocieerde vasculitiden (granulomatose met polyangiitis, microscopische polyangiitis, EGPA). Ze kunnen nieren, longen, huid en zenuwen aantasten en vragen om immunosuppressie.</p>","image_url":"","wiki_title":"Vasculitis","match":"necrotiserende vasculitis","option_only":true},"agglutinatie":{"title":"Agglutinatie","short":"Agglutinatie is het samenklonteren van deeltjes of cellen doordat antistoffen ze met elkaar verbinden.","definition":"<p><strong>Agglutinatie</strong> wordt gebruikt bij bloedgroepbepaling (erytrocyten klonteren met anti-A of anti-B) en bij serologische tests. Vooral IgM, met tien bindingsplaatsen, is een sterke agglutinine. Koude agglutininen (IgM) komen voor bij <em>Mycoplasma</em>-infecties.</p>","image_url":"","wiki_title":"Agglutination (biology)","match":"agglutinatie|samenklontering","option_only":true},"mitochondriaal dna":{"title":"Mitochondriaal DNA","short":"Mitochondriaal DNA is het eigen circulaire DNA van mitochondriën, dat via de moeder wordt overgeërfd.","definition":"<p><strong>mtDNA</strong> codeert voor enkele eiwitten van de ademhalingsketen en voor rRNA en tRNA. Een cel bevat veel kopieën; bij een mutatie kunnen normale en afwijkende kopieën naast elkaar bestaan (heteroplasmie), wat de wisselende ernst verklaart. Voorbeelden zijn LHON en MELAS.</p>","image_url":"","wiki_title":"Mitochondrial DNA","match":"mitochondriaal dna|mtdna","option_only":true},"selectine receptoren":{"title":"Selectines","short":"Selectines zijn adhesiemoleculen die zwak en kortdurend koolhydraatliganden binden, waardoor leukocyten over het endotheel ‘rollen’.","definition":"<p>Er zijn drie <strong>selectines</strong>: E-selectine (endotheel), P-selectine (endotheel en bloedplaatjes) en L-selectine (leukocyten). Ze binden aan suikerstructuren zoals sialyl-Lewis X.</p>","image_url":"","wiki_title":"Selectin","match":"selectine receptoren|selectine|selectines","option_only":true},"chemokine receptoren":{"title":"Chemokinereceptoren","short":"Chemokinereceptoren zijn G-eiwitgekoppelde receptoren op leukocyten die chemokines herkennen en zo de migratie sturen.","definition":"<p>Via <strong>chemokinereceptoren</strong> worden leukocyten naar ontstekingshaarden en lymfeklieren geleid. CCR5 en CXCR4 dienen bovendien als co-receptor voor hiv; mensen zonder functioneel CCR5 zijn grotendeels resistent tegen de meeste hiv-stammen.</p>","image_url":"","wiki_title":"Chemokine receptor","match":"chemokine receptoren|chemokinereceptoren|cxcr4|ccr5","option_only":true},"oxidatieve burst":{"title":"Oxidatieve burst (respiratory burst)","short":"Bij de oxidatieve burst maken fagocyten met NADPH-oxidase snel grote hoeveelheden zuurstofradicalen om opgenomen micro-organismen te doden.","definition":"<p>NADPH-oxidase vormt superoxide, dat wordt omgezet in waterstofperoxide en (via myeloperoxidase) hypochloorzuur. Bij <strong>chronische granulomateuze ziekte</strong> ontbreekt dit enzym, met recidiverende infecties met catalasepositieve bacteriën en schimmels.</p>","image_url":"","wiki_title":"Respiratory burst","match":"oxidatieve burst|respiratory burst","option_only":true},"complementdeficiëntie":{"title":"Complementdeficiëntie","short":"Een complementdeficiëntie is een (erfelijk of verworven) tekort aan een eiwit van het complementsysteem.","definition":"<p>Tekorten aan <strong>vroege factoren</strong> (C1q, C2, C4) zijn geassocieerd met SLE; een tekort aan <strong>C3</strong> geeft ernstige infecties met gekapselde bacteriën; tekorten aan <strong>late factoren</strong> (C5–C9) geven recidiverende <em>Neisseria</em>-infecties. Een tekort aan C1-esteraseremmer geeft erfelijk angio-oedeem.</p>","image_url":"","wiki_title":"Complement deficiency","match":"complementdeficiëntie|complement deficiëntie","option_only":true},"severe combined immunodeficiency":{"title":"Severe combined immunodeficiency (SCID)","short":"SCID is een ernstige erfelijke afweerstoornis waarbij zowel T- als B-celafweer ontbreekt.","definition":"<p>Kinderen met <strong>SCID</strong> krijgen in de eerste maanden ernstige, recidiverende infecties, chronische diarree en groeiachterstand. Levende vaccins zijn gevaarlijk. Zonder stamceltransplantatie of gentherapie is het dodelijk; in Nederland wordt SCID opgespoord met de hielprik.</p>","image_url":"","wiki_title":"Severe combined immunodeficiency","match":"severe combined immunodeficiency|scid","option_only":true},"bulleus pemfigoid":{"title":"Bulleus pemfigoïd","short":"Bulleus pemfigoïd is een auto-immuunblaarziekte bij ouderen, met jeukende, strakke blaren door antistoffen tegen hemidesmosomen.","definition":"<p>Bij <strong>bulleus pemfigoïd</strong> (antistoffen tegen BP180 en BP230) ligt de splijting onder de epidermis, waardoor de blaren stevig zijn. Er gaat vaak een lange jeukende fase vooraf. Het slijmvlies is meestal gespaard, anders dan bij pemphigus vulgaris. Behandeling met sterke lokale of systemische corticosteroïden.</p>","image_url":"","wiki_title":"Bullous pemphigoid","match":"bulleus pemfigoid|bulleus pemfigoïd|pemfigoïd","option_only":true},"maligne melanoom":{"title":"Melanoom","short":"Het melanoom is een kwaadaardige tumor van melanocyten; vroeg ontdekt goed te behandelen, gemetastaseerd gevaarlijk.","definition":"<p>Risicofactoren voor een <strong>melanoom</strong> zijn zonverbranding (vooral in de jeugd), een lichte huid, veel of atypische moedervlekken en familiaire belasting. Waarschuwingssignalen (ABCDE): asymmetrie, onregelmatige grens, kleurverschillen, diameter &gt;6 mm en evolutie. De Breslow-dikte bepaalt de prognose; immunotherapie en doelgerichte therapie (BRAF) hebben de behandeling veranderd.</p>","image_url":"","wiki_title":"Melanoma","match":"maligne melanoom|melanoom","option_only":true},"igm":{"title":"IgM","short":"IgM is de eerste antistof die bij een nieuwe infectie wordt gemaakt; in het bloed is het een groot pentameer.","definition":"<p><strong>IgM</strong> heeft een lage affiniteit maar tien bindingsplaatsen, waardoor het goed agglutineert en complement activeert. Een verhoogd specifiek IgM wijst op een recente infectie. Het passeert de placenta niet; IgM bij een pasgeborene wijst daarom op een congenitale infectie.</p>","image_url":"","wiki_title":"Immunoglobulin M","match":"igm|immunoglobuline m","option_only":true},"igd":{"title":"IgD","short":"IgD komt vooral als membraanreceptor voor op naïeve B-cellen, samen met IgM.","definition":"<p>De functie van <strong>IgD</strong> is nog niet helemaal duidelijk; het speelt een rol bij de activatie van B-cellen. Vrij IgD in het bloed is laag.</p>","image_url":"","wiki_title":"Immunoglobulin D","match":"igd|immunoglobuline d","option_only":true},"mestcellen":{"title":"Mestcellen","short":"Mestcellen zijn weefselcellen vol korrels met histamine en andere mediatoren; ze spelen een sleutelrol bij allergie.","definition":"<p><strong>Mestcellen</strong> liggen vooral rond bloedvaten in huid, slijmvliezen en luchtwegen. Via IgE op FcεRI worden ze door allergenen geactiveerd, maar ook door complement (C3a, C5a), fysische prikkels en sommige geneesmiddelen. Ze geven histamine, tryptase, leukotriënen en prostaglandinen af.</p>","image_url":"","wiki_title":"Mast cell","match":"mestcellen|mestcel","option_only":true},"leukotriënen":{"title":"Leukotriënen","short":"Leukotriënen zijn ontstekingsmediatoren uit arachidonzuur (via lipoxygenase) die bronchoconstrictie en chemotaxis veroorzaken.","definition":"<p>Cysteinyl-<strong>leukotriënen</strong> (LTC4, LTD4, LTE4) geven sterke bronchoconstrictie, slijmproductie en vaatlekkage en spelen een rol bij astma; montelukast blokkeert hun receptor. LTB4 trekt neutrofielen aan.</p>","image_url":"","wiki_title":"Leukotriene","match":"leukotriënen|leukotrienen|leukotrieen","option_only":true},"lipoxines":{"title":"Lipoxines","short":"Lipoxines zijn ontstekingsremmende lipidemediatoren uit arachidonzuur die helpen een ontsteking te beëindigen.","definition":"<p><strong>Lipoxines</strong> remmen de rekrutering van neutrofielen en bevorderen het opruimen van apoptotische cellen door macrofagen. Ze horen bij de ‘pro-resolving’ mediatoren, samen met resolvines en protectines.</p>","image_url":"","wiki_title":"Lipoxin","match":"lipoxines|lipoxine a4","option_only":true},"toll-like receptoren":{"title":"Toll-like receptoren","short":"Toll-like receptoren zijn receptoren van de aangeboren afweer die vaste patronen van micro-organismen herkennen (PAMPs).","definition":"<p>Er zijn verschillende <strong>TLR's</strong>: bijv. TLR4 herkent LPS van gramnegatieve bacteriën, TLR2 lipoproteïnen en teichoïnezuur, TLR5 flagelline, en TLR3, 7, 8 en 9 virale en bacteriële nucleïnezuren. Activatie leidt via NF-κB tot productie van cytokines en activatie van de verworven afweer.</p>","image_url":"","wiki_title":"Toll-like receptor","match":"toll-like receptoren|toll-like receptor|tlr","option_only":true},"treg cellen":{"title":"Regulatoire T-cellen","short":"Regulatoire T-cellen remmen de afweerreactie en voorkomen auto-immuniteit.","definition":"<p><strong>Tregs</strong> brengen CD4, CD25 en de transcriptiefactor FOXP3 tot expressie en werken o.a. via IL-10, TGF-β en CTLA-4. Een erfelijk defect in FOXP3 geeft het IPEX-syndroom met ernstige auto-immuunziekte op jonge leeftijd.</p>","image_url":"","wiki_title":"Regulatory T cell","match":"treg cellen|treg|regulatoire t-cellen","option_only":true},"tgf-β":{"title":"TGF-β","short":"TGF-β is een cytokine dat de afweer remt, wondgenezing en fibrose bevordert en celgroei reguleert.","definition":"<p><strong>TGF-β</strong> stimuleert fibroblasten tot collageenproductie (fibrose), helpt bij het ontstaan van regulatoire en Th17-cellen en de klasseswitch naar IgA. Een te actieve TGF-β-signalering speelt een rol bij het syndroom van Marfan.</p>","image_url":"","wiki_title":"Transforming growth factor beta","match":"tgf-β|tgf-beta|transforming growth factor beta","option_only":true},"interleukine 2":{"title":"Interleukine-2","short":"IL-2 is een groeifactor voor T-cellen, gemaakt door geactiveerde T-cellen.","definition":"<p><strong>IL-2</strong> stimuleert de deling van T-cellen en is ook nodig voor regulatoire T-cellen. Calcineurineremmers (ciclosporine, tacrolimus) remmen de vorming van IL-2 en worden gebruikt na orgaantransplantatie.</p>","image_url":"","wiki_title":"Interleukin 2","match":"interleukine 2|il-2","option_only":true},"interleukines":{"title":"Interleukines","short":"Interleukines zijn cytokines die vooral door en tussen leukocyten signalen doorgeven.","definition":"<p>Voorbeelden van <strong>interleukines</strong>: IL-1 en IL-6 (koorts, acutefase-reactie), IL-2 (T-celgroei), IL-4, IL-5 en IL-13 (Th2, allergie), IL-10 (remmend), IL-12 (Th1), IL-17 (Th17, neutrofielen). Veel biologicals zijn tegen interleukines of hun receptoren gericht.</p>","image_url":"","wiki_title":"Interleukin","match":"interleukines|interleukine|interleukinen","option_only":true},"systemisch lupus erythematosus":{"title":"Systemische lupus erythematosus (SLE)","short":"SLE is een systemische auto-immuunziekte met antinucleaire antistoffen en immuuncomplexen; gewrichten, huid, nieren en bloed kunnen aangedaan zijn.","definition":"<p><strong>Systemische lupus erythematosus</strong> is een chronische auto-immuunziekte die vooral jonge vrouwen treft. Er worden antistoffen gevormd tegen kerncomponenten (ANA, anti-dsDNA, anti-Sm), die met antigenen <em>immuuncomplexen</em> vormen die neerslaan in weefsels (type III-reactie) en complement verbruiken.</p><p>Kenmerken: artralgie/artritis, vlindervormig erytheem in het gezicht, fotosensitiviteit, serositis, nefritis, cytopenieën en neurologische verschijnselen. Behandeling met o.a. hydroxychloroquine, corticosteroïden en immunosuppressiva.</p>","image_url":"","wiki_title":"Systemic lupus erythematosus","match":"systemisch lupus erythematosus","option_only":true},"plasmodium falciparum malaria":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"plasmodium falciparum malaria","option_only":true},"s. aureus":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"s. aureus","option_only":true},"jicht (artritis urica)":{"title":"Jicht","short":"Jicht is een gewrichtsontsteking door neerslag van uraatkristallen bij een verhoogd urinezuur.","definition":"<p>Bij <strong>jicht</strong> slaan mononatriumuraatkristallen neer in en rond gewrichten. Een aanval begint plotseling, vaak ’s nachts, met een rood, gezwollen, zeer pijnlijk gewricht. Uitlokkers zijn alcohol, purinerijk voedsel, diuretica en uitdroging. In het gewrichtsvocht zijn naaldvormige, negatief dubbelbrekende kristallen te zien. Behandeling van een aanval met NSAID's, colchicine of corticosteroïden; preventie met allopurinol.</p>","image_url":"","wiki_title":"Gout","match":"jicht (artritis urica)","option_only":true},"bacteri&euml;le conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies, met een rood oog, tranen of afscheiding en een branderig gevoel, zonder visusdaling.","definition":"<p><strong>Conjunctivitis</strong> kan viraal (vaak adenovirus, waterige afscheiding), bacterieel (purulente afscheiding) of allergisch (jeuk, beide ogen, seizoensgebonden) zijn. Het zicht is normaal en er is meestal geen echte pijn of lichtschuwheid; die passen eerder bij keratitis, uveïtis of glaucoom. Bij pasgeborenen moet aan chlamydia of gonokokken worden gedacht.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"bacteri&euml;le conjunctivitis","option_only":true},"bacteriële conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies, met een rood oog, tranen of afscheiding en een branderig gevoel, zonder visusdaling.","definition":"<p><strong>Conjunctivitis</strong> kan viraal (vaak adenovirus, waterige afscheiding), bacterieel (purulente afscheiding) of allergisch (jeuk, beide ogen, seizoensgebonden) zijn. Het zicht is normaal en er is meestal geen echte pijn of lichtschuwheid; die passen eerder bij keratitis, uveïtis of glaucoom. Bij pasgeborenen moet aan chlamydia of gonokokken worden gedacht.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"bacteriële conjunctivitis","option_only":true},"virale/banale conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies, met een rood oog, tranen of afscheiding en een branderig gevoel, zonder visusdaling.","definition":"<p><strong>Conjunctivitis</strong> kan viraal (vaak adenovirus, waterige afscheiding), bacterieel (purulente afscheiding) of allergisch (jeuk, beide ogen, seizoensgebonden) zijn. Het zicht is normaal en er is meestal geen echte pijn of lichtschuwheid; die passen eerder bij keratitis, uveïtis of glaucoom. Bij pasgeborenen moet aan chlamydia of gonokokken worden gedacht.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"virale/banale conjunctivitis","option_only":true},"bacteriële meningitis":{"title":"Meningitis","short":"Meningitis is een ontsteking van de hersenvliezen, met hoofdpijn, koorts, nekstijfheid en verminderd bewustzijn; bacteriële meningitis is een spoedgeval.","definition":"<p><strong>Meningitis</strong> is een ontsteking van de leptomeningen (pia en arachnoidea) en de liquor. Oorzaken zijn bacteriën (bij volwassenen vooral pneumokok en meningokok), virussen (vaak milder) en zelden schimmels.</p><p>Klassieke symptomen: hoofdpijn, koorts, nekstijfheid en een verlaagd bewustzijn; bij meningokokken soms petechiën. Diagnose via lumbaalpunctie (liquoronderzoek). Bacteriële meningitis vereist direct antibiotica en dexamethason.</p>","image_url":"","wiki_title":"Meningitis","match":"bacteriële meningitis","option_only":true},"oxycodon (een opiaat)":{"title":"Oxycodon","short":"Oxycodon is een sterk werkend opioïd voor (matig) ernstige pijn.","definition":"<p><strong>Oxycodon</strong> is een µ-opioïdreceptoragonist met een vergelijkbaar effect en bijwerkingenprofiel als morfine (obstipatie, sufheid, ademhalingsdepressie). Het wordt via de lever (CYP3A4, CYP2D6) omgezet en is daarom een alternatief bij nierfunctiestoornissen. Er zijn snel- en langwerkende vormen; misbruik is een probleem.</p>","image_url":"","wiki_title":"Oxycodone","match":"oxycodon (een opiaat)","option_only":true},"methotrexaat (een immunosuppressivum)":{"title":"Methotrexaat","short":"Methotrexaat is een foliumzuurantagonist; in lage dosis een basismiddel bij reumatoïde artritis en psoriasis, in hoge dosis een cytostaticum.","definition":"<p><strong>Methotrexaat</strong> remt dihydrofolaatreductase. In lage, wekelijkse dosering werkt het ontstekingsremmend (o.a. via adenosine) en is het een hoeksteen bij reumatoïde artritis, psoriasis en IBD; foliumzuur vermindert bijwerkingen. Bijwerkingen: beenmergsuppressie, levertoxiciteit, mucositis en pneumonitis. Het is teratogeen en wordt via de nier uitgescheiden.</p>","image_url":"","wiki_title":"Methotrexate","match":"methotrexaat (een immunosuppressivum)","option_only":true},"diclofenac (een nsaid)":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"diclofenac (een nsaid)","option_only":true},"een antihistaminicum":{"title":"Levocetirizine","short":"Levocetirizine is een tweede generatie H1-antihistaminicum dat weinig sufheid geeft; gebruikt bij hooikoorts en urticaria.","definition":"<p>Tweede generatie <strong>antihistaminica</strong> (cetirizine, levocetirizine, loratadine) blokkeren H1-receptoren en passeren de bloed-hersenbarrière nauwelijks, waardoor ze minder sederend en anticholinerg zijn dan de eerste generatie (zoals clemastine). Ze verminderen jeuk, niezen, waterige neus en netelroos.</p>","image_url":"","wiki_title":"Levocetirizine","match":"een antihistaminicum","option_only":true},"een corticosteroïd":{"title":"Corticosteroïden","short":"Corticosteroïden zijn van cortisol afgeleide middelen met sterke ontstekingsremmende en immunosuppressieve werking.","definition":"<p>Glucocorticoïden binden aan een intracellulaire receptor en remmen de transcriptie van ontstekingsgenen (cytokines, COX-2) en de vorming van ontstekingsmediatoren. Ze worden lokaal (huid, inhalatie, injectie) en systemisch gebruikt. Bij langdurig systemisch gebruik: osteoporose, hyperglykemie, gewichtstoename, huidatrofie, infecties, spierzwakte, cataract en remming van de eigen bijnier (niet abrupt stoppen).</p>","image_url":"","wiki_title":"Corticosteroid","match":"een corticosteroïd","option_only":true},"een beta-agonist":{"title":"Salbutamol","short":"Salbutamol is een kortwerkende β2-agonist die binnen minuten de luchtwegen verwijdt; gebruikt bij astma- en COPD-aanvallen.","definition":"<p><strong>Salbutamol</strong> ontspant de gladde spier van de bronchi via β2-receptoren en cAMP. Het werkt binnen enkele minuten en ongeveer 4–6 uur. Het wordt via een dosisaerosol met voorzetkamer of als verneveling gegeven. Bijwerkingen: tremor, tachycardie en een daling van het kalium (het wordt daarom ook gebruikt bij hyperkaliëmie).</p>","image_url":"","wiki_title":"Salbutamol","match":"een beta-agonist","option_only":true},"herpes simplex type 2":{"title":"Herpes genitalis","short":"Herpes genitalis is een seksueel overdraagbare infectie met HSV-2 of HSV-1, met pijnlijke blaasjes en zweertjes in het genitale gebied.","definition":"<p>Bij <strong>herpes genitalis</strong> ontstaan na besmetting pijnlijke groepjes blaasjes die openbreken tot oppervlakkige ulcera, vaak met koorts, pijn bij het plassen en vergrote lieslymfeklieren. Het virus blijft latent in de sacrale ganglia en kan recidiveren. Een primaire infectie rond de bevalling geeft een groot risico op neonatale herpes.</p>","image_url":"","wiki_title":"Genital herpes","match":"herpes simplex type 2","option_only":true},"een granulomateuze ontsteking":{"title":"Granulomateuze ontsteking","short":"Bij een granulomateuze ontsteking vormen macrofagen (epitheloïde cellen en reuscellen) compacte haarden: granulomen.","definition":"<p><strong>Granulomen</strong> ontstaan bij persisterende antigenen die moeilijk op te ruimen zijn, via een Th1/IFN-γ-gedreven reactie. Voorbeelden: tuberculose (met centrale verkazing), sarcoïdose (niet-verkazend), lepra, schimmels, de ziekte van Crohn, granulomatose met polyangiitis en vreemdlichaamreacties.</p>","image_url":"","wiki_title":"Granulomatous inflammation","match":"een granulomateuze ontsteking","option_only":true},"factoren van het complementsysteem":{"title":"Complement","short":"Het complementsysteem is een cascade van plasma-eiwitten die micro-organismen opsoneert, ontsteking aanjaagt en via het membraanaanvalscomplex cellen lyseert.","definition":"<p>Het <strong>complementsysteem</strong> bestaat uit plasma-eiwitten (C1–C9 en regulatoren) die in een cascade worden geactiveerd via de klassieke (antilichamen), de lectine- en de alternatieve route.</p><p>Belangrijke functies: <em>opsonisatie</em> (C3b), aantrekken van ontstekingscellen en mestcelactivatie (anafylatoxinen C3a en C5a) en lysis van micro-organismen door het <em>membraanaanvalscomplex</em> (C5b–C9). Tekort aan late complementfactoren geeft een verhoogd risico op <em>Neisseria</em>-infecties.</p>","image_url":"","wiki_title":"Complement system","match":"factoren van het complementsysteem","option_only":true},"echo van de lever":{"title":"Echo abdomen","short":"Een echo abdomen is een echografisch onderzoek van de buikorganen; zonder straling en goed voor galblaas, galwegen, lever, nieren en vrij vocht.","definition":"<p>Bij een <strong>echo abdomen</strong> wordt met geluidsgolven een beeld gemaakt van de buikorganen. Het onderzoek gebruikt geen ioniserende straling, is goedkoop en direct beschikbaar.</p><p>Het is bijzonder geschikt voor het aantonen van galstenen en cholecystitis, verwijde galwegen, leverafwijkingen, nierstuwing (hydronefrose), een abdominaal aorta-aneurysma en vrij vocht. Darmgas en een dikke buikwand beperken het zicht; de kwaliteit hangt af van de onderzoeker.</p>","image_url":"","wiki_title":"Abdominal ultrasonography","match":"echo van de lever","option_only":true},"type 2 diabetes mellitus":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"type 2 diabetes mellitus","option_only":true},"de ziekte van sjögren":{"title":"Syndroom van Sjögren","short":"Het syndroom van Sjögren is een auto-immuunziekte van de traan- en speekselklieren, met droge ogen en een droge mond.","definition":"<p>Bij <strong>Sjögren</strong> infiltreren lymfocyten de exocriene klieren. Daarnaast kunnen gewrichtsklachten, vermoeidheid, neuropathie en nierbetrokkenheid optreden. Er zijn vaak anti-SSA/SSB-antistoffen. Het risico op een (MALT-)lymfoom is verhoogd. Het kan primair of samen met andere auto-immuunziekten voorkomen.</p>","image_url":"","wiki_title":"Sjögren syndrome","match":"de ziekte van sjögren","option_only":true},"th2 lymfocyten":{"title":"Th2-cellen","short":"Th2-cellen zijn CD4-T-helpercellen die via IL-4, IL-5 en IL-13 de afweer tegen parasieten en allergische reacties sturen.","definition":"<p><strong>Th2-cellen</strong> ontstaan onder invloed van IL-4. Ze stimuleren B-cellen tot de productie van IgE (IL-4, IL-13), activeren eosinofielen (IL-5) en bevorderen slijmproductie. Ze spelen een centrale rol bij allergie, allergisch astma en atopisch eczeem; biologicals tegen IL-4/IL-13 en IL-5 remmen deze route.</p>","image_url":"","wiki_title":"T helper cell","match":"th2 lymfocyten","option_only":true},"pneumocystis jiroveci":{"title":"Pneumocystis jirovecii","short":"Pneumocystis jirovecii is een gistachtige schimmel die bij een sterk verminderde cellulaire afweer een interstitiële longontsteking veroorzaakt.","definition":"<p><strong>Pneumocystis</strong> groeit niet in standaardkweek en wordt aangetoond met PCR of zilverkleuring op sputum of BAL. Risicogroepen: hiv met laag CD4-getal, transplantatiepatiënten, langdurig hoge dosis corticosteroïden. Behandeling en profylaxe met co-trimoxazol.</p>","image_url":"","wiki_title":"Pneumocystis jirovecii","match":"pneumocystis jiroveci|pneumocystis jirovecii|pcp|pjp","option_only":true},"hepatocellulair carcinoom":{"title":"Hepatocellulair carcinoom (HCC)","short":"Het hepatocellulair carcinoom is primaire leverkanker uitgaand van hepatocyten, meestal in een cirrotische lever.","definition":"<p><strong>HCC</strong> ontstaat vooral bij cirrose door alcohol, NASH of chronische hepatitis B en C (bij hepatitis B ook zonder cirrose). Patiënten met cirrose worden halfjaarlijks gescreend met echo, eventueel met AFP. Behandeling hangt af van tumorgrootte en leverfunctie: resectie, ablatie, transplantatie of systemische therapie.</p>","image_url":"","wiki_title":"Hepatocellular carcinoma","match":"hepatocellulair carcinoom|hcc|levercelcarcinoom","option_only":true},"keloïd":{"title":"Keloïd","short":"Een keloïd is een verheven, stevig litteken door excessieve collageenvorming, dat buiten de grenzen van de oorspronkelijke wond groeit.","definition":"<p><strong>Keloïden</strong> komen vaker voor bij een donkere huid en op oorlellen, borst en schouders. Ze verdwijnen niet vanzelf en komen na excisie vaak terug. Een hypertrofisch litteken blijft daarentegen binnen de wondgrenzen en kan in de loop van de tijd verbeteren.</p>","image_url":"","wiki_title":"Keloid","match":"keloïd|keloid","option_only":true},"integrines":{"title":"Integrines","short":"Integrines zijn adhesiemoleculen die cellen aan elkaar of aan de extracellulaire matrix koppelen.","definition":"<p><strong>Integrines</strong> zijn heterodimeren (α- en β-keten) die binnen in de cel aan het cytoskelet vastzitten. Op leukocyten (LFA-1, Mac-1) zorgen ze na activatie voor stevige hechting aan ICAM's op het endotheel. Op bloedplaatjes is GPIIb/IIIa een integrine.</p>","image_url":"","wiki_title":"Integrin","match":"integrines|integrine","option_only":true},"prostaglandine":{"title":"Prostaglandinen","short":"Prostaglandinen zijn lokaal werkende lipidemediatoren uit arachidonzuur, gevormd via cyclo-oxygenase.","definition":"<p><strong>Prostaglandinen</strong> zijn betrokken bij ontsteking, pijn en koorts (PGE2), maagbescherming, nierdoorbloeding, de baring en het openhouden van de ductus arteriosus. Prostacycline (PGI2) uit het endotheel remt plaatjesaggregatie en verwijdt vaten; tromboxaan A2 uit plaatjes doet het omgekeerde. NSAID's remmen hun vorming.</p>","image_url":"","wiki_title":"Prostaglandin","match":"prostaglandine|prostaglandinen|prostaglandine pgi2|prostacycline","option_only":true},"elastase":{"title":"Elastase","short":"Elastase is een eiwitsplitsend enzym (o.a. uit neutrofielen en pancreas) dat elastine en andere matrixeiwitten afbreekt.","definition":"<p><strong>Neutrofielenelastase</strong> helpt bij het doden van bacteriën en het opruimen van weefsel, maar kan bij overmaat longweefsel beschadigen. α1-antitrypsine remt het; een tekort daaraan geeft emfyseem. Fecaal elastase wordt gemeten om de exocriene pancreasfunctie te beoordelen.</p>","image_url":"","wiki_title":"Elastase","match":"elastase|elastases|neutrofielenelastase","option_only":true},"histaminase":{"title":"Histaminase (diamineoxidase)","short":"Histaminase (diamineoxidase) breekt histamine af, vooral in de darm.","definition":"<p><strong>Diamineoxidase</strong> beperkt de opname en werking van histamine uit voedsel. Eosinofielen bevatten het ook en kunnen zo de werking van histamine bij allergische ontsteking dempen.</p>","image_url":"","wiki_title":"Diamine oxidase","match":"histaminase|diamineoxidase","option_only":true},"decay accelerating factor, daf":{"title":"Decay-accelerating factor (CD55)","short":"DAF (CD55) is een eiwit op het celoppervlak dat complementactivatie op lichaamseigen cellen remt.","definition":"<p><strong>DAF</strong> versnelt het uiteenvallen van de C3-convertase. Bij <strong>paroxismale nachtelijke hemoglobinurie</strong> ontbreken DAF en CD59 op bloedcellen (door een PIG-A-mutatie), waardoor complement rode bloedcellen afbreekt, met hemolyse en trombose.</p>","image_url":"","wiki_title":"Decay-accelerating factor","match":"decay accelerating factor, daf|decay accelerating factor|daf|cd55","option_only":true},"mediane halscyste":{"title":"Mediane halscyste (ductus thyroglossus-cyste)","short":"Een mediane halscyste is een restant van de ductus thyroglossus en geeft een zwelling in de middellijn van de hals die meebeweegt bij slikken en tong uitsteken.","definition":"<p>Tijdens de ontwikkeling daalt de schildklier af vanaf de tongbasis. Een open gebleven deel van de <strong>ductus thyroglossus</strong> kan een cyste vormen, vaak bij het tongbeen, die kan ontsteken. Behandeling met de operatie van Sistrunk (inclusief het middendeel van het tongbeen).</p>","image_url":"","wiki_title":"Thyroglossal cyst","match":"mediane halscyste|ductus thyroglossus cyste|thyreoglossuscyste","option_only":true},"iga deficiëntie":{"title":"Selectieve IgA-deficiëntie","short":"Selectieve IgA-deficiëntie is de meest voorkomende primaire immuundeficiëntie; veel mensen hebben geen klachten.","definition":"<p>Bij <strong>IgA-deficiëntie</strong> kunnen recidiverende luchtweg- en darminfecties, giardiasis, coeliakie en auto-immuunziekten voorkomen. Bij coeliakie-serologie moet het totaal-IgA worden bepaald, omdat IgA-antistoffen vals-negatief kunnen zijn. Bij transfusies kan een anafylactische reactie op IgA in donorbloed optreden.</p>","image_url":"","wiki_title":"Selective immunoglobulin A deficiency","match":"iga deficiëntie|iga-deficiëntie|selectieve iga-deficiëntie","option_only":true},"functio laesa":{"title":"Functio laesa","short":"Functio laesa (functieverlies) is een van de vijf klassieke kenmerken van ontsteking.","definition":"<p>De klassieke tekenen van ontsteking zijn rubor (roodheid), calor (warmte), tumor (zwelling), dolor (pijn) en <strong>functio laesa</strong>, dat door Virchow werd toegevoegd. Het functieverlies ontstaat door pijn, zwelling en weefselschade.</p>","image_url":"","wiki_title":"Inflammation","match":"functio laesa|functieverlies","option_only":true},"dolor":{"title":"Dolor (pijn)","short":"Dolor (pijn) is een van de klassieke kenmerken van ontsteking, veroorzaakt door mediatoren zoals bradykinine en prostaglandinen.","definition":"<p>Bij ontsteking prikkelen <strong>bradykinine</strong> en prostaglandinen (PGE2) de pijnreceptoren, en drukt de zwelling op het weefsel. NSAID's verminderen de pijn door de vorming van prostaglandinen te remmen.</p>","image_url":"","wiki_title":"Inflammation","match":"dolor","option_only":true},"levercarcinoom":{"title":"Hepatocellulair carcinoom (HCC)","short":"Het hepatocellulair carcinoom is primaire leverkanker uitgaand van hepatocyten, meestal in een cirrotische lever.","definition":"<p><strong>HCC</strong> ontstaat vooral bij cirrose door alcohol, NASH of chronische hepatitis B en C (bij hepatitis B ook zonder cirrose). Patiënten met cirrose worden halfjaarlijks gescreend met echo, eventueel met AFP. Behandeling hangt af van tumorgrootte en leverfunctie: resectie, ablatie, transplantatie of systemische therapie.</p>","image_url":"","wiki_title":"Hepatocellular carcinoma","match":"levercarcinoom","option_only":true},"keloïdvorming":{"title":"Keloïd","short":"Een keloïd is een verheven, stevig litteken door excessieve collageenvorming, dat buiten de grenzen van de oorspronkelijke wond groeit.","definition":"<p><strong>Keloïden</strong> komen vaker voor bij een donkere huid en op oorlellen, borst en schouders. Ze verdwijnen niet vanzelf en komen na excisie vaak terug. Een hypertrofisch litteken blijft daarentegen binnen de wondgrenzen en kan in de loop van de tijd verbeteren.</p>","image_url":"","wiki_title":"Keloid","match":"keloïdvorming","option_only":true},"prostaglandinen":{"title":"Prostaglandinen","short":"Prostaglandinen zijn lokaal werkende lipidemediatoren uit arachidonzuur, gevormd via cyclo-oxygenase.","definition":"<p><strong>Prostaglandinen</strong> zijn betrokken bij ontsteking, pijn en koorts (PGE2), maagbescherming, nierdoorbloeding, de baring en het openhouden van de ductus arteriosus. Prostacycline (PGI2) uit het endotheel remt plaatjesaggregatie en verwijdt vaten; tromboxaan A2 uit plaatjes doet het omgekeerde. NSAID's remmen hun vorming.</p>","image_url":"","wiki_title":"Prostaglandin","match":"prostaglandinen","option_only":true},"elastases":{"title":"Elastase","short":"Elastase is een eiwitsplitsend enzym (o.a. uit neutrofielen en pancreas) dat elastine en andere matrixeiwitten afbreekt.","definition":"<p><strong>Neutrofielenelastase</strong> helpt bij het doden van bacteriën en het opruimen van weefsel, maar kan bij overmaat longweefsel beschadigen. α1-antitrypsine remt het; een tekort daaraan geeft emfyseem. Fecaal elastase wordt gemeten om de exocriene pancreasfunctie te beoordelen.</p>","image_url":"","wiki_title":"Elastase","match":"elastases","option_only":true},"a. carotis communis":{"title":"A. carotis communis","short":"De a. carotis communis loopt in de hals omhoog en splitst ter hoogte van het schildkraakbeen in de a. carotis interna en externa.","definition":"<p>Rechts komt de <strong>a. carotis communis</strong> uit de truncus brachiocephalicus, links rechtstreeks uit de aortaboog. Bij de splitsing liggen de sinus caroticus (baroreceptoren) en het glomus caroticum (chemoreceptoren). De carotispols is lateraal van het strottenhoofd voelbaar.</p>","image_url":"","wiki_title":"Common carotid artery","match":"a. carotis communis|arteria carotis communis|a.carotis|halsslagader","option_only":true},"colchicine":{"title":"Colchicine","short":"Colchicine remt de polymerisatie van microtubuli in neutrofielen en wordt gebruikt bij jicht, pericarditis en familiaire mediterrane koorts.","definition":"<p><strong>Colchicine</strong> vermindert de migratie en activatie van neutrofielen en remt het inflammasoom. Bij een jichtaanval werkt het het best als het vroeg wordt gestart. Bijwerkingen: diarree, misselijkheid en bij overdosering of nierfalen ernstige toxiciteit. Interacties met o.a. claritromycine.</p>","image_url":"","wiki_title":"Colchicine","match":"colchicine","option_only":true},"allopurinol":{"title":"Allopurinol","short":"Allopurinol remt xanthineoxidase en verlaagt zo het urinezuur; het wordt gebruikt ter preventie van jicht en tumorlysis.","definition":"<p><strong>Allopurinol</strong> wordt geleidelijk opgehoogd tot het urinezuur onder de streefwaarde is. Starten tijdens een aanval kan die verergeren; vaak wordt colchicine erbij gegeven. Een ernstige maar zeldzame bijwerking is een overgevoeligheidsreactie met huidafwijkingen (risico groter bij HLA-B*58:01). Het versterkt de werking van azathioprine.</p>","image_url":"","wiki_title":"Allopurinol","match":"allopurinol|xanthineoxidaseremmer","option_only":true},"fagosoom":{"title":"Fagosoom","short":"Een fagosoom is het blaasje waarin een fagocyt een opgenomen deeltje of micro-organisme insluit; na fusie met een lysosoom ontstaat een fagolysosoom.","definition":"<p>In het <strong>fagolysosoom</strong> wordt het opgenomen materiaal afgebroken door enzymen, een lage pH en zuurstofradicalen (oxidatieve burst). Sommige micro-organismen, zoals mycobacteriën, voorkomen de fusie met lysosomen en overleven zo in macrofagen.</p>","image_url":"","wiki_title":"Phagosome","match":"fagosoom|fagolysosoom","option_only":true},"bronchodilatatie":{"title":"Bronchodilatatie","short":"Bronchodilatatie is verwijding van de luchtwegen door ontspanning van de gladde spier in de wand.","definition":"<p><strong>Bronchodilatatie</strong> ontstaat via β2-stimulatie (salbutamol, formoterol) of via blokkade van muscarinereceptoren (ipratropium, tiotropium). De reversibiliteitstest meet de verbetering van de FEV1 na een luchtwegverwijder: een duidelijke verbetering past bij astma.</p>","image_url":"","wiki_title":"Bronchodilator","match":"bronchodilatatie|luchtwegverwijding|bronchusverwijder","option_only":true},"vasoconstrictie":{"title":"Vasoconstrictie","short":"Vasoconstrictie is vernauwing van bloedvaten door samentrekking van de gladde spier in de vaatwand.","definition":"<p><strong>Vasoconstrictie</strong> wordt veroorzaakt door o.a. sympathische activatie (α1), angiotensine II, endotheline, vasopressine en kou. Het verhoogt de bloeddruk en stuurt bloed naar vitale organen, bijvoorbeeld bij bloedverlies. In de long trekken vaten juist samen bij hypoxie.</p>","image_url":"","wiki_title":"Vasoconstriction","match":"vasoconstrictie|vaatvernauwing|perifere vasoconstrictie","option_only":true},"hemoglobine":{"title":"Hemoglobine","short":"Hemoglobine is het eiwit in rode bloedcellen dat zuurstof bindt en vervoert.","definition":"<p>Volwassen <strong>hemoglobine</strong> (HbA) bestaat uit twee alfa- en twee bètaketens, elk met een heemgroep met ijzer. De zuurstofbinding is coöperatief (S-vormige dissociatiecurve); een lagere pH, hogere CO₂, temperatuur en 2,3-BPG verschuiven de curve naar rechts (makkelijker afgifte). Foetaal Hb (HbF) heeft een hogere affiniteit voor zuurstof.</p>","image_url":"","wiki_title":"Hemoglobin","match":"hemoglobine|hb","option_only":true},"acute middenoorontsteking":{"title":"Otitis media acuta","short":"Otitis media acuta is een acute middenoorontsteking met oorpijn, koorts en een rood, bomberend trommelvlies.","definition":"<p><strong>Acute otitis media</strong> komt vooral bij jonge kinderen voor, vaak na een verkoudheid; verwekkers zijn virussen en bacteriën (pneumokok, <em>H. influenzae</em>, <em>Moraxella</em>). Een loopoor ontstaat bij perforatie van het trommelvlies. Meestal geneest het spontaan; pijnstilling is de basis, antibiotica alleen bij risicofactoren of ernstig beloop.</p>","image_url":"","wiki_title":"Otitis media","match":"acute middenoorontsteking","option_only":true},"katalase":{"title":"Catalase","short":"Catalase is een enzym dat waterstofperoxide omzet in water en zuurstof; bacteriën met catalase (zoals stafylokokken) zijn catalasepositief.","definition":"<p><strong>Catalase</strong> breekt <em>waterstofperoxide</em> af: 2 H<sub>2</sub>O<sub>2</sub> → 2 H<sub>2</sub>O + O<sub>2</sub>. In menselijke cellen zit het vooral in de peroxisomen en beschermt het tegen oxidatieve schade.</p><p>In de microbiologie is de catalasetest een snelle manier om grampositieve kokken te onderscheiden: <em>stafylokokken</em> zijn catalasepositief (bruisen met H<sub>2</sub>O<sub>2</sub>), <em>streptokokken</em> catalasenegatief. Catalasepositieve micro-organismen zijn ook beter bestand tegen de oxidatieve burst van fagocyten.</p>","image_url":"","wiki_title":"Catalase","match":"katalase","option_only":true},"common variable immunodeficiency":{"title":"Common variable immunodeficiency (CVID)","short":"CVID is een primaire afweerstoornis met te weinig antistoffen (IgG en IgA en/of IgM), met recidiverende luchtweginfecties.","definition":"<p>Bij <strong>CVID</strong> ontstaan vaak pas op jongvolwassen leeftijd herhaalde sinusitis, bronchitis en pneumonieën, met bronchiëctasieën als gevolg. Er is ook meer kans op auto-immuunziekten, granulomen en lymfomen. Behandeling met immunoglobulinesuppletie.</p>","image_url":"","wiki_title":"Common variable immunodeficiency","match":"common variable immunodeficiency|cvid","option_only":true},"mannose-bindend lectine":{"title":"Mannosebindend lectine (MBL)","short":"Mannosebindend lectine herkent suikers op micro-organismen en activeert de lectineroute van het complementsysteem.","definition":"<p><strong>MBL</strong> is een acutefase-eiwit uit de lever. Een tekort komt vaak voor en geeft meestal weinig klachten, maar kan bij jonge kinderen of in combinatie met andere afweerproblemen het infectierisico verhogen.</p>","image_url":"","wiki_title":"Mannan-binding lectin","match":"mannose-bindend lectine|mbl|lectineroute","option_only":true},"interferon-γ":{"title":"Interferon-γ","short":"Interferon-γ is het belangrijkste cytokine van Th1-cellen en NK-cellen; het activeert macrofagen om intracellulaire micro-organismen te doden.","definition":"<p><strong>IFN-γ</strong> is essentieel bij de afweer tegen mycobacteriën en andere intracellulaire verwekkers en speelt een rol bij granuloomvorming. De IGRA-test meet IFN-γ-productie na stimulatie met tbc-antigenen, om latente tuberculose aan te tonen.</p>","image_url":"","wiki_title":"Interferon gamma","match":"interferon-γ|ifn-γ|interferon gamma","option_only":true},"mmp-3":{"title":"Matrixmetalloproteïnasen (MMP's)","short":"Matrixmetalloproteïnasen zijn enzymen die de extracellulaire matrix afbreken, bij weefselremodellering, ontsteking en tumorinvasie.","definition":"<p><strong>MMP's</strong> (zoals collagenasen en stromelysine/MMP-3) worden geremd door TIMP's. Ze zijn nodig bij wondgenezing en ontwikkeling, maar dragen bij aan kraakbeenafbraak bij artritis, aneurysmavorming en metastasering van tumoren.</p>","image_url":"","wiki_title":"Matrix metalloproteinase","match":"mmp-3|mmp|matrixmetalloproteïnase|matrixmetalloproteinasen","option_only":true},"neuspoliep":{"title":"Neuspoliepen","short":"Neuspoliepen zijn goedaardige, druppelvormige zwellingen van het slijmvlies van neus en bijholten, met een verstopte neus en reukverlies.","definition":"<p><strong>Neuspoliepen</strong> horen bij chronische rhinosinusitis, vaak met astma en soms met overgevoeligheid voor aspirine (triade van Samter/Widal). Bij kinderen moet aan cystische fibrose worden gedacht. Behandeling met corticosteroïdneusspray, kortdurend orale steroïden of chirurgie.</p>","image_url":"","wiki_title":"Nasal polyp","match":"neuspoliep|neuspoliepen","option_only":true},"endocriene pancreas":{"title":"Pancreas","short":"De pancreas is zowel een exocriene klier (verteringsenzymen en bicarbonaat naar het duodenum) als een endocriene klier (insuline en glucagon uit de eilandjes van Langerhans).","definition":"<p>De <strong>pancreas</strong> ligt retroperitoneaal achter de maag, met de kop in de bocht van het duodenum.</p><p>Het <em>exocriene</em> deel (±98%) maakt verteringsenzymen (trypsine(ogeen), lipase, amylase) en bicarbonaatrijk sap, dat via de ductus pancreaticus samen met de galweg in het duodenum uitmondt. Het <em>endocriene</em> deel bestaat uit de eilandjes van Langerhans met bètacellen (insuline), alfacellen (glucagon) en deltacellen (somatostatine).</p>","image_url":"","wiki_title":"Pancreas","match":"endocriene pancreas","option_only":true},"exocriene pancreas":{"title":"Pancreas","short":"De pancreas is zowel een exocriene klier (verteringsenzymen en bicarbonaat naar het duodenum) als een endocriene klier (insuline en glucagon uit de eilandjes van Langerhans).","definition":"<p>De <strong>pancreas</strong> ligt retroperitoneaal achter de maag, met de kop in de bocht van het duodenum.</p><p>Het <em>exocriene</em> deel (±98%) maakt verteringsenzymen (trypsine(ogeen), lipase, amylase) en bicarbonaatrijk sap, dat via de ductus pancreaticus samen met de galweg in het duodenum uitmondt. Het <em>endocriene</em> deel bestaat uit de eilandjes van Langerhans met bètacellen (insuline), alfacellen (glucagon) en deltacellen (somatostatine).</p>","image_url":"","wiki_title":"Pancreas","match":"exocriene pancreas","option_only":true},"jichtartritis":{"title":"Jicht","short":"Jicht is een gewrichtsontsteking door neerslag van uraatkristallen bij een verhoogd urinezuur.","definition":"<p>Bij <strong>jicht</strong> slaan mononatriumuraatkristallen neer in en rond gewrichten. Een aanval begint plotseling, vaak ’s nachts, met een rood, gezwollen, zeer pijnlijk gewricht. Uitlokkers zijn alcohol, purinerijk voedsel, diuretica en uitdroging. In het gewrichtsvocht zijn naaldvormige, negatief dubbelbrekende kristallen te zien. Behandeling van een aanval met NSAID's, colchicine of corticosteroïden; preventie met allopurinol.</p>","image_url":"","wiki_title":"Gout","match":"jichtartritis","option_only":true},"levercirrose":{"title":"Levercirrose","short":"Bij levercirrose is het leverweefsel vervangen door bindweefsel en regeneratieknobbels, met verlies van leverfunctie en portale hypertensie.","definition":"<p>Oorzaken van <strong>cirrose</strong> zijn o.a. alcohol, NASH, chronische hepatitis B en C, auto-immuunziekten en hemochromatose. Gevolgen: ascites, varices met bloedingen, hepatische encefalopathie, icterus, stollingsstoornissen en een verhoogd risico op hepatocellulair carcinoom. Ernst wordt ingedeeld met Child-Pugh of MELD.</p>","image_url":"","wiki_title":"Cirrhosis","match":"levercirrose|cirrose|cirrhose","option_only":true},"tuberculose (mycobacterium tuberculosis)":{"title":"Tuberculose","short":"Tuberculose is een infectie met Mycobacterium tuberculosis, meestal in de longen, met langdurig hoesten, nachtzweten, gewichtsverlies en granulomen.","definition":"<p><strong>Tuberculose</strong> wordt veroorzaakt door <em>Mycobacterium tuberculosis</em> en verspreidt zich via aerosolen. Na infectie wordt de bacterie meestal ingekapseld in granulomen (latente tbc); bij verminderde afweer kan actieve ziekte ontstaan.</p><p>Longtuberculose geeft langdurig hoesten (soms met bloed), koorts, nachtzweten en gewichtsverlies; typisch zijn holtevorming in de longtoppen en granulomen met centrale <em>verkazing</em>. Behandeling met een combinatie van tuberculostatica gedurende minstens 6 maanden.</p>","image_url":"","wiki_title":"Tuberculosis","match":"tuberculose (mycobacterium tuberculosis)","option_only":true},"intercellulair adhesie molecuul 1":{"title":"ICAM-1","short":"ICAM-1 is een adhesiemolecuul op geactiveerd endotheel dat via integrines (LFA-1) leukocyten stevig laat binden.","definition":"<p><strong>ICAM-1</strong> behoort tot de immunoglobuline-superfamilie en wordt door IL-1 en TNF op endotheel tot expressie gebracht. Het bindt aan integrines zoals LFA-1 en Mac-1 op leukocyten, wat vaste adhesie en transmigratie mogelijk maakt. ICAM-1 is ook de receptor voor de meeste rhinovirussen.</p>","image_url":"","wiki_title":"ICAM-1","match":"intercellulair adhesie molecuul 1","option_only":true},"icam (intercellulair adhesiemolecuul)":{"title":"ICAM-1","short":"ICAM-1 is een adhesiemolecuul op geactiveerd endotheel dat via integrines (LFA-1) leukocyten stevig laat binden.","definition":"<p><strong>ICAM-1</strong> behoort tot de immunoglobuline-superfamilie en wordt door IL-1 en TNF op endotheel tot expressie gebracht. Het bindt aan integrines zoals LFA-1 en Mac-1 op leukocyten, wat vaste adhesie en transmigratie mogelijk maakt. ICAM-1 is ook de receptor voor de meeste rhinovirussen.</p>","image_url":"","wiki_title":"ICAM-1","match":"icam (intercellulair adhesiemolecuul)","option_only":true},"malaria tropica":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"malaria tropica","option_only":true},"plasmodium falciparum-malaria":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"plasmodium falciparum-malaria","option_only":true},"plasmodium vivax-malaria":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"plasmodium vivax-malaria","option_only":true},"plasmodium spp":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"plasmodium spp","option_only":true},"malariaparasiet":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"malariaparasiet","option_only":true},"astma-aanval":{"title":"Astma","short":"Astma is een chronische ontsteking van de luchtwegen met wisselende, reversibele luchtwegobstructie en hyperreactiviteit; klachten zijn piepen, benauwdheid en hoesten.","definition":"<p>Bij <strong>astma</strong> zijn de luchtwegen chronisch ontstoken (vaak eosinofiel/Th2-gemedieerd) en <em>hyperreactief</em>: op prikkels zoals allergenen, inspanning, koude lucht of rook ontstaan bronchoconstrictie, slijmvliesoedeem en slijmproductie.</p><p>De obstructie is variabel en grotendeels <em>reversibel</em> (verbetering van de FEV1 na een luchtwegverwijder). Klachten: aanvallen van piepen, kortademigheid, een beklemd gevoel op de borst en hoesten, vaak ’s nachts. Behandeling met inhalatiecorticosteroïden en luchtwegverwijders.</p>","image_url":"","wiki_title":"Asthma","match":"astma-aanval","option_only":true},"astma-exacerbatie":{"title":"Astma","short":"Astma is een chronische ontsteking van de luchtwegen met wisselende, reversibele luchtwegobstructie en hyperreactiviteit; klachten zijn piepen, benauwdheid en hoesten.","definition":"<p>Bij <strong>astma</strong> zijn de luchtwegen chronisch ontstoken (vaak eosinofiel/Th2-gemedieerd) en <em>hyperreactief</em>: op prikkels zoals allergenen, inspanning, koude lucht of rook ontstaan bronchoconstrictie, slijmvliesoedeem en slijmproductie.</p><p>De obstructie is variabel en grotendeels <em>reversibel</em> (verbetering van de FEV1 na een luchtwegverwijder). Klachten: aanvallen van piepen, kortademigheid, een beklemd gevoel op de borst en hoesten, vaak ’s nachts. Behandeling met inhalatiecorticosteroïden en luchtwegverwijders.</p>","image_url":"","wiki_title":"Asthma","match":"astma-exacerbatie","option_only":true},"anti-dsdna":{"title":"Anti-dsDNA-antistoffen","short":"Anti-dsDNA-antistoffen zijn auto-antistoffen tegen dubbelstrengs DNA en zeer specifiek voor systemische lupus erythematodes (SLE).","definition":"<p>De titer van <strong>anti-dsDNA</strong> stijgt vaak bij ziekteactiviteit, vooral bij lupusnefritis, samen met een daling van complement (C3, C4). Een positieve ANA is gevoelig maar weinig specifiek; anti-dsDNA en anti-Sm zijn juist specifiek.</p>","image_url":"","wiki_title":"Anti-dsDNA antibodies","match":"anti-dsdna|anti-dubbelstrengs dna antistoffen|anti-dsdna-antistoffen","option_only":true},"anti-dubbelstrengs dna antistoffen":{"title":"Anti-dsDNA-antistoffen","short":"Anti-dsDNA-antistoffen zijn auto-antistoffen tegen dubbelstrengs DNA en zeer specifiek voor systemische lupus erythematodes (SLE).","definition":"<p>De titer van <strong>anti-dsDNA</strong> stijgt vaak bij ziekteactiviteit, vooral bij lupusnefritis, samen met een daling van complement (C3, C4). Een positieve ANA is gevoelig maar weinig specifiek; anti-dsDNA en anti-Sm zijn juist specifiek.</p>","image_url":"","wiki_title":"Anti-dsDNA antibodies","match":"anti-dubbelstrengs dna antistoffen","option_only":true},"cd4":{"title":"CD4","short":"Celoppervlaktemolecuul op onder andere T-helpercellen; dient als receptor waaraan het hiv-virus zich hecht.","definition":"<p><b>CD4</b> is een glycoproteïne op het oppervlak van T-helperlymfocyten (en enkele andere cellen). Het humaan immunodeficiëntievirus (hiv) gebruikt CD4 (samen met een co-receptor) om aan de cel te binden en die binnen te dringen.</p>","image_url":"","wiki_title":"","match":"cd4","option_only":true},"prostaglandine pgi2":{"title":"Prostaglandinen","short":"Prostaglandinen zijn lokaal werkende lipidemediatoren uit arachidonzuur, gevormd via cyclo-oxygenase.","definition":"<p><strong>Prostaglandinen</strong> zijn betrokken bij ontsteking, pijn en koorts (PGE2), maagbescherming, nierdoorbloeding, de baring en het openhouden van de ductus arteriosus. Prostacycline (PGI2) uit het endotheel remt plaatjesaggregatie en verwijdt vaten; tromboxaan A2 uit plaatjes doet het omgekeerde. NSAID's remmen hun vorming.</p>","image_url":"","wiki_title":"Prostaglandin","match":"prostaglandine pgi2","option_only":true},"cd3":{"title":"CD3","short":"Eiwitcomplex dat samen met de TCR het T-celreceptorcomplex vormt en de signaaltransductie na antigeenherkenning verzorgt; onmisbaar voor T-celontwikkeling en -activatie.","definition":"<p><b>CD3</b> bestaat uit meerdere ketens die niet-covalent gekoppeld zijn aan de αβ-TCR. Terwijl de TCR het peptide-MHC herkent, geeft CD3 het intracellulaire signaal door. Zonder CD3 worden er nauwelijks naïeve T cellen gevormd omdat T-celontwikkeling in de thymus afhankelijk is van functionele TCR-signalering.</p>","image_url":"","wiki_title":"CD3 (immunology)","match":"cd3","option_only":true},"c5a":{"title":"C5a","short":"Complementsplitsproduct (anafylatoxine) dat sterk chemotactisch is voor neutrofielen en de vaatpermeabiliteit verhoogt.","definition":"<p><b>C5a</b> ontstaat bij complementactivatie en is een krachtig anafylatoxine. Het trekt neutrofielen en monocyten aan (chemotaxis), activeert deze cellen en verhoogt samen met C3a de doorlaatbaarheid van de vaatwand.</p>","image_url":"","wiki_title":"Complement component 5a","match":"c5a","option_only":true},"monocyten":{"title":"Monocyt","short":"Grootste witte bloedcel; verlaat het bloed en rijpt in de weefsels uit tot macrofaag of dendritische cel.","definition":"<p>De <b>monocyt</b> is de grootste circulerende leukocyt, met een niervormige kern. Hij circuleert enkele dagen en migreert dan de weefsels in.</p><p>Daar differentieert hij tot macrofaag of dendritische cel, die pathogenen fagocyteren en antigenen presenteren.</p>","image_url":"","wiki_title":"Monocyte","match":"monocyten","option_only":true},"heesheid":{"title":"Heesheid","short":"Verandering van de stemkwaliteit (hese, schorre stem) door aandoening van de stembanden of larynx.","definition":"<p>Heesheid (dysfonie) ontstaat bij afwijkingen van de stemplooien of hun innervatie. Aanhoudende heesheid (>3 weken) bij een roker is een alarmsymptoom voor larynxcarcinoom.</p>","image_url":"","wiki_title":"Hoarse voice","match":"heesheid","option_only":true},"fibrose":{"title":"Fibrose","short":"Overmatige neerslag van bindweefsel (collageen) in een orgaan, doorgaans als eindstadium van chronische schade of ontsteking.","definition":"<p><b>Fibrose</b> is de vervanging van functioneel weefsel door collageenrijk littekenweefsel. In de long leidt dit tot verstijving en verstoorde gaswisseling; in de lever is uitgebreide fibrose met architectuurverstoring de basis van cirrose.</p>","image_url":"","wiki_title":"Fibrosis","match":"fibrose","option_only":true},"de epidermis":{"title":"Epidermis","short":"De opperhuid: het bovenste, uit meerlagig verhoornend plaveiselepitheel opgebouwde deel van de huid.","definition":"<p>De <b>epidermis</b> (opperhuid) is de buitenste huidlaag, opgebouwd uit meerlagig verhoornend plaveiselepitheel zonder bloedvaten.</p><p>Ze bestaat vooral uit keratinocyten in opeenvolgende lagen (basale → hoornlaag) en levert de beschermende barrière.</p>","image_url":"","wiki_title":"Epidermis","match":"de epidermis","option_only":true},"a.carotis":{"title":"A. carotis communis","short":"De a. carotis communis loopt in de hals omhoog en splitst ter hoogte van het schildkraakbeen in de a. carotis interna en externa.","definition":"<p>Rechts komt de <strong>a. carotis communis</strong> uit de truncus brachiocephalicus, links rechtstreeks uit de aortaboog. Bij de splitsing liggen de sinus caroticus (baroreceptoren) en het glomus caroticum (chemoreceptoren). De carotispols is lateraal van het strottenhoofd voelbaar.</p>","image_url":"","wiki_title":"Common carotid artery","match":"a.carotis","option_only":true},"hepatocyt":{"title":"Hepatocyten","short":"Hepatocyten zijn de levercellen die vrijwel alle metabole, synthetiserende en ontgiftende functies van de lever uitvoeren.","definition":"<p><strong>Hepatocyten</strong> vormen ±80% van het levervolume. Ze liggen in balkjes langs de sinusoïden en hebben veel mitochondriën, glad en ruw ER en Golgi.</p><p>Ze maken plasma-eiwitten (albumine, stollingsfactoren), gal, glucose (gluconeogenese) en ureum, slaan glycogeen, vet en vitamines op en ontgiften stoffen via het cytochroom P450-systeem. Tussen naburige hepatocyten liggen de galcanaliculi.</p>","image_url":"","wiki_title":"Hepatocyte","match":"hepatocyt","option_only":true},"nk-cellen":{"title":"NK-cellen","short":"Cytotoxische cellen van de aangeboren afweer die geïnfecteerde of tumorcellen doden zonder voorafgaande sensibilisatie.","definition":"<p><b>Natural killer (NK)-cellen</b> herkennen cellen met afwijkende of afwezige MHC-I ('missing self') en beklede doelwitten via ADCC. Ze doden zonder eerdere sensibilisatie en zijn belangrijk tegen virussen en tumoren.</p>","image_url":"","wiki_title":"Natural killer cell","match":"nk-cellen","option_only":true},"tgfβ":{"title":"TGF-β","short":"TGF-β is een cytokine dat de afweer remt, wondgenezing en fibrose bevordert en celgroei reguleert.","definition":"<p><strong>TGF-β</strong> stimuleert fibroblasten tot collageenproductie (fibrose), helpt bij het ontstaan van regulatoire en Th17-cellen en de klasseswitch naar IgA. Een te actieve TGF-β-signalering speelt een rol bij het syndroom van Marfan.</p>","image_url":"","wiki_title":"Transforming growth factor beta","match":"tgfβ","option_only":true},"cd59":{"title":"CD59","short":"CD59 (protectine) is een GPI-verankerd complementregulerend eiwit op lichaamseigen cellen.","definition":"<p><b>CD59</b> bindt aan C8 en C9 van het complementsysteem. Bij paroxismale nachtelijke hemoglobinurie (PNH) ontbreken GPI-verankerde eiwitten zoals CD55 (DAF) en CD59, met hemolyse als gevolg.</p>","image_url":"","wiki_title":"CD59","match":"cd59","option_only":true},"vasculogenese":{"title":"Vasculogenese","short":"Vasculogenese is de aanleg van nieuwe bloedvaten uit endotheel-voorlopers (angioblasten) tijdens de embryonale ontwikkeling.","definition":"<p><strong>Vasculogenese</strong> is de de-novo vorming van bloedvaten door aggregatie en differentiatie van angioblasten in het embryo, in tegenstelling tot angiogenese die uit bestaande vaten vertrekt.</p>","image_url":"","wiki_title":"Vasculogenesis","match":"vasculogenese","option_only":true},"cytotoxines":{"title":"Cytotoxines","short":"Effectormoleculen (o.a. perforine en granzymen) in de granula van CD8+ T-cellen en NK-cellen die doelcellen doden.","definition":"<p><b>Cytotoxines</b> zijn dodende effectormoleculen die zijn opgeslagen in de granula van cytotoxische CD8+ T-cellen en NK-cellen. Perforine maakt poriën en granzymen induceren apoptose in de doelcel.</p>","image_url":"","wiki_title":"Cytotoxic T cell","match":"cytotoxines","option_only":true},"cytokines":{"title":"Cytokines","short":"Oplosbare signaaleiwitten (o.a. interleukines en interferonen) waarmee immuuncellen elkaar reguleren.","definition":"<p><b>Cytokines</b> zijn kleine signaaleiwitten die celgroei, differentiatie en immuunreacties sturen. Interleukines en interferonen behoren tot de cytokines; ze werken vaak lokaal en op korte afstand.</p>","image_url":"","wiki_title":"Cytokine","match":"cytokines","option_only":true},"sjögren syndroom":{"title":"Sjögren-syndroom","short":"Auto-immuunziekte met lymfocytaire infiltratie van speeksel- en traanklieren; kenmerkend zijn een droge mond en droge ogen (sicca).","definition":"<p>Het <b>syndroom van Sjögren</b> is een auto-immuunziekte gericht tegen exocriene klieren. Aantasting van traan- en speekselklieren geeft het kenmerkende <b>sicca-syndroom</b>: droge ogen en droge mond. Vaak zijn SS-A- en SS-B-antistoffen aanwezig.</p>","image_url":"","wiki_title":"Sjögren syndrome","match":"sjögren syndroom","option_only":true},"aid":{"title":"AID (activation-induced cytidine deaminase)","short":"Enzym dat essentieel is voor isotypeswitch en somatische hypermutatie in B-cellen.","definition":"<p><b>AID</b> (activation-induced cytidine deaminase) deamineert cytosine in het immunoglobulinegen-DNA en initieert zo zowel <b>isotype switching</b> als somatische hypermutatie. Zonder AID blijven B-cellen alleen IgM maken (hyper-IgM syndroom type 2).</p>","image_url":"","wiki_title":"Activation-induced cytidine deaminase","match":"aid","option_only":true},"chemotaxis":{"title":"Chemotaxis","short":"Gerichte migratie van cellen (zoals leukocyten) langs een concentratiegradiënt van chemische lokstoffen richting de hoogste concentratie.","definition":"<p><b>Chemotaxis</b> is de beweging van cellen in de richting van (of weg van) een chemische stof. Bij ontsteking migreren neutrofielen en monocyten langs een gradiënt van chemokines en complementfactoren (o.a. C5a) naar de plaats van infectie.</p>","image_url":"","wiki_title":"Chemotaxis","match":"chemotaxis","option_only":true},"eosinofiele granulocyten":{"title":"Eosinofiele granulocyt","short":"Witte bloedcel met rood-kleurende korrels, actief bij afweer tegen parasieten en bij allergie.","definition":"<p>De <b>eosinofiele granulocyt</b> heeft korrels die met eosine roodroze aankleuren en meestal een tweelobbige kern.</p><p>Hij is betrokken bij de afweer tegen wormparasieten en bij allergische processen zoals astma en eczeem; het aantal is dan vaak verhoogd.</p>","image_url":"","wiki_title":"Eosinophil","match":"eosinofiele granulocyten","option_only":true},"lymfadenitis colli":{"title":"Lymfadenitis colli","short":"Lymfadenitis colli is een ontsteking van de lymfeklieren in de hals, o.a. bij tuberculose of kattenkrabziekte.","definition":"<p><strong>Lymfadenitis colli</strong> is een halsklierontsteking die kan verkleven met de huid en abcederen; ze komt onder meer voor bij tuberculose en de kattenkrabziekte.</p>","image_url":"","wiki_title":"","match":"lymfadenitis colli","option_only":true},"thromboxanen":{"title":"Thromboxanen","short":"Uit arachidonzuur gevormde eicosanoïden die bloedplaatjesaggregatie en vaatvernauwing bevorderen.","definition":"<p><b>Thromboxaan A2</b> wordt door bloedplaatjes gemaakt via cyclo-oxygenase en stimuleert plaatjesaggregatie en vasoconstrictie; aspirine remt dit.</p>","image_url":"","wiki_title":"Thromboxane","match":"thromboxanen","option_only":true},"paf":{"title":"PAF (platelet activating factor)","short":"PAF is een lipide-mediator die o.a. bronchoconstrictie en vasodilatatie veroorzaakt bij ontsteking.","definition":"<p><strong>Platelet activating factor</strong> is een fosfolipide-mediator die bloedplaatjes activeert en in de ontsteking bronchoconstrictie, verhoogde vaatpermeabiliteit en vasodilatatie induceert.</p>","image_url":"","wiki_title":"Platelet-activating factor","match":"paf","option_only":true},"aa-proteïne":{"title":"AA-proteïne","short":"Amyloïdeiwit afkomstig van serum-amyloïd A, kenmerkend voor secundaire (reactieve) amyloïdose.","definition":"<p><b>AA-amyloïd</b> ontstaat uit het acute-fase-eiwit serum-amyloïd A (SAA). Langdurige ontsteking of auto-immuunziekte houdt SAA-productie hoog, wat leidt tot AA-amyloïdose.</p>","image_url":"","wiki_title":"AA amyloidosis","match":"aa-proteïne","option_only":true},"tlr-4":{"title":"TLR4 (Toll-like receptor 4)","short":"Patroonherkenningsreceptor van aangeboren immuuncellen die vooral LPS van gram-negatieve bacteriën herkent en de cel aanzet tot productie van pro-inflammatoire mediatoren.","definition":"<p><b>TLR4</b> is een Toll-like receptor op o.a. macrofagen die bacterieel lipopolysaccharide (LPS) herkent. Signaaltransductie via TLR4 zet de cel aan tot aanmaak van cytokines en andere ontstekingsmediatoren; bij een defect blijft deze respons uit.</p>","image_url":"","wiki_title":"TLR4","match":"tlr-4","option_only":true},"anergie":{"title":"Anergie","short":"Gebrek aan (fysieke) energie en verhoogde vermoeidheid; veelvoorkomend symptoom bij depressie.","definition":"<p><strong>Anergie</strong> verwijst naar een aanhoudend gebrek aan energie en verhoogde moeheid. Het is een frequent symptoom bij depressieve stoornissen.</p>","image_url":"","wiki_title":"","match":"anergie","option_only":true},"purulente (suppuratieve) ontsteking":{"title":"Purulente ontsteking","short":"Ontsteking met vorming van pus (etter): dode neutrofielen, weefseldebris en oedeemvocht, meestal door pyogene bacteriën.","definition":"<p><b>Purulente (etterige) ontsteking</b> wordt gekenmerkt door productie van pus, bestaande uit grote aantallen neutrofielen, necrotisch weefsel en vocht. Een afgekapselde purulente haard heet een abces.</p>","image_url":"","wiki_title":"Pus","match":"purulente (suppuratieve) ontsteking","option_only":true},"clemastine":{"title":"Clemastine","short":"Klassiek antihistaminicum (H1-blokker) dat de directe, histamine-gemedieerde verschijnselen van een allergische reactie snel dempt.","definition":"<p><b>Clemastine</b> is een H1-antihistaminicum dat de werking van door mestcellen afgegeven histamine blokkeert. Daardoor heeft het snel effect op de acute symptomen (jeuk, urticaria) van een allergische reactie, in tegenstelling tot het traag werkende corticosteroïd.</p>","image_url":"","wiki_title":"Clemastine","match":"clemastine","option_only":true},"b lymfocyten":{"title":"B-cellen","short":"B-cellen zijn lymfocyten die na activatie uitrijpen tot plasmacellen die antilichamen maken; ze rijpen in het beenmerg.","definition":"<p><strong>B-cellen</strong> ontstaan en rijpen in het beenmerg. Elke B-cel draagt een unieke B-celreceptor (membraangebonden antilichaam).</p><p>Na binding van een antigeen en meestal hulp van een T-helpercel (in de kiemcentra van lymfeklieren) prolifereren ze en differentiëren ze tot <em>plasmacellen</em> (antilichaamproductie) en geheugen-B-cellen. Daarbij vinden klasseswitch en affiniteitsrijping plaats. B-cellen kunnen ook antigeen presenteren.</p>","image_url":"","wiki_title":"B cell","match":"b lymfocyten","option_only":true},"t lymfocyten":{"title":"T-cellen","short":"T-cellen zijn lymfocyten die in de thymus rijpen en antigeen herkennen dat via MHC wordt gepresenteerd; CD4-cellen helpen, CD8-cellen doden geïnfecteerde cellen.","definition":"<p><strong>T-cellen</strong> ontstaan in het beenmerg en rijpen in de <em>thymus</em>, waar positieve en negatieve selectie plaatsvindt. Hun T-celreceptor herkent alleen peptiden die door MHC-moleculen worden gepresenteerd.</p><p><em>CD4⁺ T-helpercellen</em> herkennen MHC-II en sturen de afweer met cytokines (Th1, Th2, Th17, Tfh); <em>CD8⁺ cytotoxische T-cellen</em> herkennen MHC-I en doden geïnfecteerde of tumorcellen; regulatoire T-cellen remmen de afweer. Ze vormen de cellulaire adaptieve immuniteit.</p>","image_url":"","wiki_title":"T cell","match":"t lymfocyten","option_only":true},"eilandjes van langerhans":{"title":"Eilandjes van Langerhans","short":"Endocriene celgroepen in de pancreas met α-cellen (glucagon), β-cellen (insuline) en δ-cellen (somatostatine).","definition":"<p>De <b>eilandjes van Langerhans</b> reguleren de glucosehuishouding; bij diabetes type 2 tonen ze hyperplasie en later amyloïd-depositie.</p>","image_url":"","wiki_title":"Pancreatic islets","match":"eilandjes van langerhans","option_only":true},"toll like receptoren":{"title":"Toll-like receptoren","short":"Toll-like receptoren zijn receptoren van de aangeboren afweer die vaste patronen van micro-organismen herkennen (PAMPs).","definition":"<p>Er zijn verschillende <strong>TLR's</strong>: bijv. TLR4 herkent LPS van gramnegatieve bacteriën, TLR2 lipoproteïnen en teichoïnezuur, TLR5 flagelline, en TLR3, 7, 8 en 9 virale en bacteriële nucleïnezuren. Activatie leidt via NF-κB tot productie van cytokines en activatie van de verworven afweer.</p>","image_url":"","wiki_title":"Toll-like receptor","match":"toll like receptoren","option_only":true},"creactive protein":{"title":"C-reactive protein (CRP)","short":"Een acute-fase eiwit dat aan pathogeenoppervlakken (fosfocholine) bindt en zo als opsonine dient en de klassieke complementroute kan starten.","definition":"<p><b>C-reactive protein (CRP)</b> is een pentameer acute-fase eiwit dat door de lever wordt gemaakt onder invloed van IL-6. Het bindt aan fosfocholine op micro-organismen en beschadigde cellen, werkt als opsonine en activeert het complementsysteem via de klassieke route (C1q). Het bloedgehalte stijgt snel bij ontsteking en wordt klinisch als ontstekingsmarker gebruikt.</p>","image_url":"","wiki_title":"C-reactive protein","match":"creactive protein","option_only":true},"arachidonzuur":{"title":"Arachidonzuur","short":"Vetzuur dat de grondstof vormt voor prostaglandinen (via COX) en leukotriënen (via lipoxygenase).","definition":"<p><b>Arachidonzuur</b> is een meervoudig onverzadigd vetzuur dat als uitgangsstof dient voor twee routes: via <b>COX</b> naar prostaglandinen en via <b>lipoxygenase</b> naar leukotriënen. Remming van de COX-route (door NSAID's) kan de arachidonzuurstroom naar de leukotriënenroute verschuiven.</p>","image_url":"","wiki_title":"Arachidonic acid","match":"arachidonzuur","option_only":true},"nk cellen":{"title":"NK-cellen","short":"Cytotoxische cellen van de aangeboren afweer die geïnfecteerde of tumorcellen doden zonder voorafgaande sensibilisatie.","definition":"<p><b>Natural killer (NK)-cellen</b> herkennen cellen met afwijkende of afwezige MHC-I ('missing self') en beklede doelwitten via ADCC. Ze doden zonder eerdere sensibilisatie en zijn belangrijk tegen virussen en tumoren.</p>","image_url":"","wiki_title":"Natural killer cell","match":"nk cellen","option_only":true},"prostaglandines":{"title":"Prostaglandines","short":"Lipide-signaalmoleculen die uit arachidonzuur worden gemaakt via cyclo-oxygenase en o.a. ontsteking, pijn en vaattonus reguleren.","definition":"<p><b>Prostaglandines</b> zijn eicosanoïden die uit arachidonzuur ontstaan via COX-enzymen en lokaal werken op vaatwand, bloedstelping en ontstekingsreacties.</p>","image_url":"","wiki_title":"Prostaglandin","match":"prostaglandines","option_only":true},"superoxide dismutase":{"title":"Superoxide dismutase (SOD1)","short":"Antioxidant-enzym; mutaties erin zijn een oorzaak van (familiaire) ALS.","definition":"<p>Enzym dat superoxide-radicalen onschadelijk maakt. Mutaties in het SOD1-gen veroorzaken een deel van de erfelijke vormen van amyotrofische laterale sclerose.</p>","image_url":"","wiki_title":"Superoxide dismutase","match":"superoxide dismutase","option_only":true},"anti-nucleaire factor":{"title":"Antinucleaire antistoffen (ANA)","short":"Antinucleaire antistoffen zijn auto-antistoffen tegen kerncomponenten; een positieve ANA past bij SLE en andere bindweefselziekten, maar is weinig specifiek.","definition":"<p>De <strong>ANA</strong> wordt bepaald met immunofluorescentie. Ze is bijna altijd positief bij SLE (gevoelig), maar ook bij Sjögren, systemische sclerose, geneesmiddel-lupus en bij een deel van de gezonde mensen (vooral ouderen). Daarom wordt bij een positieve ANA verder gekeken naar specifieke antistoffen (dsDNA, Sm, SSA, SSB, Scl-70).</p>","image_url":"","wiki_title":"Antinuclear antibody","match":"anti-nucleaire factor","option_only":true},"ige":{"title":"IgE (immunoglobuline E)","short":"Antilichaamklasse die centraal staat bij allergische reacties en de afweer tegen parasieten.","definition":"<p><b>IgE</b> is de antistofklasse die bindt aan mestcellen en basofielen. Bij hernieuwd contact met een allergeen leidt kruisbinding van IgE tot degranulatie en de symptomen van een allergische reactie.</p>","image_url":"","wiki_title":"Immunoglobulin E","match":"ige","option_only":true},"virale conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies met een rood oog, waterig, slijmerig of etterig vocht, en een normale visus.","definition":"<p>Een <strong>virale conjunctivitis</strong> (vaak adenovirus) is zeer besmettelijk, met waterig vocht en een gezwollen klier voor het oor. Een bacteriële vorm geeft meer pus en dichtgeplakte ogen; een allergische vorm jeuk. Pijn, lichtschuwheid en verminderde visus wijzen op een ernstigere oorzaak.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"virale conjunctivitis|bacteriële conjunctivitis|allergische conjunctivitis","option_only":true},"bloedkweek":{"title":"Bloedkweek","short":"Een bloedkweek onderzoekt of er bacteriën of schimmels in het bloed zitten (bacteriëmie).","definition":"<p>Bij verdenking op sepsis of endocarditis worden minimaal twee sets <strong>bloedkweken</strong> afgenomen vóór het starten van antibiotica. Een kweek met huidbacteriën (bijv. coagulasenegatieve stafylokokken) in één fles is vaak een verontreiniging.</p>","image_url":"","wiki_title":"Blood culture","match":"bloedkweek|bloedkweken","option_only":true},"een granuloom":{"title":"Granuloom","short":"Een granuloom is een ophoping van geactiveerde macrofagen (epitheloïde cellen), vaak met reuscellen, rond een moeilijk afbreekbare prikkel.","definition":"<p><strong>Granulomen</strong> ontstaan bij tuberculose (met centrale verkazing), sarcoïdose, de ziekte van Crohn, schimmelinfecties en reacties op vreemd materiaal. Ze ontstaan via Th1-cellen en IFN-γ. Een abces bestaat juist uit granulocyten en pus.</p>","image_url":"","wiki_title":"Granuloma","match":"een granuloom|granuloom|granulomateuze ontsteking","option_only":true},"prostaglandine d2":{"title":"Eicosanoïden","short":"Eicosanoïden (prostaglandinen, tromboxanen en leukotriënen) zijn ontstekingsmediatoren die uit arachidonzuur ontstaan.","definition":"<p>Via <strong>cyclo-oxygenase</strong> ontstaan prostaglandinen (PGE2: koorts, pijn; PGI2: vaatverwijding) en tromboxaan (plaatjesaggregatie). Via <strong>lipoxygenase</strong> ontstaan leukotriënen: LTB4 trekt neutrofielen aan, LTC4/D4/E4 geven bronchoconstrictie. PGD2 komt vrij uit mestcellen bij allergie.</p>","image_url":"","wiki_title":"Eicosanoid","match":"prostaglandine d2|leukotriënen|leukotrieën b4|prostaglandine e2|tromboxaan a2","option_only":true},"interleukine 4":{"title":"IL-4, IL-5 en IL-13 (type 2-cytokines)","short":"IL-4, IL-5 en IL-13 zijn cytokines van Th2-cellen die allergische ontsteking en de afweer tegen wormen sturen.","definition":"<p><strong>IL-4</strong> laat B-cellen overschakelen naar IgE, <strong>IL-5</strong> stimuleert eosinofielen, en IL-13 geeft slijmproductie en luchtweghyperreactiviteit. Biologicals tegen IL-5 (mepolizumab) en de IL-4-receptor (dupilumab) worden gebruikt bij ernstig astma en eczeem.</p>","image_url":"","wiki_title":"Interleukin 4","match":"interleukine 4|il-4|interleukine 5|il-5|il-13","option_only":true},"calor":{"title":"Klassieke ontstekingsverschijnselen","short":"De klassieke verschijnselen van een acute ontsteking zijn rubor (roodheid), calor (warmte), tumor (zwelling), dolor (pijn) en functio laesa (functieverlies).","definition":"<p>Roodheid en warmte komen door vaatverwijding, zwelling door toegenomen vaatdoorlaatbaarheid (oedeem), en pijn door mediatoren zoals bradykinine en prostaglandinen.</p>","image_url":"","wiki_title":"Inflammation","match":"calor|rubor|tumor|dolor|functio laesa","option_only":true},"α1-antitrypsine":{"title":"Alfa-1-antitrypsine","short":"Alfa-1-antitrypsine is een eiwit uit de lever dat elastase van neutrofielen remt; een erfelijk tekort geeft longemfyseem en leverziekte.","definition":"<p>Bij een <strong>alfa-1-antitrypsinedeficiëntie</strong> (vooral het PiZZ-genotype) ontstaat op jonge leeftijd een panlobulair emfyseem in de onderkwabben, versneld door roken. Het afwijkende eiwit stapelt in de lever, met cirrose. Het is ook een acutefase-eiwit.</p>","image_url":"","wiki_title":"Alpha-1 antitrypsin deficiency","match":"α1-antitrypsine|alfa-1-antitrypsine|a1at","option_only":true},"complementfixatie":{"title":"Complementactivatie","short":"Bij complementactivatie (fixatie) binden complementeiwitten aan antistoffen of microben, met opsonisatie, aantrekking van afweercellen en lysis.","definition":"<p>Het complement kan via drie routes worden geactiveerd: de <strong>klassieke</strong> route (via IgM en IgG), de lectineroute en de alternatieve route. C3b werkt als opsonine, C5a lokt ontsteking uit en C5b-9 vormt het membrane attack complex.</p>","image_url":"","wiki_title":"Complement system","match":"complementfixatie|complement eiwitten|complementactivatie","option_only":true},"scavenger receptor":{"title":"Patroonherkennende receptoren","short":"Scavenger- en mannosereceptoren op macrofagen herkennen moleculen op microben en beschadigde cellen en helpen ze op te nemen.","definition":"<p>Ze horen bij de <strong>patroonherkennende receptoren</strong> van de aangeboren afweer, net als Toll-like receptoren. Scavengerreceptoren nemen ook geoxideerd LDL op, waardoor bij atherosclerose schuimcellen ontstaan.</p>","image_url":"","wiki_title":"Scavenger receptor","match":"scavenger receptor|mannosereceptor|mannose receptoren|toll-like receptor","option_only":true},"a. facialis":{"title":"A. facialis, a. temporalis superficialis en a. maxillaris","short":"De a. facialis, a. temporalis superficialis en a. maxillaris zijn slagaders van gezicht, schedel en kaak.","definition":"<p>De <strong>a. facialis</strong> is voelbaar aan de rand van de onderkaak voor de m. masseter. De <strong>a. temporalis superficialis</strong> is voelbaar voor het oor en is bij arteriitis temporalis verdikt en drukpijnlijk. De a. maxillaris geeft o.a. de a. meningea media af.</p>","image_url":"","wiki_title":"External carotid artery","match":"a. facialis|a. temporalis superficialis|a. maxillaris|a. lingualis","option_only":true},"lymfe endotheel cellen":{"title":"Hoogendotheel-venulen (HEV)","short":"Hoogendotheel-venulen zijn speciale bloedvaten in lymfeklieren waardoor naïeve lymfocyten vanuit het bloed de klier binnengaan.","definition":"<p>Lymfocyten herkennen het endotheel van de <strong>HEV</strong> via L-selectine en chemokines (CCR7). Lymfatisch endotheel bekleedt daarentegen de lymfevaten die lymfe en dendritische cellen naar de klier voeren.</p>","image_url":"","wiki_title":"High endothelial venules","match":"lymfe endotheel cellen|hoog endotheel cellen|hoogendotheel venulen|hev","option_only":true},"dermatofibroom":{"title":"Dermatofibroom","short":"Een dermatofibroom is een goedaardig, hard knobbeltje in de huid, vaak op de benen, dat bij knijpen naar binnen zakt.","definition":"<p>Het positieve <strong>‘dimple sign’</strong> is kenmerkend. Een dermatofibroom ontstaat soms na een insectenbeet of klein wondje en hoeft niet te worden behandeld.</p>","image_url":"","wiki_title":"Dermatofibroma","match":"dermatofibroom","option_only":true},"hypertrofisch littekenweefsel":{"title":"Hypertrofisch litteken en keloïd","short":"Een hypertrofisch litteken is verdikt en rood maar blijft binnen de grenzen van de oorspronkelijke wond; een keloïd groeit daar juist buiten.","definition":"<p><strong>Hypertrofische littekens</strong> ontstaan vaak na brandwonden en wonden onder spanning en worden in de loop van de tijd vaak vlakker. Keloïden komen vaker voor bij een donkere huid en recidiveren na excisie. Behandeling: drukkleding, siliconen en corticosteroïdinjecties.</p>","image_url":"","wiki_title":"Hypertrophic scar","match":"hypertrofisch littekenweefsel|hypertrofisch litteken|keloïd","option_only":true},"adhesiemoleculen":{"title":"Adhesiemoleculen","short":"Adhesiemoleculen (selectines, integrines en ICAM's) zorgen ervoor dat leukocyten aan het endotheel binden en de bloedbaan kunnen verlaten.","definition":"<p>De migratie van leukocyten verloopt in stappen: rollen via <strong>selectines</strong>, stevig vasthechten via integrines aan ICAM-1/VCAM-1, en daarna diapedese door de vaatwand richting chemokines (chemotaxie). Bij een tekort aan integrines (LAD) ontstaan ernstige bacteriële infecties zonder pus.</p>","image_url":"","wiki_title":"Cell adhesion molecule","match":"adhesiemoleculen|selectines|integrines|icam-1","option_only":true},"chemotaxie":{"title":"Chemotaxie","short":"Chemotaxie is de gerichte beweging van cellen langs een concentratieverschil van een lokstof, zoals chemokines.","definition":"<p>Neutrofielen worden o.a. aangetrokken door <strong>IL-8</strong> (CXCL8), C5a, LTB4 en bacteriële peptiden. Zo komen afweercellen op de plek van een infectie terecht.</p>","image_url":"","wiki_title":"Chemotaxis","match":"chemotaxie|chemokines","option_only":true},"klasse switching van b-cellen":{"title":"Klassenswitch (isotypeswitch)","short":"Bij een klassenswitch gaat een B-cel van IgM over op het maken van IgG, IgA of IgE met dezelfde specificiteit.","definition":"<p>De <strong>klassenswitch</strong> vindt plaats in kiemcentra en vereist hulp van T-cellen (CD40-CD40L) en cytokines. Bij een defect in CD40L (hyper-IgM-syndroom) is het IgM hoog en ontbreken IgG, IgA en IgE.</p>","image_url":"","wiki_title":"Immunoglobulin class switching","match":"klasse switching van b-cellen|klassenswitch|isotypeswitch","option_only":true},"m1 macrofagen":{"title":"M1- en M2-macrofagen","short":"M1-macrofagen (klassiek geactiveerd, via IFN-γ) doden microben en geven ontsteking; M2-macrofagen (alternatief geactiveerd, via IL-4/IL-13) helpen bij weefselherstel en fibrose.","definition":"<p>Deze indeling is een vereenvoudiging van een spectrum aan <strong>macrofaagactivatie</strong>. Tumorgeassocieerde macrofagen lijken vaak op M2-macrofagen en kunnen de tumorgroei bevorderen.</p>","image_url":"","wiki_title":"Macrophage polarization","match":"m1 macrofagen|m2 macrofagen","option_only":true},"weefselgebonden antigenen":{"title":"Overgevoeligheidsreacties type II en III","short":"Bij een type II-overgevoeligheid richten antistoffen zich tegen antigenen op cellen of in weefsel; bij type III slaan immuuncomplexen uit de circulatie neer in vaatwanden.","definition":"<p>Voorbeelden van <strong>type II</strong> zijn auto-immuunhemolyse, Goodpasture en de ziekte van Graves. Voorbeelden van <strong>type III</strong> zijn SLE, poststreptokokken-glomerulonefritis en serumziekte. Type I is IgE-gemedieerd (allergie), type IV T-celgemedieerd (contactallergie).</p>","image_url":"","wiki_title":"Hypersensitivity","match":"weefselgebonden antigenen|circulerende immuuncomplexen|type ii overgevoeligheid|type iii overgevoeligheid","option_only":true},"cd8+ cellen":{"title":"T-cellen (cytotoxisch en helper)","short":"Cytotoxische T-cellen (CD8) doden virus-geïnfecteerde cellen en tumorcellen die via MHC I een vreemd peptide tonen; T-helpercellen (CD4) sturen de afweerreactie via cytokines.","definition":"<p><strong>CD4-helpercellen</strong> herkennen antigeen op MHC II en splitsen zich in o.a. Th1 (macrofaagactivatie, intracellulaire bacteriën), Th2 (IgE, eosinofielen, parasieten), Th17 (neutrofielen, schimmels) en regulatoire T-cellen. Bij hiv daalt het aantal CD4-cellen.</p>","image_url":"","wiki_title":"T cell","match":"cd8+ cellen","option_only":true},"cd8-cellen":{"title":"T-cellen (cytotoxisch en helper)","short":"Cytotoxische T-cellen (CD8) doden virus-geïnfecteerde cellen en tumorcellen die via MHC I een vreemd peptide tonen; T-helpercellen (CD4) sturen de afweerreactie via cytokines.","definition":"<p><strong>CD4-helpercellen</strong> herkennen antigeen op MHC II en splitsen zich in o.a. Th1 (macrofaagactivatie, intracellulaire bacteriën), Th2 (IgE, eosinofielen, parasieten), Th17 (neutrofielen, schimmels) en regulatoire T-cellen. Bij hiv daalt het aantal CD4-cellen.</p>","image_url":"","wiki_title":"T cell","match":"cd8-cellen","option_only":true},"th1 lymfocyten":{"title":"T-cellen (cytotoxisch en helper)","short":"Cytotoxische T-cellen (CD8) doden virus-geïnfecteerde cellen en tumorcellen die via MHC I een vreemd peptide tonen; T-helpercellen (CD4) sturen de afweerreactie via cytokines.","definition":"<p><strong>CD4-helpercellen</strong> herkennen antigeen op MHC II en splitsen zich in o.a. Th1 (macrofaagactivatie, intracellulaire bacteriën), Th2 (IgE, eosinofielen, parasieten), Th17 (neutrofielen, schimmels) en regulatoire T-cellen. Bij hiv daalt het aantal CD4-cellen.</p>","image_url":"","wiki_title":"T cell","match":"th1 lymfocyten","option_only":true},"een abces":{"title":"Granuloom","short":"Een granuloom is een ophoping van geactiveerde macrofagen (epitheloïde cellen), vaak met reuscellen, rond een moeilijk afbreekbare prikkel.","definition":"<p><strong>Granulomen</strong> ontstaan bij tuberculose (met centrale verkazing), sarcoïdose, de ziekte van Crohn, schimmelinfecties en reacties op vreemd materiaal. Ze ontstaan via Th1-cellen en IFN-γ. Een abces bestaat juist uit granulocyten en pus.</p>","image_url":"","wiki_title":"Granuloma","match":"een abces","option_only":true},"een ulcus":{"title":"Granuloom","short":"Een granuloom is een ophoping van geactiveerde macrofagen (epitheloïde cellen), vaak met reuscellen, rond een moeilijk afbreekbare prikkel.","definition":"<p><strong>Granulomen</strong> ontstaan bij tuberculose (met centrale verkazing), sarcoïdose, de ziekte van Crohn, schimmelinfecties en reacties op vreemd materiaal. Ze ontstaan via Th1-cellen en IFN-γ. Een abces bestaat juist uit granulocyten en pus.</p>","image_url":"","wiki_title":"Granuloma","match":"een ulcus","option_only":true},"een necrosehaard":{"title":"Granuloom","short":"Een granuloom is een ophoping van geactiveerde macrofagen (epitheloïde cellen), vaak met reuscellen, rond een moeilijk afbreekbare prikkel.","definition":"<p><strong>Granulomen</strong> ontstaan bij tuberculose (met centrale verkazing), sarcoïdose, de ziekte van Crohn, schimmelinfecties en reacties op vreemd materiaal. Ze ontstaan via Th1-cellen en IFN-γ. Een abces bestaat juist uit granulocyten en pus.</p>","image_url":"","wiki_title":"Granuloma","match":"een necrosehaard","option_only":true},"tuberculeuze granulomen":{"title":"Granuloom","short":"Een granuloom is een ophoping van geactiveerde macrofagen (epitheloïde cellen), vaak met reuscellen, rond een moeilijk afbreekbare prikkel.","definition":"<p><strong>Granulomen</strong> ontstaan bij tuberculose (met centrale verkazing), sarcoïdose, de ziekte van Crohn, schimmelinfecties en reacties op vreemd materiaal. Ze ontstaan via Th1-cellen en IFN-γ. Een abces bestaat juist uit granulocyten en pus.</p>","image_url":"","wiki_title":"Granuloma","match":"tuberculeuze granulomen","option_only":true},"interleukine 5":{"title":"IL-4, IL-5 en IL-13 (type 2-cytokines)","short":"IL-4, IL-5 en IL-13 zijn cytokines van Th2-cellen die allergische ontsteking en de afweer tegen wormen sturen.","definition":"<p><strong>IL-4</strong> laat B-cellen overschakelen naar IgE, <strong>IL-5</strong> stimuleert eosinofielen, en IL-13 geeft slijmproductie en luchtweghyperreactiviteit. Biologicals tegen IL-5 (mepolizumab) en de IL-4-receptor (dupilumab) worden gebruikt bij ernstig astma en eczeem.</p>","image_url":"","wiki_title":"Interleukin 4","match":"interleukine 5","option_only":true},"leukotrieën b4":{"title":"Eicosanoïden","short":"Eicosanoïden (prostaglandinen, tromboxanen en leukotriënen) zijn ontstekingsmediatoren die uit arachidonzuur ontstaan.","definition":"<p>Via <strong>cyclo-oxygenase</strong> ontstaan prostaglandinen (PGE2: koorts, pijn; PGI2: vaatverwijding) en tromboxaan (plaatjesaggregatie). Via <strong>lipoxygenase</strong> ontstaan leukotriënen: LTB4 trekt neutrofielen aan, LTC4/D4/E4 geven bronchoconstrictie. PGD2 komt vrij uit mestcellen bij allergie.</p>","image_url":"","wiki_title":"Eicosanoid","match":"leukotrieën b4","option_only":true},"12-lipoxygenase":{"title":"Eicosanoïden","short":"Eicosanoïden (prostaglandinen, tromboxanen en leukotriënen) zijn ontstekingsmediatoren die uit arachidonzuur ontstaan.","definition":"<p>Via <strong>cyclo-oxygenase</strong> ontstaan prostaglandinen (PGE2: koorts, pijn; PGI2: vaatverwijding) en tromboxaan (plaatjesaggregatie). Via <strong>lipoxygenase</strong> ontstaan leukotriënen: LTB4 trekt neutrofielen aan, LTC4/D4/E4 geven bronchoconstrictie. PGD2 komt vrij uit mestcellen bij allergie.</p>","image_url":"","wiki_title":"Eicosanoid","match":"12-lipoxygenase","option_only":true},"mannose receptoren":{"title":"Patroonherkennende receptoren","short":"Scavenger- en mannosereceptoren op macrofagen herkennen moleculen op microben en beschadigde cellen en helpen ze op te nemen.","definition":"<p>Ze horen bij de <strong>patroonherkennende receptoren</strong> van de aangeboren afweer, net als Toll-like receptoren. Scavengerreceptoren nemen ook geoxideerd LDL op, waardoor bij atherosclerose schuimcellen ontstaan.</p>","image_url":"","wiki_title":"Scavenger receptor","match":"mannose receptoren","option_only":true},"a. temporalis superficialis":{"title":"A. facialis, a. temporalis superficialis en a. maxillaris","short":"De a. facialis, a. temporalis superficialis en a. maxillaris zijn slagaders van gezicht, schedel en kaak.","definition":"<p>De <strong>a. facialis</strong> is voelbaar aan de rand van de onderkaak voor de m. masseter. De <strong>a. temporalis superficialis</strong> is voelbaar voor het oor en is bij arteriitis temporalis verdikt en drukpijnlijk. De a. maxillaris geeft o.a. de a. meningea media af.</p>","image_url":"","wiki_title":"External carotid artery","match":"a. temporalis superficialis","option_only":true},"a. maxillaris":{"title":"A. facialis, a. temporalis superficialis en a. maxillaris","short":"De a. facialis, a. temporalis superficialis en a. maxillaris zijn slagaders van gezicht, schedel en kaak.","definition":"<p>De <strong>a. facialis</strong> is voelbaar aan de rand van de onderkaak voor de m. masseter. De <strong>a. temporalis superficialis</strong> is voelbaar voor het oor en is bij arteriitis temporalis verdikt en drukpijnlijk. De a. maxillaris geeft o.a. de a. meningea media af.</p>","image_url":"","wiki_title":"External carotid artery","match":"a. maxillaris","option_only":true},"hoog endotheel cellen":{"title":"Hoogendotheel-venulen (HEV)","short":"Hoogendotheel-venulen zijn speciale bloedvaten in lymfeklieren waardoor naïeve lymfocyten vanuit het bloed de klier binnengaan.","definition":"<p>Lymfocyten herkennen het endotheel van de <strong>HEV</strong> via L-selectine en chemokines (CCR7). Lymfatisch endotheel bekleedt daarentegen de lymfevaten die lymfe en dendritische cellen naar de klier voeren.</p>","image_url":"","wiki_title":"High endothelial venules","match":"hoog endotheel cellen","option_only":true},"opregulatie van selectines":{"title":"Adhesiemoleculen","short":"Adhesiemoleculen (selectines, integrines en ICAM's) zorgen ervoor dat leukocyten aan het endotheel binden en de bloedbaan kunnen verlaten.","definition":"<p>De migratie van leukocyten verloopt in stappen: rollen via <strong>selectines</strong>, stevig vasthechten via integrines aan ICAM-1/VCAM-1, en daarna diapedese door de vaatwand richting chemokines (chemotaxie). Bij een tekort aan integrines (LAD) ontstaan ernstige bacteriële infecties zonder pus.</p>","image_url":"","wiki_title":"Cell adhesion molecule","match":"opregulatie van selectines","option_only":true},"adhesie moleculen":{"title":"Adhesiemoleculen","short":"Adhesiemoleculen (selectines, integrines en ICAM's) zorgen ervoor dat leukocyten aan het endotheel binden en de bloedbaan kunnen verlaten.","definition":"<p>De migratie van leukocyten verloopt in stappen: rollen via <strong>selectines</strong>, stevig vasthechten via integrines aan ICAM-1/VCAM-1, en daarna diapedese door de vaatwand richting chemokines (chemotaxie). Bij een tekort aan integrines (LAD) ontstaan ernstige bacteriële infecties zonder pus.</p>","image_url":"","wiki_title":"Cell adhesion molecule","match":"adhesie moleculen","option_only":true},"adhesie moleculen en chemokines":{"title":"Adhesiemoleculen","short":"Adhesiemoleculen (selectines, integrines en ICAM's) zorgen ervoor dat leukocyten aan het endotheel binden en de bloedbaan kunnen verlaten.","definition":"<p>De migratie van leukocyten verloopt in stappen: rollen via <strong>selectines</strong>, stevig vasthechten via integrines aan ICAM-1/VCAM-1, en daarna diapedese door de vaatwand richting chemokines (chemotaxie). Bij een tekort aan integrines (LAD) ontstaan ernstige bacteriële infecties zonder pus.</p>","image_url":"","wiki_title":"Cell adhesion molecule","match":"adhesie moleculen en chemokines","option_only":true},"m17 macrofagen":{"title":"M1- en M2-macrofagen","short":"M1-macrofagen (klassiek geactiveerd, via IFN-γ) doden microben en geven ontsteking; M2-macrofagen (alternatief geactiveerd, via IL-4/IL-13) helpen bij weefselherstel en fibrose.","definition":"<p>Deze indeling is een vereenvoudiging van een spectrum aan <strong>macrofaagactivatie</strong>. Tumorgeassocieerde macrofagen lijken vaak op M2-macrofagen en kunnen de tumorgroei bevorderen.</p>","image_url":"","wiki_title":"Macrophage polarization","match":"m17 macrofagen","option_only":true},"circulerende immuuncomplexen":{"title":"Overgevoeligheidsreacties type II en III","short":"Bij een type II-overgevoeligheid richten antistoffen zich tegen antigenen op cellen of in weefsel; bij type III slaan immuuncomplexen uit de circulatie neer in vaatwanden.","definition":"<p>Voorbeelden van <strong>type II</strong> zijn auto-immuunhemolyse, Goodpasture en de ziekte van Graves. Voorbeelden van <strong>type III</strong> zijn SLE, poststreptokokken-glomerulonefritis en serumziekte. Type I is IgE-gemedieerd (allergie), type IV T-celgemedieerd (contactallergie).</p>","image_url":"","wiki_title":"Hypersensitivity","match":"circulerende immuuncomplexen","option_only":true},"alcoholische levercirrose":{"title":"Levercirrose","short":"Bij levercirrose is het leverweefsel vervangen door bindweefsel en regeneratieknobbels, met verlies van leverfunctie en portale hypertensie.","definition":"<p>Oorzaken van <strong>cirrose</strong> zijn o.a. alcohol, NASH, chronische hepatitis B en C, auto-immuunziekten en hemochromatose. Gevolgen: ascites, varices met bloedingen, hepatische encefalopathie, icterus, stollingsstoornissen en een verhoogd risico op hepatocellulair carcinoom. Ernst wordt ingedeeld met Child-Pugh of MELD.</p>","image_url":"","wiki_title":"Cirrhosis","match":"alcoholische levercirrose","option_only":true},"bloedkweken":{"title":"Bloedkweek","short":"Een bloedkweek onderzoekt of er bacteriën of schimmels in het bloed zitten (bacteriëmie).","definition":"<p>Bij verdenking op sepsis of endocarditis worden minimaal twee sets <strong>bloedkweken</strong> afgenomen vóór het starten van antibiotica. Een kweek met huidbacteriën (bijv. coagulasenegatieve stafylokokken) in één fles is vaak een verontreiniging.</p>","image_url":"","wiki_title":"Blood culture","match":"bloedkweken","option_only":true},"bacteriele tonsillitis":{"title":"Tonsillitis","short":"Tonsillitis is een ontsteking van de keelamandelen, meestal viraal, soms door groep A-streptokokken.","definition":"<p>Bij <strong>tonsillitis</strong> zijn de amandelen rood en gezwollen, soms met beslag, en zijn er keelpijn, slikklachten en koorts. Meestal gaat het om een virus (ook EBV). Bij een bacteriële oorzaak gaat het vaak om groep A-streptokokken. Complicaties zijn een peritonsillair abces (met trismus en uitpuilen van het gehemelte) en zelden acuut reuma.</p>","image_url":"","wiki_title":"Tonsillitis","match":"bacteriele tonsillitis","option_only":true},"stafylokok":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"stafylokok","option_only":true},"lymfeadenitis colli":{"title":"Lymfadenitis colli","short":"Lymfadenitis colli is een ontsteking van de lymfeklieren in de hals, o.a. bij tuberculose of kattenkrabziekte.","definition":"<p><strong>Lymfadenitis colli</strong> is een halsklierontsteking die kan verkleven met de huid en abcederen; ze komt onder meer voor bij tuberculose en de kattenkrabziekte.</p>","image_url":"","wiki_title":"","match":"lymfeadenitis colli","option_only":true},"ziekte van waldenström":{"title":"Ziekte van Waldenström","short":"De ziekte van Waldenström is een lymfoplasmacytair lymfoom dat een monoklonaal IgM maakt.","definition":"<p>Het hoge <strong>IgM</strong> kan een hyperviscositeitssyndroom geven (hoofdpijn, gezichtsstoornissen, bloedingen), en daarnaast neuropathie, cryoglobulinemie en koude-agglutinatie. Een MYD88-mutatie is kenmerkend.</p>","image_url":"","wiki_title":"Waldenström macroglobulinemia","match":"ziekte van waldenström|de ziekte van waldenström|macroglobulinemie","option_only":true},"crest-syndroom":{"title":"CREST-syndroom (gelimiteerde systemische sclerose)","short":"Het CREST-syndroom is een vorm van systemische sclerose met calcinose, Raynaud, slokdarmstoornissen, sclerodactylie en teleangiëctasieën.","definition":"<p>Bij deze <strong>gelimiteerde vorm</strong> zijn anticentromeerantistoffen kenmerkend. Er is een risico op pulmonale arteriële hypertensie. Bij de diffuse vorm (anti-Scl-70) staan longfibrose en nierproblemen meer op de voorgrond.</p>","image_url":"","wiki_title":"CREST syndrome","match":"crest-syndroom|het crest syndroom|crest","option_only":true},"bence-jonesproteïne":{"title":"Bence Jones-eiwit","short":"Bence Jones-eiwit bestaat uit vrije lichte ketens van immunoglobulinen in de urine, vooral bij een multipel myeloom.","definition":"<p>Lichte ketens worden gefiltreerd en kunnen in de tubuli neerslaan (myeloomnier). Ze worden niet altijd gezien met een gewone urinestick, maar wel met elektroforese of een bepaling van vrije lichte ketens in serum.</p>","image_url":"","wiki_title":"Bence Jones protein","match":"bence-jonesproteïne|bence jones|de ziekte van bence-jones|vrije lichte ketens","option_only":true},"myasthenia gravis":{"title":"Myasthenia gravis","short":"Myasthenia gravis is een auto-immuunziekte waarbij antistoffen de acetylcholinereceptoren van de motorische eindplaat blokkeren, met een spierzwakte die toeneemt bij inspanning.","definition":"<p>Vaak begint <strong>myasthenia gravis</strong> met ptosis en dubbelzien; later kunnen slikken, praten en ademhalen zwak worden (myasthene crisis). Naast anti-AChR komen anti-MuSK-antistoffen voor. Er is een samenhang met een thymoom. Behandeling: pyridostigmine, immunosuppressie, thymectomie.</p>","image_url":"","wiki_title":"Myasthenia gravis","match":"myasthenia gravis|antistoffen tegen acetylcholinereceptor|anti-achr","option_only":true},"wegener granulomatose":{"title":"Granulomatose met polyangiitis (GPA)","short":"GPA is een ANCA-geassocieerde vasculitis van kleine vaten met granulomen, vooral in bovenste luchtwegen, longen en nieren.","definition":"<p>Bij <strong>GPA</strong> zijn er klachten van neus en bijholten (korsten, bloedingen, zadelneus), longnoduli of -bloedingen en een snel progressieve glomerulonefritis. Meestal zijn er c-ANCA (anti-PR3). Behandeling met hoge dosis corticosteroïden en rituximab of cyclofosfamide.</p>","image_url":"","wiki_title":"Granulomatosis with polyangiitis","match":"wegener granulomatose","option_only":true},"bulleus pemphigoid":{"title":"Bulleus pemfigoïd","short":"Bulleus pemfigoïd is een auto-immuunblaarziekte bij ouderen, met jeukende, strakke blaren door antistoffen tegen hemidesmosomen.","definition":"<p>Bij <strong>bulleus pemfigoïd</strong> (antistoffen tegen BP180 en BP230) ligt de splijting onder de epidermis, waardoor de blaren stevig zijn. Er gaat vaak een lange jeukende fase vooraf. Het slijmvlies is meestal gespaard, anders dan bij pemphigus vulgaris. Behandeling met sterke lokale of systemische corticosteroïden.</p>","image_url":"","wiki_title":"Bullous pemphigoid","match":"bulleus pemphigoid","option_only":true},"de ziekte van waldenström":{"title":"Ziekte van Waldenström","short":"De ziekte van Waldenström is een lymfoplasmacytair lymfoom dat een monoklonaal IgM maakt.","definition":"<p>Het hoge <strong>IgM</strong> kan een hyperviscositeitssyndroom geven (hoofdpijn, gezichtsstoornissen, bloedingen), en daarnaast neuropathie, cryoglobulinemie en koude-agglutinatie. Een MYD88-mutatie is kenmerkend.</p>","image_url":"","wiki_title":"Waldenström macroglobulinemia","match":"de ziekte van waldenström","option_only":true},"het crest syndroom":{"title":"CREST-syndroom (gelimiteerde systemische sclerose)","short":"Het CREST-syndroom is een vorm van systemische sclerose met calcinose, Raynaud, slokdarmstoornissen, sclerodactylie en teleangiëctasieën.","definition":"<p>Bij deze <strong>gelimiteerde vorm</strong> zijn anticentromeerantistoffen kenmerkend. Er is een risico op pulmonale arteriële hypertensie. Bij de diffuse vorm (anti-Scl-70) staan longfibrose en nierproblemen meer op de voorgrond.</p>","image_url":"","wiki_title":"CREST syndrome","match":"het crest syndroom","option_only":true},"de ziekte van bence-jones":{"title":"Bence Jones-eiwit","short":"Bence Jones-eiwit bestaat uit vrije lichte ketens van immunoglobulinen in de urine, vooral bij een multipel myeloom.","definition":"<p>Lichte ketens worden gefiltreerd en kunnen in de tubuli neerslaan (myeloomnier). Ze worden niet altijd gezien met een gewone urinestick, maar wel met elektroforese of een bepaling van vrije lichte ketens in serum.</p>","image_url":"","wiki_title":"Bence Jones protein","match":"de ziekte van bence-jones","option_only":true},"antistoffen tegen acetylcholinereceptor":{"title":"Myasthenia gravis","short":"Myasthenia gravis is een auto-immuunziekte waarbij antistoffen de acetylcholinereceptoren van de motorische eindplaat blokkeren, met een spierzwakte die toeneemt bij inspanning.","definition":"<p>Vaak begint <strong>myasthenia gravis</strong> met ptosis en dubbelzien; later kunnen slikken, praten en ademhalen zwak worden (myasthene crisis). Naast anti-AChR komen anti-MuSK-antistoffen voor. Er is een samenhang met een thymoom. Behandeling: pyridostigmine, immunosuppressie, thymectomie.</p>","image_url":"","wiki_title":"Myasthenia gravis","match":"antistoffen tegen acetylcholinereceptor","option_only":true}};
